window.smartMoveQuestions = [{"subject":"biology","q":"Why is it important to define a problem clearly before starting an investigation?","options":["To make the report longer","To know exactly what needs to be solved","To reduce the number of observations","To avoid collecting data"],"answer":1,"explanation":"Defining a problem clearly helps focus the investigation and identify appropriate methods for finding a solution."},{"subject":"biology","q":"Which step comes immediately after identifying a problem?","options":["Writing a report","Gathering information","Defining the problem","Drawing conclusions"],"answer":2,"explanation":"Once a problem is identified, it must be clearly stated before information is collected."},{"subject":"biology","q":"Why is information gathered before testing a solution?","options":["To understand possible causes and solutions","To avoid experiments","To increase costs","To replace observations"],"answer":0,"explanation":"Information helps researchers understand the problem and identify suitable solutions."},{"subject":"biology","q":"What is the purpose of using a sample during an investigation?","options":["To increase errors","To test a solution before applying it to a larger population","To replace data collection","To reduce conclusions"],"answer":1,"explanation":"Testing on a sample helps determine whether a solution is effective before large-scale implementation."},{"subject":"biology","q":"Which of the following should be included in a scientific report?","options":["Rumours","Personal opinions only","Aim, method, results and conclusions","Guesses only"],"answer":2,"explanation":"A scientific report should clearly state the aim, method, findings and conclusions."},{"subject":"biology","q":"Why is alcohol heated using a water bath instead of a direct flame?","options":["Alcohol is expensive","Alcohol is flammable","Alcohol is poisonous","Alcohol evaporates slowly"],"answer":1,"explanation":"Alcohol catches fire easily and must therefore be heated indirectly using a water bath."},{"subject":"biology","q":"What happens to a green leaf when it is boiled in alcohol?","options":["It becomes larger","It becomes colourless","It becomes blue-black","It becomes yellow immediately"],"answer":1,"explanation":"Chlorophyll dissolves in alcohol, leaving the leaf decolourised."},{"subject":"biology","q":"What causes lime water to turn milky during fermentation?","options":["Oxygen","Nitrogen","Carbon dioxide","Water vapour"],"answer":2,"explanation":"Carbon dioxide reacts with lime water producing a milky appearance."},{"subject":"biology","q":"Why is warm water used when fermenting sugar with yeast?","options":["To kill yeast","To increase the rate of enzyme activity","To remove carbon dioxide","To produce oxygen"],"answer":1,"explanation":"Warm temperatures increase enzyme activity, making fermentation faster."},{"subject":"biology","q":"What group of organisms does yeast belong to?","options":["Bacteria","Fungi","Plants","Protozoa"],"answer":1,"explanation":"Yeast is a fungus used in fermentation processes."},{"subject":"biology","q":"What is photosynthesis?","options":["Breakdown of food to release energy","Process by which green plants make food using light energy","Movement of water through xylem","Loss of water from leaves"],"answer":1,"explanation":"Photosynthesis enables green plants to manufacture food using carbon dioxide, water and light."},{"subject":"biology","q":"Which part of the leaf contains the greatest number of chloroplasts?","options":["Cuticle","Upper epidermis","Palisade mesophyll","Xylem"],"answer":2,"explanation":"Palisade mesophyll cells are packed with chloroplasts and are the main site of photosynthesis."},{"subject":"biology","q":"Which gas enters a leaf during photosynthesis?","options":["Oxygen","Nitrogen","Carbon dioxide","Hydrogen"],"answer":2,"explanation":"Carbon dioxide enters the leaf through stomata and is used to make glucose."},{"subject":"biology","q":"What is the main function of stomata?","options":["Transport food","Absorb minerals","Gaseous exchange","Produce chlorophyll"],"answer":2,"explanation":"Stomata allow carbon dioxide to enter and oxygen to leave the leaf."},{"subject":"biology","q":"Why are leaves usually broad?","options":["To store water","To increase surface area for absorbing light","To reduce photosynthesis","To transport food faster"],"answer":1,"explanation":"A broad surface allows more sunlight to be absorbed for photosynthesis."},{"subject":"biology","q":"What is the function of xylem in a leaf?","options":["Transport food","Transport hormones","Transport water and mineral salts","Store starch"],"answer":2,"explanation":"Xylem carries water and mineral salts from the roots to the leaf."},{"subject":"biology","q":"What is the role of phloem?","options":["Carry oxygen","Carry water","Transport manufactured food","Open stomata"],"answer":2,"explanation":"Phloem transports food made during photosynthesis to other parts of the plant."},{"subject":"biology","q":"In which organelle does photosynthesis take place?","options":["Nucleus","Mitochondrion","Chloroplast","Ribosome"],"answer":2,"explanation":"Chloroplasts contain chlorophyll and are the site of photosynthesis."},{"subject":"biology","q":"What mineral element is necessary for chlorophyll formation?","options":["Calcium","Sodium","Magnesium","Zinc"],"answer":2,"explanation":"Magnesium forms an essential part of the chlorophyll molecule."},{"subject":"biology","q":"Why is photosynthesis important to living things?","options":["It produces oxygen and food","It causes diseases","It increases carbon dioxide levels","It prevents respiration"],"answer":0,"explanation":"Photosynthesis provides food for ecosystems and releases oxygen needed for respiration."},{"subject":"biology","q":"Why is it important to observe safety measures when carrying out laboratory investigations?","options":["To make experiments longer","To prevent accidents and injuries","To increase costs","To avoid recording results"],"answer":1,"explanation":"Safety measures protect learners, equipment, and laboratory materials from accidents and damage."},{"subject":"biology","q":"Why is a wire gauze placed between a beaker and a flame during heating?","options":["To make water boil faster","To change the colour of the beaker","To protect the glass from direct heat","To increase the temperature"],"answer":2,"explanation":"The wire gauze distributes heat evenly and prevents the glass from cracking due to direct heating."},{"subject":"biology","q":"Why should alcohol not be heated directly over a flame?","options":["It is expensive","It is acidic","It is flammable","It evaporates slowly"],"answer":2,"explanation":"Alcohol catches fire easily, so it is heated using a water bath instead of a direct flame."},{"subject":"biology","q":"What is the name given to a beaker containing hot water used to heat another substance?","options":["Condenser","Water bath","Evaporating dish","Filter funnel"],"answer":1,"explanation":"A water bath provides indirect heating for substances that cannot be heated directly."},{"subject":"biology","q":"Which observation proves that chlorophyll dissolves in alcohol?","options":["The alcohol freezes","The alcohol changes colour to green","The leaf becomes larger","Water turns yellow"],"answer":1,"explanation":"Chlorophyll leaves the leaf and dissolves into the alcohol, causing the alcohol to become green."},{"subject":"biology","q":"Why is yeast added to a sugar solution during a fermentation experiment?","options":["To produce oxygen","To absorb water","To cause fermentation","To cool the solution"],"answer":2,"explanation":"Yeast contains enzymes that break down sugar and release carbon dioxide during fermentation."},{"subject":"biology","q":"What type of organism is yeast?","options":["Bacterium","Fungus","Virus","Protozoan"],"answer":1,"explanation":"Yeast belongs to the fungi and is commonly used in fermentation experiments."},{"subject":"biology","q":"Which gas causes lime water to turn milky?","options":["Oxygen","Nitrogen","Hydrogen","Carbon dioxide"],"answer":3,"explanation":"Carbon dioxide reacts with lime water producing a milky appearance."},{"subject":"biology","q":"Why is warm water used when preparing a yeast fermentation experiment?","options":["To increase enzyme activity","To destroy yeast cells","To remove glucose","To stop respiration"],"answer":0,"explanation":"Warm temperatures increase the rate at which yeast enzymes work."},{"subject":"biology","q":"What is the main function of a microscope?","options":["To weigh substances","To heat substances","To observe tiny organisms and structures","To test gases"],"answer":2,"explanation":"A microscope magnifies very small structures that cannot be seen clearly with the naked eye."},{"subject":"biology","q":"What part of an onion is commonly examined under a microscope to study cells?","options":["Root cap","Epidermis","Stem","Flower"],"answer":1,"explanation":"The onion epidermis consists of a thin layer of cells that can easily be observed under a microscope."},{"subject":"biology","q":"Why is a cover slip placed over a specimen on a slide?","options":["To colour cells","To hold the specimen flat and protect it","To increase temperature","To absorb water"],"answer":1,"explanation":"A cover slip keeps the specimen in position and improves viewing under a microscope."},{"subject":"biology","q":"What happens to the number of cells visible when magnification increases?","options":["More cells become visible","The number stays the same","Fewer cells become visible","Cells disappear completely"],"answer":2,"explanation":"Increased magnification reduces the field of view, so fewer cells can be seen."},{"subject":"biology","q":"Why do cells appear more detailed under higher magnification?","options":["They become larger naturally","More details are enlarged and visible","They absorb stain better","The microscope adds structures"],"answer":1,"explanation":"Higher magnification enlarges cell structures, making details easier to observe."},{"subject":"biology","q":"Why is pond water examined under a microscope?","options":["To measure temperature","To identify tiny organisms living in water","To determine acidity only","To make distilled water"],"answer":1,"explanation":"Many microscopic organisms in pond water can only be observed using a microscope."},{"subject":"biology","q":"Which type of structure helps some microscopic organisms move in water?","options":["Cell wall","Chloroplast","Whip-like structures","Vacuole"],"answer":2,"explanation":"Some organisms use whip-like structures such as flagella for movement."},{"subject":"biology","q":"Why are observations recorded during an investigation?","options":["To replace conclusions","To provide evidence for results and conclusions","To avoid experiments","To increase laboratory costs"],"answer":1,"explanation":"Observations provide the data needed to support scientific conclusions."},{"subject":"biology","q":"What is the purpose of a hypothesis in an investigation?","options":["To state a prediction that can be tested","To record final results","To replace observations","To write a report"],"answer":0,"explanation":"A hypothesis is a testable statement predicting what may happen during an investigation."},{"subject":"biology","q":"Why should only one variable be changed during an experiment?","options":["To make the experiment complicated","To identify the effect of that variable clearly","To increase temperature","To reduce measurements"],"answer":1,"explanation":"Changing only one variable ensures that observed changes can be linked to that factor."},{"subject":"biology","q":"What is the final step after collecting data and drawing conclusions?","options":["Repeating the experiment forever","Destroying equipment","Writing a report","Ignoring the results"],"answer":2,"explanation":"A scientific report communicates the aim, method, results and conclusions of the investigation."},{"subject":"biology","q":"What is photosynthesis?","options":["The breakdown of food to release energy","The process by which green plants make food using light energy","The movement of water through plants","The loss of water from leaves"],"answer":1,"explanation":"Photosynthesis is the process whereby green plants use sunlight, water, and carbon dioxide to manufacture food (glucose)."},{"subject":"biology","q":"Which gas is required for photosynthesis?","options":["Oxygen","Nitrogen","Carbon dioxide","Hydrogen"],"answer":2,"explanation":"Carbon dioxide enters the leaf through stomata and is used to make glucose."},{"subject":"biology","q":"Which substance is absorbed by roots and used during photosynthesis?","options":["Starch","Water","Oxygen","Sucrose"],"answer":1,"explanation":"Water absorbed by roots is transported to the leaves where it is used in photosynthesis."},{"subject":"biology","q":"Which pigment absorbs light energy during photosynthesis?","options":["Hemoglobin","Chlorophyll","Keratin","Melanin"],"answer":1,"explanation":"Chlorophyll is the green pigment that traps light energy."},{"subject":"biology","q":"Which part of the leaf contains the largest number of chloroplasts?","options":["Lower epidermis","Xylem","Palisade mesophyll","Phloem"],"answer":2,"explanation":"Palisade cells contain many chloroplasts and are the main site of photosynthesis."},{"subject":"biology","q":"Why are leaves usually broad?","options":["To store food","To increase absorption of light","To reduce water uptake","To increase weight"],"answer":1,"explanation":"A broad surface area allows leaves to absorb more sunlight."},{"subject":"biology","q":"Why are leaves usually thin?","options":["To reduce transport of water","To shorten the diffusion distance of gases","To increase weight","To store starch"],"answer":1,"explanation":"Thin leaves allow carbon dioxide and oxygen to move quickly through the leaf."},{"subject":"biology","q":"What is the function of stomata?","options":["Absorb minerals","Transport food","Allow gaseous exchange","Produce chlorophyll"],"answer":2,"explanation":"Stomata allow carbon dioxide to enter and oxygen to leave the leaf."},{"subject":"biology","q":"Which tissue transports water into the leaf?","options":["Phloem","Cortex","Xylem","Epidermis"],"answer":2,"explanation":"Xylem transports water and dissolved mineral salts from roots to leaves."},{"subject":"biology","q":"Which tissue transports manufactured food away from the leaf?","options":["Xylem","Phloem","Epidermis","Cuticle"],"answer":1,"explanation":"Phloem carries sugars produced during photosynthesis to other parts of the plant."},{"subject":"biology","q":"What is the main function of the cuticle?","options":["Transport water","Prevent excessive water loss","Produce food","Store minerals"],"answer":1,"explanation":"The waxy cuticle reduces water loss from the leaf surface."},{"subject":"biology","q":"Which organelle is the site of photosynthesis?","options":["Mitochondrion","Ribosome","Chloroplast","Nucleus"],"answer":2,"explanation":"Photosynthesis occurs inside chloroplasts."},{"subject":"biology","q":"In which part of the chloroplast does the light stage occur?","options":["Cell wall","Stroma","Grana","Vacuole"],"answer":2,"explanation":"The light-dependent stage takes place in the grana where chlorophyll is located."},{"subject":"biology","q":"In which part of the chloroplast does the dark stage occur?","options":["Grana","Stroma","Cell membrane","Nucleus"],"answer":1,"explanation":"Carbon dioxide fixation and glucose formation occur in the stroma."},{"subject":"biology","q":"What is photolysis?","options":["Formation of glucose","Splitting of water using light energy","Storage of starch","Breakdown of proteins"],"answer":1,"explanation":"Light energy splits water molecules into hydrogen and oxygen."},{"subject":"biology","q":"What happens to the oxygen produced during photolysis?","options":["It is converted into starch","It is released through stomata","It becomes chlorophyll","It forms cellulose"],"answer":1,"explanation":"Oxygen is released as a by-product of photosynthesis."},{"subject":"biology","q":"What is the role of hydrogen produced during photolysis?","options":["Makes proteins directly","Combines with carbon dioxide to form glucose","Opens stomata","Forms xylem vessels"],"answer":1,"explanation":"Hydrogen is used during the dark stage to form glucose."},{"subject":"biology","q":"Which mineral element is essential for chlorophyll formation?","options":["Calcium","Magnesium","Sodium","Potassium"],"answer":1,"explanation":"Magnesium is a key component of chlorophyll molecules."},{"subject":"biology","q":"Why is photosynthesis important to animals?","options":["Animals perform photosynthesis","It provides food and oxygen","It removes water from soil","It produces diseases"],"answer":1,"explanation":"Photosynthesis provides oxygen for respiration and forms the basis of food chains."},{"subject":"biology","q":"What is the main product of photosynthesis?","options":["Carbon dioxide","Glucose","Nitrogen","Ammonia"],"answer":1,"explanation":"Glucose is the food produced by plants during photosynthesis and can be converted into starch, proteins, or lipids."},{"subject":"biology","q":"What is transport in plants?","options":["The manufacture of food","Movement of substances from one part of a plant to another","Growth of roots","Germination of seeds"],"answer":1,"explanation":"Transport is the movement of water, mineral salts, and manufactured food substances within a plant."},{"subject":"biology","q":"Which structures are mainly responsible for transport in plants?","options":["Stomata","Chloroplasts","Vascular bundles","Epidermis"],"answer":2,"explanation":"Vascular bundles contain xylem and phloem tissues responsible for transport."},{"subject":"biology","q":"Which tissue transports water and mineral salts?","options":["Phloem","Cortex","Xylem","Epidermis"],"answer":2,"explanation":"Xylem carries water and dissolved mineral salts from roots to leaves."},{"subject":"biology","q":"Which tissue transports manufactured food substances?","options":["Xylem","Phloem","Endodermis","Cortex"],"answer":1,"explanation":"Phloem carries sugars and other food products from leaves to the rest of the plant."},{"subject":"biology","q":"What is a major structural difference between xylem and phloem?","options":["Xylem is living while phloem is dead","Xylem is dead while phloem is living","Both are dead","Both are living"],"answer":1,"explanation":"Mature xylem tissues are dead, while phloem tissues remain living."},{"subject":"biology","q":"What substance strengthens xylem walls?","options":["Chlorophyll","Cellulose only","Lignin","Starch"],"answer":2,"explanation":"Lignin strengthens xylem vessels and helps support the plant."},{"subject":"biology","q":"Why are xylem vessels suitable for transporting water?","options":["They contain chloroplasts","They are hollow and continuous","They have large nuclei","They contain food reserves"],"answer":1,"explanation":"Their hollow nature allows water to move easily with little resistance."},{"subject":"biology","q":"What is translocation?","options":["Movement of water in xylem","Movement of organic food substances in phloem","Absorption of minerals","Movement of oxygen"],"answer":1,"explanation":"Translocation refers to transport of manufactured food substances through the phloem."},{"subject":"biology","q":"Which cells are closely associated with sieve tubes?","options":["Palisade cells","Companion cells","Guard cells","Cortex cells"],"answer":1,"explanation":"Companion cells provide energy and support to sieve tube elements."},{"subject":"biology","q":"In the ringing experiment, why does swelling occur above the removed bark?","options":["Water accumulates there","Mineral salts accumulate there","Food accumulates above the cut phloem","Air accumulates there"],"answer":2,"explanation":"Food transported through the phloem cannot move past the ringed section and accumulates above it."},{"subject":"biology","q":"What is diffusion?","options":["Movement of particles from low concentration to high concentration","Movement of particles from high concentration to low concentration","Movement of water only","Movement requiring energy"],"answer":1,"explanation":"Diffusion occurs down a concentration gradient."},{"subject":"biology","q":"Which factor increases the rate of diffusion?","options":["Lower temperature","Larger molecules","Higher temperature","Lower concentration gradient"],"answer":2,"explanation":"Higher temperatures increase particle movement and speed up diffusion."},{"subject":"biology","q":"What is osmosis?","options":["Movement of food substances","Movement of water through a semi-permeable membrane","Movement requiring ATP","Movement of gases"],"answer":1,"explanation":"Osmosis is the diffusion of water molecules through a semi-permeable membrane."},{"subject":"biology","q":"What is a solute?","options":["A liquid that dissolves substances","A dissolved substance","Pure water","A membrane"],"answer":1,"explanation":"A solute is the substance dissolved in a solvent to form a solution."},{"subject":"biology","q":"What is active transport?","options":["Movement down a concentration gradient","Movement of water molecules only","Movement against a concentration gradient using energy","Passive movement of gases"],"answer":2,"explanation":"Active transport uses energy from respiration to move substances against their concentration gradient."},{"subject":"biology","q":"Which cell organelle provides energy for active transport?","options":["Chloroplast","Vacuole","Mitochondrion","Nucleus"],"answer":2,"explanation":"Mitochondria release energy during respiration, which powers active transport."},{"subject":"biology","q":"What is transpiration?","options":["Movement of food in phloem","Loss of water vapour from plant surfaces","Absorption of minerals","Formation of glucose"],"answer":1,"explanation":"Transpiration is the evaporation of water from plant surfaces, mainly through leaves."},{"subject":"biology","q":"What is the transpiration stream?","options":["Flow of food through phloem","Continuous flow of water through the plant due to transpiration","Movement of oxygen through stomata","Diffusion of carbon dioxide"],"answer":1,"explanation":"Water moves from roots to leaves in a continuous stream because of transpiration."},{"subject":"biology","q":"Which environmental condition causes the highest rate of transpiration?","options":["Cold, humid, still air","Hot, windy, dry air","Cold, windy, humid air","Wet conditions"],"answer":1,"explanation":"High temperature, low humidity, and air movement increase water loss from leaves."},{"subject":"biology","q":"Why is transpiration important to plants?","options":["It destroys mineral salts","It cools the plant and helps transport water and minerals","It prevents photosynthesis","It reduces water uptake"],"answer":1,"explanation":"Transpiration cools plants, assists in mineral transport, and promotes water uptake from the soil."},{"subject":"biology","q":"What is digestion?","options":["Absorption of nutrients into blood","Breakdown of complex food substances into simple soluble forms","Elimination of waste products","Transportation of food around the body"],"answer":1,"explanation":"Digestion is the process by which large, complex food molecules are broken down into smaller soluble molecules that can be absorbed."},{"subject":"biology","q":"Which nutrient is the body\u0027s main source of energy?","options":["Proteins","Vitamins","Carbohydrates","Mineral salts"],"answer":2,"explanation":"Carbohydrates are broken down to glucose, which is used in respiration to release energy."},{"subject":"biology","q":"Which carbohydrate forms part of plant cell walls?","options":["Starch","Sucrose","Cellulose","Glucose"],"answer":2,"explanation":"Cellulose provides strength and support to plant cell walls."},{"subject":"biology","q":"Which protein transports oxygen in the blood?","options":["Insulin","Keratin","Haemoglobin","Collagen"],"answer":2,"explanation":"Haemoglobin is found in red blood cells and carries oxygen from the lungs to body tissues."},{"subject":"biology","q":"Which nutrient provides insulation beneath the skin?","options":["Vitamins","Proteins","Lipids (fats)","Water"],"answer":2,"explanation":"Fat beneath the skin helps reduce heat loss from the body."},{"subject":"biology","q":"Which vitamin is important for healthy vision?","options":["Vitamin A","Vitamin BÃ¢â€šÂ","Vitamin C","Vitamin K"],"answer":0,"explanation":"Vitamin A helps maintain healthy vision and epithelial tissues."},{"subject":"biology","q":"Which vitamin is important for blood clotting?","options":["Vitamin C","Vitamin D","Vitamin K","Vitamin BÃ¢â€šâ€š"],"answer":2,"explanation":"Vitamin K is necessary for the formation of substances involved in blood clotting."},{"subject":"biology","q":"Why is water important in the body?","options":["It only cools the body","It dissolves and transports substances","It replaces proteins","It produces enzymes"],"answer":1,"explanation":"Water acts as a solvent and transport medium for digested food, wastes, and gases."},{"subject":"biology","q":"Which enzyme is found in saliva?","options":["Pepsin","Trypsin","Salivary amylase (ptyalin)","Lipase"],"answer":2,"explanation":"Salivary amylase begins carbohydrate digestion by converting starch into maltose."},{"subject":"biology","q":"What is the product of starch digestion by salivary amylase?","options":["Glucose","Maltose","Fructose","Sucrose"],"answer":1,"explanation":"Salivary amylase breaks starch into maltose."},{"subject":"biology","q":"Which enzyme digests proteins in the stomach?","options":["Lipase","Amylase","Pepsin","Lactase"],"answer":2,"explanation":"Pepsin breaks down proteins into smaller polypeptides in the stomach."},{"subject":"biology","q":"What is the main role of rennin in young mammals?","options":["Digests starch","Coagulates milk protein","Digests fats","Absorbs nutrients"],"answer":1,"explanation":"Rennin converts soluble caseinogen into insoluble casein, allowing milk digestion."},{"subject":"biology","q":"Which organ produces pancreatic juice?","options":["Liver","Stomach","Pancreas","Large intestine"],"answer":2,"explanation":"The pancreas secretes digestive enzymes into the small intestine."},{"subject":"biology","q":"What does lipase break down?","options":["Proteins","Lipids (fats)","Starch","Maltose"],"answer":1,"explanation":"Lipase digests lipids into fatty acids and glycerol."},{"subject":"biology","q":"What are the final products of protein digestion?","options":["Glucose and fructose","Fatty acids and glycerol","Amino acids","Maltose"],"answer":2,"explanation":"Proteins are broken down into amino acids, which can be absorbed by the body."},{"subject":"biology","q":"Where does most absorption of digested food occur?","options":["Mouth","Stomach","Ileum (small intestine)","Rectum"],"answer":2,"explanation":"The ileum is specialised for the absorption of digested nutrients."},{"subject":"biology","q":"Which structures increase the surface area for absorption in the ileum?","options":["Stomata","Villi","Alveoli","Nephrons"],"answer":1,"explanation":"Villi and microvilli greatly increase the absorption surface area."},{"subject":"biology","q":"What is the main function of the large intestine?","options":["Digestion of proteins","Absorption of water","Production of bile","Storage of glucose"],"answer":1,"explanation":"The large intestine absorbs water and forms faeces."},{"subject":"biology","q":"What is the role of bile in digestion?","options":["Digests proteins","Digests glucose","Emulsifies fats into smaller droplets","Absorbs nutrients"],"answer":2,"explanation":"Bile breaks large fat globules into smaller droplets, increasing the surface area for lipase action."},{"subject":"biology","q":"Which condition occurs when a person passes hard faeces infrequently?","options":["Diarrhoea","Ulcer","Indigestion","Constipation"],"answer":3,"explanation":"Constipation occurs when faeces remain too long in the large intestine, causing excessive water absorption and hardening."},{"subject":"biology","q":"What is the main function of the circulatory system?","options":["Digestion of food","Transport of substances around the body","Reproduction","Excretion only"],"answer":1,"explanation":"The circulatory system transports oxygen, nutrients, hormones, and waste products throughout the body."},{"subject":"biology","q":"Which blood vessel carries blood away from the heart?","options":["Vein","Capillary","Artery","Venule"],"answer":2,"explanation":"Arteries carry blood away from the heart under high pressure."},{"subject":"biology","q":"Which blood vessel carries blood back to the heart?","options":["Artery","Vein","Capillary","Aorta"],"answer":1,"explanation":"Veins return blood from body tissues to the heart."},{"subject":"biology","q":"What is the main function of red blood cells?","options":["Fight infections","Carry oxygen","Produce hormones","Form antibodies"],"answer":1,"explanation":"Red blood cells transport oxygen from the lungs to body tissues."},{"subject":"biology","q":"Which substance in red blood cells carries oxygen?","options":["Plasma","Antibody","Haemoglobin","Fibrin"],"answer":2,"explanation":"Haemoglobin combines with oxygen to form oxyhaemoglobin."},{"subject":"biology","q":"Why do red blood cells lack a nucleus?","options":["To reduce their weight","To create space for more haemoglobin","To absorb water","To store food"],"answer":1,"explanation":"The absence of a nucleus allows more haemoglobin to be packed inside the cell."},{"subject":"biology","q":"Which blood cells defend the body against infection?","options":["Red blood cells","Platelets","White blood cells","Plasma cells"],"answer":2,"explanation":"White blood cells protect the body from disease-causing organisms."},{"subject":"biology","q":"Which type of white blood cell engulfs pathogens?","options":["Lymphocyte","Phagocyte","Platelet","Erythrocyte"],"answer":1,"explanation":"Phagocytes destroy pathogens by engulfing and digesting them."},{"subject":"biology","q":"What is the role of lymphocytes?","options":["Carry oxygen","Produce antibodies","Clot blood","Transport nutrients"],"answer":1,"explanation":"Lymphocytes produce antibodies that help destroy disease-causing organisms."},{"subject":"biology","q":"Why are capillaries suitable for exchange of substances?","options":["They have thick walls","They contain valves","Their walls are one cell thick","They have muscular walls"],"answer":2,"explanation":"Thin walls allow rapid diffusion of gases, nutrients, and wastes."},{"subject":"biology","q":"Which chamber of the heart pumps blood to the entire body?","options":["Right atrium","Right ventricle","Left atrium","Left ventricle"],"answer":3,"explanation":"The left ventricle pumps oxygenated blood through the aorta to all parts of the body."},{"subject":"biology","q":"Why is the wall of the left ventricle thicker than the right ventricle?","options":["It stores more blood","It pumps blood at higher pressure","It contains more valves","It receives more blood"],"answer":1,"explanation":"The left ventricle must generate enough pressure to pump blood throughout the body."},{"subject":"biology","q":"What is the function of heart valves?","options":["Produce blood cells","Prevent backflow of blood","Increase heart rate","Carry oxygen"],"answer":1,"explanation":"Valves ensure blood flows in one direction through the heart."},{"subject":"biology","q":"Which blood vessel carries blood from the heart to the lungs?","options":["Pulmonary vein","Vena cava","Aorta","Pulmonary artery"],"answer":3,"explanation":"The pulmonary artery carries deoxygenated blood to the lungs."},{"subject":"biology","q":"Which blood vessel carries oxygenated blood from the lungs to the heart?","options":["Pulmonary vein","Pulmonary artery","Vena cava","Aorta"],"answer":0,"explanation":"The pulmonary vein returns oxygenated blood to the left atrium."},{"subject":"biology","q":"What is blood clotting?","options":["Breakdown of blood cells","Formation of a plug that prevents excessive blood loss","Production of antibodies","Oxygen transport"],"answer":1,"explanation":"Blood clotting seals wounds and prevents excessive bleeding."},{"subject":"biology","q":"Which vitamin is essential for blood clotting?","options":["Vitamin A","Vitamin C","Vitamin D","Vitamin K"],"answer":3,"explanation":"Vitamin K is needed for production of prothrombin involved in clotting."},{"subject":"biology","q":"What is the function of the lymphatic system?","options":["Produces digestive enzymes","Returns excess tissue fluid to the blood","Carries urine to the bladder","Produces bile"],"answer":1,"explanation":"The lymphatic system collects excess tissue fluid and returns it to the bloodstream."},{"subject":"biology","q":"Which condition occurs when blood pressure remains above normal?","options":["Anaemia","Hypertension (high blood pressure)","Diabetes","Malaria"],"answer":1,"explanation":"High blood pressure increases strain on the heart and blood vessels."},{"subject":"biology","q":"Which lifestyle habit helps prevent circulatory diseases?","options":["Smoking regularly","Excessive alcohol consumption","Regular exercise","Eating excessive fatty foods"],"answer":2,"explanation":"Regular exercise strengthens the heart, improves circulation, and reduces the risk of cardiovascular diseases."},{"subject":"biology","q":"What is respiration?","options":["Breathing in oxygen only","Breakdown of food substances to release energy","Movement of air into lungs","Removal of carbon dioxide only"],"answer":1,"explanation":"Respiration is the process by which food substances are broken down to release energy needed for life processes."},{"subject":"biology","q":"In which cell organelle does respiration mainly occur?","options":["Chloroplast","Nucleus","Mitochondrion","Ribosome"],"answer":2,"explanation":"Mitochondria contain enzymes required for cellular respiration and energy production."},{"subject":"biology","q":"Which type of respiration requires oxygen?","options":["Anaerobic respiration","Aerobic respiration","Fermentation","Glycolysis only"],"answer":1,"explanation":"Aerobic respiration uses oxygen to completely break down glucose and release large amounts of energy."},{"subject":"biology","q":"Which type of respiration occurs in the absence of oxygen?","options":["Aerobic respiration","Photosynthesis","Anaerobic respiration","Ventilation"],"answer":2,"explanation":"Anaerobic respiration allows energy release without oxygen."},{"subject":"biology","q":"What is the first substance formed when glucose begins to break down during respiration?","options":["Carbon dioxide","Water","Pyruvic acid","Ethanol"],"answer":2,"explanation":"Glucose is first broken down into pyruvic acid during glycolysis."},{"subject":"biology","q":"What are the final products of aerobic respiration?","options":["Lactic acid and energy","Carbon dioxide, water, and energy","Ethanol and carbon dioxide","Oxygen and glucose"],"answer":1,"explanation":"Aerobic respiration completely breaks down glucose to produce carbon dioxide, water, and energy."},{"subject":"biology","q":"Which energy-rich molecule stores energy released during respiration?","options":["DNA","RNA","ATP","ADP"],"answer":2,"explanation":"ATP stores energy and releases it when needed by cells."},{"subject":"biology","q":"What does ATP stand for?","options":["Adenosine Triphosphate","Active Transport Protein","Adenosine Transfer Phosphate","Amino Transfer Product"],"answer":0,"explanation":"ATP is the main energy-carrying molecule in cells."},{"subject":"biology","q":"What evidence shows that respiration produces heat?","options":["Production of oxygen","Increase in temperature of germinating seeds","Formation of chlorophyll","Reduction of humidity"],"answer":1,"explanation":"Germinating seeds release heat during respiration, causing a temperature increase."},{"subject":"biology","q":"Which gas is produced during alcoholic fermentation by yeast?","options":["Nitrogen","Oxygen","Carbon dioxide","Hydrogen"],"answer":2,"explanation":"Yeast produces carbon dioxide and ethanol during anaerobic respiration."},{"subject":"biology","q":"What is alcoholic fermentation?","options":["Production of lactic acid in muscles","Breakdown of glucose to ethanol and carbon dioxide","Absorption of oxygen","Digestion of starch"],"answer":1,"explanation":"Alcoholic fermentation occurs in yeast and some plants under anaerobic conditions."},{"subject":"biology","q":"What is produced during anaerobic respiration in human muscles?","options":["Ethanol","Carbon dioxide only","Lactic acid","Glucose"],"answer":2,"explanation":"Human muscle cells produce lactic acid when oxygen is insufficient."},{"subject":"biology","q":"What is oxygen debt?","options":["Lack of oxygen in the atmosphere","Extra oxygen needed to remove lactic acid after exercise","Oxygen stored in muscles","Oxygen used in photosynthesis"],"answer":1,"explanation":"After strenuous exercise, extra oxygen is required to break down accumulated lactic acid."},{"subject":"biology","q":"Why is gaseous exchange important?","options":["To increase body size","To obtain useful gases and remove waste gases","To produce food","To transport blood"],"answer":1,"explanation":"Organisms need oxygen and must remove carbon dioxide produced during respiration."},{"subject":"biology","q":"Where does gaseous exchange occur in human lungs?","options":["Bronchi","Trachea","Alveoli","Larynx"],"answer":2,"explanation":"Alveoli provide a large surface area for diffusion of respiratory gases."},{"subject":"biology","q":"Why are alveoli efficient for gaseous exchange?","options":["They have thick walls","They are dry","They have a large surface area and thin walls","They contain bones"],"answer":2,"explanation":"Thin moist walls and numerous alveoli allow rapid diffusion of gases."},{"subject":"biology","q":"Which part of the brain regulates breathing?","options":["Cerebrum","Cerebellum","Medulla oblongata","Hypothalamus"],"answer":2,"explanation":"The medulla oblongata monitors carbon dioxide levels and controls breathing rate."},{"subject":"biology","q":"What happens to breathing rate during vigorous exercise?","options":["It decreases","It remains unchanged","It increases","It stops briefly"],"answer":2,"explanation":"Exercise increases oxygen demand and carbon dioxide production, causing faster breathing."},{"subject":"biology","q":"Why is carbon monoxide dangerous?","options":["It destroys lungs immediately","It combines strongly with haemoglobin, preventing oxygen transport","It lowers body temperature","It increases digestion"],"answer":1,"explanation":"Carbon monoxide forms carboxyhaemoglobin, reducing oxygen supply to body tissues."},{"subject":"biology","q":"Which harmful substance in cigarette smoke can cause lung cancer?","options":["Oxygen","Water vapour","Tar","Nitrogen"],"answer":2,"explanation":"Tar contains carcinogens that promote the development of cancerous cells in the lungs."},{"subject":"biology","q":"What is locomotion?","options":["Digestion of food","Movement of an organism from one place to another","Breathing process","Blood circulation"],"answer":1,"explanation":"Locomotion is the movement of a whole organism from one place to another, helping it find food, shelter, and mates."},{"subject":"biology","q":"Which of the following is a function of the skeleton?","options":["Photosynthesis","Support and protection of the body","Digestion of food","Production of oxygen"],"answer":1,"explanation":"The skeleton supports the body, protects internal organs, and provides attachment points for muscles."},{"subject":"biology","q":"Which type of skeleton is found inside the body?","options":["Exoskeleton","Hydrostatic skeleton","Endoskeleton","Cartilage skeleton"],"answer":2,"explanation":"An endoskeleton is an internal skeleton made of bone and cartilage."},{"subject":"biology","q":"Which type of skeleton is found in insects?","options":["Endoskeleton","Hydrostatic skeleton","Exoskeleton","Cartilage skeleton"],"answer":2,"explanation":"Insects possess a hard external covering called an exoskeleton."},{"subject":"biology","q":"What is the main function of cartilage?","options":["Produces red blood cells","Reduces friction at joints","Digests food","Produces hormones"],"answer":1,"explanation":"Cartilage covers the ends of bones and reduces friction during movement."},{"subject":"biology","q":"Which mineral gives bones their hardness?","options":["Iron","Magnesium","Calcium","Potassium"],"answer":2,"explanation":"Calcium compounds strengthen bones and teeth."},{"subject":"biology","q":"What is a joint?","options":["A blood vessel","A point where two bones meet","A type of muscle","A part of the nervous system"],"answer":1,"explanation":"Joints allow movement between bones."},{"subject":"biology","q":"Which type of joint is found at the knee?","options":["Ball-and-socket joint","Pivot joint","Hinge joint","Gliding joint"],"answer":2,"explanation":"Hinge joints allow movement in one plane, like a door hinge."},{"subject":"biology","q":"Which joint is found at the shoulder?","options":["Hinge joint","Ball-and-socket joint","Pivot joint","Fixed joint"],"answer":1,"explanation":"Ball-and-socket joints allow movement in many directions."},{"subject":"biology","q":"What is the function of ligaments?","options":["Connect muscle to bone","Connect bone to bone","Produce energy","Transport nutrients"],"answer":1,"explanation":"Ligaments hold bones together and stabilise joints."},{"subject":"biology","q":"What is the function of tendons?","options":["Connect muscle to bone","Connect bone to bone","Carry blood","Produce hormones"],"answer":0,"explanation":"Tendons attach muscles to bones, enabling movement."},{"subject":"biology","q":"Which part of a long bone contains bone marrow?","options":["Cartilage","Periosteum","Medullary cavity","Ligament"],"answer":2,"explanation":"The medullary cavity contains bone marrow that produces blood cells."},{"subject":"biology","q":"Why are bones considered living tissues?","options":["They contain chloroplasts","They can grow and repair themselves","They produce food","They perform photosynthesis"],"answer":1,"explanation":"Bones contain living cells that allow growth and healing after injury."},{"subject":"biology","q":"Which adaptation helps birds fly?","options":["Heavy bones","Hollow bones","Thick skin","Large teeth"],"answer":1,"explanation":"Hollow bones reduce body weight, making flight easier."},{"subject":"biology","q":"What is the main function of feathers in birds?","options":["Digestion","Reproduction","Aid flight and insulation","Production of blood"],"answer":2,"explanation":"Feathers help birds fly and maintain body temperature."},{"subject":"biology","q":"Which structure helps fish move through water?","options":["Wings","Fins","Claws","Hair"],"answer":1,"explanation":"Fins provide balance, steering, and propulsion in water."},{"subject":"biology","q":"Why do fish have streamlined bodies?","options":["To store more food","To reduce resistance when swimming","To attract predators","To increase body weight"],"answer":1,"explanation":"A streamlined shape reduces water resistance during movement."},{"subject":"biology","q":"Which type of muscle works together with bones to produce movement?","options":["Cardiac muscle","Smooth muscle","Skeletal muscle","Circular muscle"],"answer":2,"explanation":"Skeletal muscles pull on bones to create body movements."},{"subject":"biology","q":"What happens when a muscle contracts?","options":["It lengthens","It becomes inactive","It shortens and pulls on the bone","It produces blood"],"answer":2,"explanation":"Muscle contraction causes movement by pulling on attached bones."},{"subject":"biology","q":"Why is locomotion important to animals?","options":["It allows them to obtain food, escape danger, and find mates","It produces oxygen","It controls blood pressure","It replaces respiration"],"answer":0,"explanation":"Locomotion increases an animal\u0027s chances of survival by helping it obtain resources and avoid threats."},{"subject":"biology","q":"What is reproduction?","options":["Movement from one place to another","Production of new individuals of the same species","Digestion of food","Respiration"],"answer":1,"explanation":"Reproduction is the process by which organisms produce offspring to ensure continuity of their species."},{"subject":"biology","q":"What is the function of chromosomes?","options":["Transport oxygen","Control heredity and carry genetic information","Produce hormones","Digest food"],"answer":1,"explanation":"Chromosomes contain genes that determine inherited characteristics."},{"subject":"biology","q":"In which part of the cell are chromosomes found?","options":["Cytoplasm","Cell membrane","Nucleus","Vacuole"],"answer":2,"explanation":"Chromosomes are located in the nucleus where genetic material is stored."},{"subject":"biology","q":"What is mitosis?","options":["Formation of sex cells","Cell division that produces identical cells","Fertilisation process","Production of hormones"],"answer":1,"explanation":"Mitosis produces two genetically identical daughter cells for growth and repair."},{"subject":"biology","q":"What is the importance of mitosis?","options":["Produces gametes","Increases variation only","Growth, repair and replacement of worn-out cells","Produces embryos"],"answer":2,"explanation":"Mitosis helps organisms grow and repair damaged tissues."},{"subject":"biology","q":"What is meiosis?","options":["Division producing two identical cells","Division producing four cells with half the chromosome number","Respiration process","Fertilisation process"],"answer":1,"explanation":"Meiosis produces gametes containing half the normal chromosome number."},{"subject":"biology","q":"Why is meiosis important?","options":["It increases body size","It produces sex cells for reproduction","It causes digestion","It increases blood pressure"],"answer":1,"explanation":"Meiosis ensures that chromosome numbers remain constant after fertilisation."},{"subject":"biology","q":"What is a gamete?","options":["Body cell","Nerve cell","Sex cell","Blood cell"],"answer":2,"explanation":"Gametes are specialised reproductive cells such as sperm and egg cells."},{"subject":"biology","q":"Which male reproductive cell fertilises the ovum?","options":["Red blood cell","Sperm cell","Platelet","White blood cell"],"answer":1,"explanation":"The sperm cell carries male genetic material to the ovum."},{"subject":"biology","q":"What is the female reproductive cell called?","options":["Ovum (egg cell)","Embryo","Zygote","Gametophyte"],"answer":0,"explanation":"The ovum is the female sex cell involved in reproduction."},{"subject":"biology","q":"What is fertilisation?","options":["Formation of sperm only","Union of male and female gametes","Growth of the embryo","Menstruation"],"answer":1,"explanation":"Fertilisation occurs when a sperm cell fuses with an ovum to form a zygote."},{"subject":"biology","q":"What is formed immediately after fertilisation?","options":["Placenta","Embryo","Zygote","Foetus"],"answer":2,"explanation":"The zygote is the first cell formed after fertilisation."},{"subject":"biology","q":"What is the main function of the placenta?","options":["Digests food for the baby","Enables exchange of nutrients and wastes between mother and foetus","Produces red blood cells only","Controls breathing"],"answer":1,"explanation":"The placenta supplies the foetus with nutrients and oxygen while removing wastes."},{"subject":"biology","q":"Why is breastfeeding important?","options":["It weakens immunity","It provides nutrients and protective antibodies","It causes disease","It reduces growth"],"answer":1,"explanation":"Breast milk provides ideal nutrition and antibodies that protect the baby from infections."},{"subject":"biology","q":"Which hormone helps regulate the menstrual cycle?","options":["Adrenaline only","Reproductive hormones such as oestrogen and progesterone","Insulin only","Thyroxine only"],"answer":1,"explanation":"Oestrogen and progesterone help control changes in the female reproductive system."},{"subject":"biology","q":"What is menstruation?","options":["Release of sperm cells","Shedding of the uterine lining when pregnancy does not occur","Fertilisation of the ovum","Implantation of the embryo"],"answer":1,"explanation":"The uterus sheds its lining when the ovum is not fertilised."},{"subject":"biology","q":"What is contraception?","options":["Process of fertilisation","Prevention of pregnancy","Formation of gametes","Growth of the foetus"],"answer":1,"explanation":"Contraceptive methods are used to prevent pregnancy."},{"subject":"biology","q":"Why is meiosis important for variation?","options":["It produces identical offspring","It creates genetic differences among offspring","It stops fertilisation","It prevents inheritance"],"answer":1,"explanation":"Meiosis produces genetically different gametes, increasing variation in populations."},{"subject":"biology","q":"What is conception?","options":["Beginning of fertilisation only","Successful establishment of pregnancy after fertilisation and implantation","Release of an ovum","Beginning of menstruation"],"answer":1,"explanation":"Conception occurs when a fertilised egg implants in the uterus and pregnancy begins."},{"subject":"biology","q":"Why is reproduction important to living organisms?","options":["It helps digestion","It maintains the survival of species","It increases respiration rate","It reduces variation"],"answer":1,"explanation":"Without reproduction, species would eventually become extinct because no new individuals would replace those that die."},{"subject":"biology","q":"What is a disease?","options":["A form of reproduction","A condition that interferes with normal body functioning","A type of nutrient","A body organ"],"answer":1,"explanation":"A disease is any condition that affects the normal functioning of the body and may cause illness."},{"subject":"biology","q":"Which of the following diseases is caused by bacteria?","options":["Malaria","Cholera","Ringworm","Bilharzia"],"answer":1,"explanation":"Cholera is caused by bacteria and is commonly spread through contaminated food and water."},{"subject":"biology","q":"Which disease is caused by a virus?","options":["Tuberculosis","Cholera","Measles","Bilharzia"],"answer":2,"explanation":"Measles is a viral disease that spreads through infected droplets in the air."},{"subject":"biology","q":"Which disease is caused by fungi?","options":["Athlete\u0027s foot (Ringworm)","Malaria","Typhoid","Polio"],"answer":0,"explanation":"Ringworm and athlete\u0027s foot are fungal infections affecting the skin."},{"subject":"biology","q":"Which disease is caused by a protozoan?","options":["Cholera","Malaria","Tuberculosis","Influenza"],"answer":1,"explanation":"Malaria is caused by the protozoan parasite Plasmodium."},{"subject":"biology","q":"Which organism transmits malaria?","options":["Housefly","Tsetse fly","Female Anopheles mosquito","Tick"],"answer":2,"explanation":"Malaria is transmitted through the bite of an infected female Anopheles mosquito."},{"subject":"biology","q":"Which disease is caused by parasitic worms?","options":["Bilharzia","Measles","Cholera","Influenza"],"answer":0,"explanation":"Bilharzia is caused by parasitic worms that can enter the body through contaminated water."},{"subject":"biology","q":"What is a pathogen?","options":["A nutrient","A disease-causing organism","A vitamin","A blood vessel"],"answer":1,"explanation":"Pathogens are organisms such as bacteria, viruses, fungi, and protozoa that cause diseases."},{"subject":"biology","q":"Which of the following helps prevent the spread of cholera?","options":["Drinking untreated water","Poor sanitation","Proper disposal of waste and clean water supply","Sharing eating utensils"],"answer":2,"explanation":"Good sanitation and safe drinking water greatly reduce the spread of cholera."},{"subject":"biology","q":"What is the main method of controlling malaria?","options":["Drinking more milk","Sleeping under treated mosquito nets","Eating less sugar","Avoiding exercise"],"answer":1,"explanation":"Insecticide-treated mosquito nets help prevent mosquito bites and reduce malaria transmission."},{"subject":"biology","q":"Which symptom is commonly associated with malaria?","options":["High fever and chills","Broken bones","Tooth decay","Loss of hearing"],"answer":0,"explanation":"Malaria often causes fever, chills, headache, and body weakness."},{"subject":"biology","q":"Why is vaccination important?","options":["It cures every disease instantly","It helps the body develop immunity against certain diseases","It replaces antibiotics","It increases appetite"],"answer":1,"explanation":"Vaccination stimulates the body\u0027s immune system to protect against specific diseases."},{"subject":"biology","q":"Which disease spreads mainly through contaminated food and water?","options":["Cholera","Influenza","Tuberculosis","Measles"],"answer":0,"explanation":"Cholera spreads through food or water contaminated with disease-causing bacteria."},{"subject":"biology","q":"What is the importance of washing hands before eating?","options":["Improves eyesight","Prevents transmission of disease-causing organisms","Increases appetite","Improves hearing"],"answer":1,"explanation":"Hand washing removes pathogens that could otherwise enter the body through food."},{"subject":"biology","q":"Which disease can be prevented by avoiding direct contact with infected skin?","options":["Ringworm","Malaria","Cholera","Bilharzia"],"answer":0,"explanation":"Ringworm spreads through contact with infected people, animals, or contaminated objects."},{"subject":"biology","q":"What is the role of antibiotics?","options":["Treat viral infections","Treat bacterial infections","Destroy red blood cells","Cure all diseases"],"answer":1,"explanation":"Antibiotics are effective against bacteria but not against viruses."},{"subject":"biology","q":"Why should stagnant water be removed around homes?","options":["To reduce dust","To prevent mosquito breeding","To improve soil fertility","To increase rainfall"],"answer":1,"explanation":"Mosquitoes breed in stagnant water, increasing the risk of malaria transmission."},{"subject":"biology","q":"Which disease affects the immune system of the body?","options":["HIV/AIDS","Cholera","Ringworm","Bilharzia"],"answer":0,"explanation":"HIV attacks the immune system, reducing the body\u0027s ability to fight infections."},{"subject":"biology","q":"How can communities help prevent the spread of diseases?","options":["Maintaining poor sanitation","Ignoring health education","Promoting hygiene and proper waste disposal","Avoiding clean water"],"answer":2,"explanation":"Good hygiene and environmental cleanliness help reduce disease outbreaks."},{"subject":"biology","q":"Why is early treatment of diseases important?","options":["It reduces the chances of complications and spread","It increases infection rates","It weakens the immune system","It replaces prevention measures"],"answer":0,"explanation":"Early diagnosis and treatment improve recovery and help prevent transmission to others."},{"subject":"biology","q":"What is a population?","options":["All organisms in a country","A group of organisms of the same species living in a particular area","All plants in an ecosystem","All animals on earth"],"answer":1,"explanation":"A population consists of members of the same species living in a particular area."},{"subject":"biology","q":"What is population growth?","options":["Increase in the number of individuals in a population over time","Movement of people from one area to another","Reduction in resources","Increase in diseases"],"answer":0,"explanation":"Population growth occurs when births and immigration exceed deaths and emigration."},{"subject":"biology","q":"Which factor directly increases population size?","options":["Death rate","Emigration","Birth rate","Disease outbreaks"],"answer":2,"explanation":"Births add new individuals to a population, increasing its size."},{"subject":"biology","q":"Which factor directly decreases population size?","options":["Immigration","Birth rate","Availability of food","Death rate"],"answer":3,"explanation":"Deaths remove individuals from a population."},{"subject":"biology","q":"What is immigration?","options":["Movement of people out of a country","Movement of people into a country or area","Increase in births","Reduction in deaths"],"answer":1,"explanation":"Immigration increases population size by adding individuals to an area."},{"subject":"biology","q":"What is emigration?","options":["Movement of people into an area","Movement of people out of an area","Change in birth rate","Population census"],"answer":1,"explanation":"Emigration reduces population size in the area people leave."},{"subject":"biology","q":"Which factor can increase human population growth?","options":["Improved healthcare","High death rates","Famine","Natural disasters"],"answer":0,"explanation":"Better healthcare reduces mortality and increases life expectancy."},{"subject":"biology","q":"What is a population growth curve?","options":["A graph showing changes in population size over time","A graph showing rainfall only","A graph showing income levels","A graph showing diseases"],"answer":0,"explanation":"Population growth curves help illustrate how populations change over time."},{"subject":"biology","q":"Which resource is often placed under pressure by rapid population growth?","options":["Air only","Water, food, and land","Sunlight only","Minerals only"],"answer":1,"explanation":"More people require more food, water, housing, and land resources."},{"subject":"biology","q":"Why can rapid population growth lead to unemployment?","options":["More people compete for available jobs","It increases rainfall","It improves education","It reduces migration"],"answer":0,"explanation":"When population grows faster than job opportunities, unemployment may increase."},{"subject":"biology","q":"Which of the following is a problem associated with rapid population growth?","options":["Increased availability of land","Increased pressure on social services","Reduced need for food","Decreased demand for housing"],"answer":1,"explanation":"Rapid population growth increases pressure on schools, hospitals, and other services."},{"subject":"biology","q":"How can family planning help control population growth?","options":["By increasing disease rates","By helping families choose the number and spacing of children","By increasing migration","By reducing food production"],"answer":1,"explanation":"Family planning can help maintain sustainable population growth."},{"subject":"biology","q":"Why is education important in population management?","options":["It reduces knowledge","It helps people make informed decisions about family size","It increases disease transmission","It decreases agricultural production"],"answer":1,"explanation":"Education helps people understand health, family planning, and resource management."},{"subject":"biology","q":"What is a census?","options":["A disease survey","Counting and collecting information about a population","Measuring rainfall","Studying plants"],"answer":1,"explanation":"A census provides population data used for planning and development."},{"subject":"biology","q":"Which factor may reduce population growth?","options":["Improved nutrition","Improved healthcare","Increased mortality due to disease","Better sanitation"],"answer":2,"explanation":"Disease outbreaks can increase death rates and reduce population growth."},{"subject":"biology","q":"Why is food security important in growing populations?","options":["It ensures enough food is available for people","It increases disease rates","It reduces employment","It decreases education levels"],"answer":0,"explanation":"Population growth increases demand for food, making food security essential."},{"subject":"biology","q":"Which environmental problem can result from rapid population growth?","options":["Reduced waste production","Deforestation","Reduced demand for land","Increased wildlife habitat"],"answer":1,"explanation":"More land may be cleared for settlement and farming, causing deforestation."},{"subject":"biology","q":"What is one benefit of managing population growth effectively?","options":["Better access to resources and services","Increased poverty only","Increased overcrowding","Reduced healthcare access"],"answer":0,"explanation":"Population management helps balance resources with people\u0027s needs."},{"subject":"biology","q":"Why is employment important for a growing population?","options":["It provides income and improves living standards","It reduces food production","It increases disease spread","It causes migration only"],"answer":0,"explanation":"Employment helps individuals meet their needs and contributes to economic growth."},{"subject":"biology","q":"Which statement best explains sustainable population growth?","options":["Population grows without consideration of resources","Population growth is balanced with available resources and development","Population remains exactly the same forever","Population growth depends only on births"],"answer":1,"explanation":"Sustainable population growth ensures that available resources can support the population without causing major social or environmental problems."},{"subject":"chemistry","q":"What is the rate of reaction?","options":["Amount of product formed only","Change in amount of reactant or product per unit time","Mass of reactants used","Temperature of reaction"],"answer":1,"explanation":"Reaction rate is the rate of change of the amount or concentration of a reactant or product per unit time."},{"subject":"chemistry","q":"According to collision theory, chemical reactions occur when:","options":["Particles dissolve","Particles are heated","Particles collide","Particles change colour"],"answer":2,"explanation":"Collision theory states that reactions occur due to collisions between reacting particles."},{"subject":"chemistry","q":"What is activation energy?","options":["Energy released during reaction","Minimum energy needed for a reaction to occur","Heat from products","Energy stored in catalysts"],"answer":1,"explanation":"Activation energy is the minimum energy particles need before they can react successfully."},{"subject":"chemistry","q":"Which collision leads to a chemical reaction?","options":["Slow collision","Weak collision","Fruitful collision","Random collision"],"answer":2,"explanation":"Only fruitful collisions produce chemical reactions."},{"subject":"chemistry","q":"Increasing concentration of reactants generally:","options":["Decreases reaction rate","Stops the reaction","Increases reaction rate","Has no effect"],"answer":2,"explanation":"Higher concentration increases collision frequency, leading to a faster reaction."},{"subject":"chemistry","q":"Increasing temperature increases reaction rate because:","options":["Particles move slower","Particles have more kinetic energy","Products are formed first","Pressure decreases"],"answer":1,"explanation":"Higher temperature increases particle speed and collision frequency."},{"subject":"chemistry","q":"Which factor affects the rate of reaction for solids?","options":["Surface area","Pressure only","Colour","Density only"],"answer":0,"explanation":"Larger surface area exposes more particles for collisions."},{"subject":"chemistry","q":"Which form of marble reacts fastest with hydrochloric acid?","options":["Large chips","Small chips","Powdered marble","All equally"],"answer":2,"explanation":"Powdered marble has the greatest surface area."},{"subject":"chemistry","q":"A catalyst:","options":["Is consumed in a reaction","Stops reactions","Increases reaction rate without being used up","Changes products formed"],"answer":2,"explanation":"Catalysts speed up reactions and remain chemically unchanged."},{"subject":"chemistry","q":"Manganese dioxide catalyses the decomposition of:","options":["Hydrochloric acid","Sulphuric acid","Hydrogen peroxide","Sodium hydroxide"],"answer":2,"explanation":"MnOÃ¢â€šâ€š speeds up the decomposition of hydrogen peroxide into water and oxygen."},{"subject":"chemistry","q":"How does a catalyst increase reaction rate?","options":["Raises activation energy","Lowers activation energy","Increases product mass","Decreases concentration"],"answer":1,"explanation":"Catalysts provide an alternative pathway with lower activation energy."},{"subject":"chemistry","q":"Increasing pressure affects reactions involving:","options":["Solids only","Liquids only","Gases only","Solutions only"],"answer":2,"explanation":"Pressure mainly affects gaseous reactants because it changes particle spacing."},{"subject":"chemistry","q":"Increasing pressure on gases will:","options":["Reduce collisions","Increase collision frequency","Stop the reaction","Lower concentration"],"answer":1,"explanation":"Gas particles are forced closer together, increasing collisions."},{"subject":"chemistry","q":"Light affects reaction rate by:","options":["Acting as an activation energy source","Lowering pressure","Reducing concentration","Forming catalysts"],"answer":0,"explanation":"Light provides energy required to start certain reactions."},{"subject":"chemistry","q":"Which is NOT a method of measuring reaction rate?","options":["Volume of gas produced","Colour of apparatus","Change in mass","Time taken for product formation"],"answer":1,"explanation":"Apparatus colour does not measure reaction rate."},{"subject":"chemistry","q":"A reversible reaction is one in which:","options":["Products cannot reform reactants","Products can change back into reactants","Only reactants exist","The reaction stops immediately"],"answer":1,"explanation":"Reversible reactions occur in both forward and backward directions."},{"subject":"chemistry","q":"Which is an irreversible reaction?","options":["Hydration of copper sulphate","Freezing water","Burning magnesium in oxygen","Melting ice"],"answer":2,"explanation":"Magnesium oxide formed cannot easily be converted back into magnesium and oxygen."},{"subject":"chemistry","q":"Chemical equilibrium occurs when:","options":["Reactants are finished","Products stop forming","Forward and backward reaction rates are equal","Temperature is constant"],"answer":2,"explanation":"At equilibrium, the forward and reverse reactions occur at the same rate."},{"subject":"chemistry","q":"According to Le Chatelier\u0027s Principle, a system at equilibrium responds to stress by:","options":["Increasing the stress","Ignoring the stress","Opposing the stress","Stopping the reaction"],"answer":2,"explanation":"Equilibrium shifts in a direction that reduces the imposed change."},{"subject":"chemistry","q":"In the Haber Process, high pressure increases ammonia yield because:","options":["Ammonia is a liquid","Fewer gas molecules are produced","Temperature increases","The catalyst changes equilibrium position"],"answer":1,"explanation":"The reaction changes from 4 moles of gas to 2 moles, so high pressure favours ammonia formation."},{"subject":"chemistry","q":"An acid is a substance that:","options":["Produces OHÃ¢ÂÂ» ions in water","Produces HÃ¢ÂÂº ions in water","Produces oxygen","Produces salts only"],"answer":1,"explanation":"Acids release hydrogen ions (HÃ¢ÂÂº) when dissolved in water."},{"subject":"chemistry","q":"A base is a substance that:","options":["Produces HÃ¢ÂÂº ions","Produces OHÃ¢ÂÂ» ions","Produces COÃ¢â€šâ€š","Produces water only"],"answer":1,"explanation":"Bases release hydroxide ions (OHÃ¢ÂÂ») in aqueous solution."},{"subject":"chemistry","q":"Which of the following is an acid?","options":["Sodium hydroxide","Potassium hydroxide","Hydrochloric acid","Calcium oxide"],"answer":2,"explanation":"Hydrochloric acid (HCl) is a common acid."},{"subject":"chemistry","q":"Which of the following is a base?","options":["Hydrochloric acid","Sulphuric acid","Nitric acid","Sodium hydroxide"],"answer":3,"explanation":"Sodium hydroxide (NaOH) is a strong base."},{"subject":"chemistry","q":"According to Bronsted-Lowry theory, an acid is:","options":["A proton acceptor","A proton donor","An electron donor","An electron acceptor"],"answer":1,"explanation":"Bronsted-Lowry acids donate protons (HÃ¢ÂÂº ions)."},{"subject":"chemistry","q":"According to Bronsted-Lowry theory, a base is:","options":["A proton acceptor","A proton donor","A metal oxide","A salt"],"answer":0,"explanation":"Bases accept protons from acids."},{"subject":"chemistry","q":"What is the conjugate base of HCl?","options":["HÃ¢â€šâ€šClÃ¢ÂÂº","ClÃ¢ÂÂ»","OHÃ¢ÂÂ»","HÃ¢â€šâ€šO"],"answer":1,"explanation":"HCl loses a proton to form ClÃ¢ÂÂ», its conjugate base."},{"subject":"chemistry","q":"Which acid is classified as a strong acid?","options":["Ethanoic acid","Carbonic acid","Hydrochloric acid","Citric acid"],"answer":2,"explanation":"Hydrochloric acid ionises completely in water."},{"subject":"chemistry","q":"A weak acid:","options":["Completely ionises in water","Partially ionises in water","Does not ionise","Is insoluble"],"answer":1,"explanation":"Weak acids only partially ionise in aqueous solution."},{"subject":"chemistry","q":"The pH of a neutral solution is:","options":["0","14","7","10"],"answer":2,"explanation":"Pure water and neutral solutions have a pH of 7."},{"subject":"chemistry","q":"A solution with pH 3 is:","options":["Neutral","Alkaline","Acidic","Basic salt"],"answer":2,"explanation":"Any pH less than 7 indicates an acidic solution."},{"subject":"chemistry","q":"A solution with pH 12 is:","options":["Acidic","Neutral","Alkaline","Weakly acidic"],"answer":2,"explanation":"Solutions with pH greater than 7 are alkaline."},{"subject":"chemistry","q":"Which oxide reacts with acids and bases?","options":["Acidic oxide","Basic oxide","Neutral oxide","Amphoteric oxide"],"answer":3,"explanation":"Amphoteric oxides react with both acids and bases."},{"subject":"chemistry","q":"Which of the following is a basic oxide?","options":["COÃ¢â€šâ€š","SOÃ¢â€šâ€š","MgO","NO"],"answer":2,"explanation":"Magnesium oxide is a metallic oxide and therefore basic."},{"subject":"chemistry","q":"Which oxide is acidic?","options":["NaÃ¢â€šâ€šO","CaO","MgO","SOÃ¢â€šâ€š"],"answer":3,"explanation":"Sulphur dioxide is a non-metal oxide and is acidic."},{"subject":"chemistry","q":"Neutralisation is the reaction between:","options":["Acid and base","Acid and metal","Metal and water","Salt and water"],"answer":0,"explanation":"Neutralisation occurs when an acid reacts with a base to form salt and water."},{"subject":"chemistry","q":"Which products are formed during neutralisation?","options":["Salt and oxygen","Salt and hydrogen","Salt and water","Water and carbon dioxide"],"answer":2,"explanation":"Acid + Base Ã¢â€ â€™ Salt + Water."},{"subject":"chemistry","q":"Which method can be used to prepare a soluble salt?","options":["Neutralisation","Burning","Distillation only","Electrolysis only"],"answer":0,"explanation":"Soluble salts are commonly prepared by neutralisation reactions."},{"subject":"chemistry","q":"A precipitate is:","options":["A gas formed in a reaction","An insoluble solid formed in a solution","A soluble salt","A liquid product"],"answer":1,"explanation":"A precipitate forms when two solutions react to produce an insoluble solid."},{"subject":"chemistry","q":"Which reaction is a precipitation reaction?","options":["Silver nitrate + sodium chloride","Methane + oxygen","Zinc + hydrochloric acid","Magnesium + oxygen"],"answer":0,"explanation":"Silver nitrate reacts with sodium chloride to form insoluble silver chloride (a precipitate)."},{"subject":"chemistry","q":"Oxidation is the:","options":["Gain of electrons","Loss of electrons","Gain of neutrons","Loss of protons"],"answer":1,"explanation":"Oxidation is defined as the loss of electrons, while reduction is the gain of electrons."},{"subject":"chemistry","q":"Reduction is the:","options":["Gain of electrons","Loss of electrons","Gain of oxygen","Loss of hydrogen"],"answer":0,"explanation":"Reduction occurs when a substance gains electrons."},{"subject":"chemistry","q":"Which process represents oxidation?","options":["Gain of hydrogen","Loss of oxygen","Gain of electrons","Gain of oxygen"],"answer":3,"explanation":"Oxidation can also be defined as the gain of oxygen."},{"subject":"chemistry","q":"Which process represents reduction?","options":["Gain of oxygen","Loss of hydrogen","Gain of oxygen and loss of electrons","Loss of electrons"],"answer":1,"explanation":"Reduction can be described as the loss of oxygen or gain of hydrogen."},{"subject":"chemistry","q":"What is the oxidation number of an element in its free state?","options":["+1","-1","0","+2"],"answer":2,"explanation":"Elements in their free state always have an oxidation number of zero."},{"subject":"chemistry","q":"The oxidation number of oxygen in most compounds is:","options":["+2","-2","+1","0"],"answer":1,"explanation":"Oxygen usually has an oxidation number of -2."},{"subject":"chemistry","q":"The oxidation number of hydrogen in most compounds is:","options":["+1","-1","+2","0"],"answer":0,"explanation":"Hydrogen generally has an oxidation number of +1."},{"subject":"chemistry","q":"What is the oxidation number of chlorine in NaCl?","options":["+1","-1","+2","0"],"answer":1,"explanation":"Sodium is +1, therefore chlorine must be -1."},{"subject":"chemistry","q":"Which statement about redox reactions is correct?","options":["Only oxidation occurs","Only reduction occurs","Oxidation and reduction occur simultaneously","No electrons are transferred"],"answer":2,"explanation":"Redox reactions involve both oxidation and reduction occurring together."},{"subject":"chemistry","q":"A reducing agent:","options":["Is reduced","Causes reduction by donating electrons","Gains electrons","Gains oxygen"],"answer":1,"explanation":"A reducing agent donates electrons and causes another substance to be reduced."},{"subject":"chemistry","q":"An oxidising agent:","options":["Accepts electrons","Donates electrons","Loses oxygen","Gains hydrogen"],"answer":0,"explanation":"Oxidising agents accept electrons and cause oxidation of other substances."},{"subject":"chemistry","q":"Which metal is the most reactive?","options":["Copper","Silver","Potassium","Gold"],"answer":2,"explanation":"Potassium is near the top of the reactivity series and is highly reactive."},{"subject":"chemistry","q":"Which metal is least reactive?","options":["Magnesium","Zinc","Gold","Iron"],"answer":2,"explanation":"Gold is very unreactive and found near the bottom of the reactivity series."},{"subject":"chemistry","q":"A more reactive metal can:","options":["Be displaced by a less reactive metal","Displace a less reactive metal from its compound","Never react with acids","React only with water"],"answer":1,"explanation":"More reactive metals displace less reactive metals from their salts."},{"subject":"chemistry","q":"Spontaneous reactions are reactions that:","options":["Need continuous heating","Occur naturally once started","Never occur","Require catalysts at all times"],"answer":1,"explanation":"Spontaneous reactions can proceed naturally once conditions are suitable."},{"subject":"chemistry","q":"An electrochemical cell converts:","options":["Heat energy into sound","Chemical energy into electrical energy","Electrical energy into heat only","Light energy into chemical energy"],"answer":1,"explanation":"Electrochemical cells generate electricity from chemical reactions."},{"subject":"chemistry","q":"The negative electrode in an electrochemical cell is called the:","options":["Cathode","Salt bridge","Anode","Electrolyte"],"answer":2,"explanation":"Oxidation occurs at the anode, making it the negative electrode in a galvanic cell."},{"subject":"chemistry","q":"Rusting of iron requires:","options":["Oxygen only","Water only","Oxygen and water","Carbon dioxide only"],"answer":2,"explanation":"Rusting occurs when iron reacts with both oxygen and water."},{"subject":"chemistry","q":"Rust is mainly:","options":["Iron carbonate","Hydrated iron(III) oxide","Iron chloride","Iron sulphide"],"answer":1,"explanation":"Rust consists mainly of hydrated iron(III) oxide."},{"subject":"chemistry","q":"Which method helps prevent rusting?","options":["Scratching the metal","Wetting the metal","Painting the metal surface","Heating the metal daily"],"answer":2,"explanation":"Painting prevents oxygen and water from reaching the iron surface."},{"subject":"chemistry","q":"What is electrolysis?","options":["Breakdown of substances using heat","Breakdown of substances using electricity","Formation of salts only","Mixing of solutions"],"answer":1,"explanation":"Electrolysis is the chemical decomposition of a substance by passing an electric current through it."},{"subject":"chemistry","q":"A substance that conducts electricity when molten or dissolved is called:","options":["Insulator","Catalyst","Electrolyte","Electrode"],"answer":2,"explanation":"An electrolyte contains mobile ions that carry electric current."},{"subject":"chemistry","q":"The positive electrode in electrolysis is the:","options":["Cathode","Anode","Electrolyte","Cell"],"answer":1,"explanation":"The anode is connected to the positive terminal of the power source."},{"subject":"chemistry","q":"The negative electrode in electrolysis is the:","options":["Cathode","Anode","Electrolyte","Salt bridge"],"answer":0,"explanation":"The cathode is connected to the negative terminal of the battery."},{"subject":"chemistry","q":"Positive ions move towards the:","options":["Anode","Cathode","Electrolyte","Salt solution"],"answer":1,"explanation":"Positive ions (cations) are attracted to the negatively charged cathode."},{"subject":"chemistry","q":"Negative ions move towards the:","options":["Cathode","Cell","Anode","Power supply"],"answer":2,"explanation":"Negative ions (anions) are attracted to the positively charged anode."},{"subject":"chemistry","q":"Which particles carry electricity in electrolytes?","options":["Electrons only","Protons","Ions","Neutrons"],"answer":2,"explanation":"Electric current in electrolytes is carried by ions."},{"subject":"chemistry","q":"During electrolysis, reduction occurs at the:","options":["Anode","Cathode","Electrolyte","Power source"],"answer":1,"explanation":"Reduction is the gain of electrons and occurs at the cathode."},{"subject":"chemistry","q":"During electrolysis, oxidation occurs at the:","options":["Cathode","Battery","Anode","Electrolyte"],"answer":2,"explanation":"Oxidation is the loss of electrons and occurs at the anode."},{"subject":"chemistry","q":"Molten lead bromide produces which substances during electrolysis?","options":["Lead and bromine","Lead and oxygen","Hydrogen and bromine","Lead oxide and bromine"],"answer":0,"explanation":"Lead forms at the cathode and bromine at the anode."},{"subject":"chemistry","q":"Which gas is commonly produced at the anode during electrolysis of water?","options":["Hydrogen","Oxygen","Nitrogen","Carbon dioxide"],"answer":1,"explanation":"Oxygen is released at the anode during electrolysis of water."},{"subject":"chemistry","q":"Which gas is commonly produced at the cathode during electrolysis of water?","options":["Oxygen","Chlorine","Hydrogen","Nitrogen"],"answer":2,"explanation":"Hydrogen gas is produced at the cathode."},{"subject":"chemistry","q":"What is a cation?","options":["Negatively charged ion","Positively charged ion","Neutral particle","Molecule"],"answer":1,"explanation":"Cations carry positive charges and move towards the cathode."},{"subject":"chemistry","q":"What is an anion?","options":["Positively charged ion","Neutral atom","Negatively charged ion","Proton"],"answer":2,"explanation":"Anions carry negative charges and move to the anode."},{"subject":"chemistry","q":"One industrial use of electrolysis is:","options":["Producing metals from ores","Burning fuels","Rusting metals","Freezing water"],"answer":0,"explanation":"Electrolysis is used to extract and purify metals."},{"subject":"chemistry","q":"Electroplating is the process of:","options":["Melting metals","Coating one metal with another using electricity","Rusting metals","Casting metals"],"answer":1,"explanation":"Electroplating deposits a thin layer of one metal on another."},{"subject":"chemistry","q":"Why are objects electroplated?","options":["To increase mass only","To improve appearance and prevent corrosion","To reduce conductivity","To make them brittle"],"answer":1,"explanation":"Electroplating protects metals and improves appearance."},{"subject":"chemistry","q":"Which metal is commonly used for electroplating jewellery?","options":["Sodium","Calcium","Gold","Potassium"],"answer":2,"explanation":"Gold is commonly used because it is attractive and resistant to corrosion."},{"subject":"chemistry","q":"The source of electrical energy used in electrolysis is usually:","options":["Magnet","Generator or battery","Water","Catalyst"],"answer":1,"explanation":"Electrolysis requires an external source of direct current."},{"subject":"chemistry","q":"Which statement about electrolysis is correct?","options":["It occurs without electricity","It uses electrical energy to cause chemical change","It is a physical change only","It cannot produce gases"],"answer":1,"explanation":"Electrolysis uses electrical energy to drive chemical reactions that would not occur naturally"},{"subject":"chemistry","q":"What is isomerism?","options":["Formation of ions","Existence of compounds with the same molecular formula but different structures","Breaking down of compounds","Change of state"],"answer":1,"explanation":"Isomerism occurs when compounds have the same molecular formula but different structural arrangements."},{"subject":"chemistry","q":"Compounds that have the same molecular formula but different structures are called:","options":["Homologues","Alkanes","Isomers","Polymers"],"answer":2,"explanation":"Such compounds are known as isomers."},{"subject":"chemistry","q":"Isomerism first appears in alkanes at:","options":["Methane (CHÃ¢â€šâ€ž)","Ethane (CÃ¢â€šâ€šHÃ¢â€šâ€ )","Propane (CÃ¢â€šÆ’HÃ¢â€šË†)","Butane (CÃ¢â€šâ€žHÃ¢â€šÂÃ¢â€šâ‚¬)"],"answer":3,"explanation":"Butane has two structural isomers: n-butane and methylpropane."},{"subject":"chemistry","q":"How many structural isomers does butane (CÃ¢â€šâ€žHÃ¢â€šÂÃ¢â€šâ‚¬) have?","options":["1","2","3","4"],"answer":1,"explanation":"Butane exists as n-butane and 2-methylpropane."},{"subject":"chemistry","q":"Isomers have:","options":["Different molecular formulas","Same molecular formula","Different elements","Same structure"],"answer":1,"explanation":"All isomers share the same molecular formula."},{"subject":"chemistry","q":"Which formula represents butane?","options":["CÃ¢â€šâ€šHÃ¢â€šâ€ ","CÃ¢â€šÆ’HÃ¢â€šË†","CÃ¢â€šâ€žHÃ¢â€šÂÃ¢â€šâ‚¬","CÃ¢â€šâ€¦HÃ¢â€šÂÃ¢â€šâ€š"],"answer":2,"explanation":"Butane has the molecular formula CÃ¢â€šâ€žHÃ¢â€šÂÃ¢â€šâ‚¬."},{"subject":"chemistry","q":"Alkenes contain:","options":["Triple bonds only","Double bonds","Ionic bonds","Metallic bonds"],"answer":1,"explanation":"Alkenes are hydrocarbons containing at least one carbon-carbon double bond."},{"subject":"chemistry","q":"Which type of isomerism commonly occurs in alkenes?","options":["Nuclear isomerism","Geometrical isomerism","Radioactive isomerism","Atomic isomerism"],"answer":1,"explanation":"Alkenes can show geometrical (cis-trans) isomerism because of restricted rotation around the double bond."},{"subject":"chemistry","q":"What causes geometric isomerism?","options":["Free rotation around a single bond","Presence of ionic bonds","Restricted rotation around a double bond","Presence of metals"],"answer":2,"explanation":"Double bonds prevent free rotation, allowing different spatial arrangements."},{"subject":"chemistry","q":"Alkanols belong to which family of compounds?","options":["Alcohols","Acids","Esters","Salts"],"answer":0,"explanation":"Alkanols are alcohols containing the hydroxyl (-OH) functional group."},{"subject":"chemistry","q":"Which functional group is present in alkanols?","options":["-COOH","-CHO","-OH","-NHÃ¢â€šâ€š"],"answer":2,"explanation":"Alcohols contain the hydroxyl functional group (-OH)."},{"subject":"chemistry","q":"Propanol has how many structural isomers?","options":["1","2","3","4"],"answer":1,"explanation":"Propanol exists as propan-1-ol and propan-2-ol."},{"subject":"chemistry","q":"Alkanals contain which functional group?","options":["-COOH","-OH","-CHO","-NHÃ¢â€šâ€š"],"answer":2,"explanation":"Alkanals (aldehydes) contain the -CHO group."},{"subject":"chemistry","q":"Alkanones are commonly known as:","options":["Alcohols","Ketones","Amines","Esters"],"answer":1,"explanation":"Alkanones belong to the ketone family."},{"subject":"chemistry","q":"Which functional group is found in ketones?","options":["C=O within the carbon chain","-OH","-COOH","-CHO"],"answer":0,"explanation":"Ketones contain a carbonyl group located within the carbon chain."},{"subject":"chemistry","q":"Alkanoic acids contain the functional group:","options":["-OH","-NHÃ¢â€šâ€š","-COOH","-CHO"],"answer":2,"explanation":"Carboxylic acids contain the carboxyl group (-COOH)."},{"subject":"chemistry","q":"Which of the following is an alkanoic acid?","options":["Ethanol","Ethanal","Ethanoic acid","Propanone"],"answer":2,"explanation":"Ethanoic acid belongs to the alkanoic acid family."},{"subject":"chemistry","q":"Why do isomers have different properties?","options":["They have different molecular formulas","They contain different elements","Their atoms are arranged differently","They have different masses"],"answer":2,"explanation":"Different structural arrangements result in different physical and chemical properties."},{"subject":"chemistry","q":"Which pair are structural isomers?","options":["CHÃ¢â€šâ€ž and CÃ¢â€šâ€šHÃ¢â€šâ€ ","CÃ¢â€šâ€šHÃ¢â€šâ€  and CÃ¢â€šÆ’HÃ¢â€šË†","Butane and 2-methylpropane","Ethanol and methanol"],"answer":2,"explanation":"Both have the formula CÃ¢â€šâ€žHÃ¢â€šÂÃ¢â€šâ‚¬ but different structures."},{"subject":"chemistry","q":"The main feature of structural isomerism is:","options":["Different molecular formulae","Same structural formula","Same molecular formula, different structural formulae","Same physical properties only"],"answer":2,"explanation":"Structural isomers have identical molecular formulas but different structural fo1. What is a polymer?"},{"subject":"chemistry","q":"Answer: CExplanation: Structural isomers have identical molecular formulas but different structural fo1. What is a polymer?","options":["A small molecule","A substance made of many repeating units","A metal compound","An acid"],"answer":1,"explanation":"A polymer is a large molecule made up of many repeating units called monomers."},{"subject":"chemistry","q":"The small molecules that join together to form polymers are called:","options":["Catalysts","Electrolytes","Monomers","Isomers"],"answer":2,"explanation":"Monomers are the building blocks of polymers."},{"subject":"chemistry","q":"The process of joining many monomers to form a polymer is called:","options":["Isomerism","Polymerisation","Electrolysis","Neutralisation"],"answer":1,"explanation":"Polymerisation is the chemical process through which monomers join together."},{"subject":"chemistry","q":"Which of the following is a natural polymer?","options":["Polythene","PVC","Cellulose","Nylon"],"answer":2,"explanation":"Cellulose is a naturally occurring polymer found in plants."},{"subject":"chemistry","q":"Which of the following is a synthetic polymer?","options":["Starch","Protein","Rubber from trees","Polythene"],"answer":3,"explanation":"Polythene is a man-made (synthetic) polymer."},{"subject":"chemistry","q":"Addition polymerisation involves:","options":["Removal of water molecules","Joining monomers without loss of atoms","Breaking large molecules","Loss of carbon dioxide"],"answer":1,"explanation":"In addition polymerisation, all atoms of the monomers become part of the polymer."},{"subject":"chemistry","q":"Which compound undergoes addition polymerisation?","options":["Ethene","Water","Sodium chloride","Calcium oxide"],"answer":0,"explanation":"Ethene molecules join together to form polyethene."},{"subject":"chemistry","q":"The polymer formed from ethene is:","options":["PVC","Nylon","Polyethene","Terylene"],"answer":2,"explanation":"Many ethene molecules join to form polyethene."},{"subject":"chemistry","q":"Condensation polymerisation produces:","options":["Only polymer","Polymer and a small molecule such as water","Only water","Only oxygen"],"answer":1,"explanation":"Condensation polymerisation releases small molecules such as water."},{"subject":"chemistry","q":"Nylon is produced by:","options":["Electrolysis","Neutralisation","Condensation polymerisation","Rusting"],"answer":2,"explanation":"Nylon is a condensation polymer."},{"subject":"chemistry","q":"Which property makes plastics useful?","options":["They rust easily","They conduct electricity well","They are lightweight and durable","They dissolve in water"],"answer":2,"explanation":"Most plastics are strong, lightweight and durable."},{"subject":"chemistry","q":"Which property is common in many synthetic polymers?","options":["Resistance to chemicals","High reactivity","Solubility in water","Rapid decomposition"],"answer":0,"explanation":"Many synthetic polymers are resistant to chemicals and corrosion."},{"subject":"chemistry","q":"Thermoplastics:","options":["Cannot be reshaped after heating","Can be softened repeatedly by heating","Burn immediately","Are natural polymers"],"answer":1,"explanation":"Thermoplastics soften on heating and can be remoulded."},{"subject":"chemistry","q":"Which of the following is a thermoplastic?","options":["Polythene","Bakelite","Melamine","Epoxy resin"],"answer":0,"explanation":"Polythene is a common thermoplastic."},{"subject":"chemistry","q":"Thermosetting polymers:","options":["Melt repeatedly when heated","Become permanently hard after heating","Dissolve in water","Are always transparent"],"answer":1,"explanation":"Thermosetting plastics cannot be remelted once set."},{"subject":"chemistry","q":"Which of the following is a thermosetting polymer?","options":["PVC","Polythene","Bakelite","Polypropene"],"answer":2,"explanation":"Bakelite is a common thermosetting plastic."},{"subject":"chemistry","q":"Why are thermosetting plastics used for electric plugs?","options":["They soften easily","They conduct electricity","They resist heat and maintain shape","They dissolve in water"],"answer":2,"explanation":"Thermosetting plastics are heat resistant and good insulators."},{"subject":"chemistry","q":"Which polymer is commonly used in packaging materials?","options":["Polyethene","Bakelite","Melamine","Teflon"],"answer":0,"explanation":"Polyethene is widely used for bags and packaging."},{"subject":"chemistry","q":"An environmental problem associated with plastics is that they:","options":["Decompose very quickly","Are biodegradable within days","Persist in the environment for long periods","Improve soil fertility"],"answer":2,"explanation":"Many plastics are non-biodegradable and accumulate as waste."},{"subject":"chemistry","q":"Which statement about polymers is correct?","options":["All polymers are natural","All polymers conduct electricity","Polymers are made from repeating monomer units","Polymers cannot be recycled"],"answer":2,"explanation":"Polymers consist of repeating monomer units linked together."},{"subject":"chemistry","q":"Which of the following is a natural source of water?","options":["Plastic tank","River","Tap","Bucket"],"answer":1,"explanation":"Rivers are natural sources of water, along with lakes, oceans, and springs."},{"subject":"chemistry","q":"The continuous movement of water between the earth and atmosphere is called:","options":["Water treatment","Water purification","Water cycle","Water balance"],"answer":2,"explanation":"The water cycle involves evaporation, condensation, and precipitation."},{"subject":"chemistry","q":"Which process changes liquid water into water vapour?","options":["Condensation","Evaporation","Freezing","Melting"],"answer":1,"explanation":"Evaporation occurs when water gains heat and turns into vapour."},{"subject":"chemistry","q":"Which process forms clouds?","options":["Freezing","Melting","Evaporation","Condensation"],"answer":3,"explanation":"Water vapour cools and condenses to form clouds."},{"subject":"chemistry","q":"Pure water boils at:","options":["0Ã‚Â°C","50Ã‚Â°C","100Ã‚Â°C","120Ã‚Â°C"],"answer":2,"explanation":"At standard atmospheric pressure, pure water boils at 100Ã‚Â°C."},{"subject":"chemistry","q":"Pure water freezes at:","options":["0Ã‚Â°C","10Ã‚Â°C","32Ã‚Â°C","100Ã‚Â°C"],"answer":0,"explanation":"Pure water freezes at 0Ã‚Â°C."},{"subject":"chemistry","q":"Which of the following is a physical property of pure water?","options":["Blue litmus turns red","It is colourless","It burns easily","It reacts with all metals"],"answer":1,"explanation":"Pure water is colourless, odourless, and tasteless."},{"subject":"chemistry","q":"Water is important because it:","options":["Supports life","Is used in agriculture","Is used in industry","All of the above"],"answer":3,"explanation":"Water is essential for living organisms, agriculture, and industrial activities."},{"subject":"chemistry","q":"Water hardness is mainly caused by:","options":["Oxygen","Nitrogen","Calcium and magnesium salts","Sodium chloride"],"answer":2,"explanation":"Dissolved calcium and magnesium compounds cause water hardness."},{"subject":"chemistry","q":"Temporary hardness is caused by:","options":["Calcium bicarbonate","Sodium chloride","Potassium nitrate","Hydrochloric acid"],"answer":0,"explanation":"Temporary hardness is due to dissolved bicarbonates of calcium and magnesium."},{"subject":"chemistry","q":"Temporary hardness can be removed by:","options":["Filtration only","Boiling","Freezing","Distillation only"],"answer":1,"explanation":"Boiling decomposes bicarbonates that cause temporary hardness."},{"subject":"chemistry","q":"Permanent hardness is caused by:","options":["Bicarbonates","Sulphates and chlorides of calcium and magnesium","Sand particles","Dissolved oxygen"],"answer":1,"explanation":"Permanent hardness results from sulphates and chlorides."},{"subject":"chemistry","q":"Which method can remove permanent hardness?","options":["Boiling only","Filtration only","Ion exchange or washing soda","Cooling"],"answer":2,"explanation":"Permanent hardness is commonly removed by ion-exchange methods or washing soda."},{"subject":"chemistry","q":"Water pollution is:","options":["Addition of harmful substances to water","Removal of dissolved salts","Water evaporation","Water freezing"],"answer":0,"explanation":"Water pollution occurs when contaminants enter water bodies."},{"subject":"chemistry","q":"Which is a major cause of water pollution?","options":["Planting trees","Proper waste disposal","Industrial waste discharge","Rainfall"],"answer":2,"explanation":"Industrial effluents can contaminate rivers and lakes."},{"subject":"chemistry","q":"Water suitable for drinking is called:","options":["Hard water","Soft water","Potable water","Distilled water"],"answer":2,"explanation":"Potable water is safe for human consumption."},{"subject":"chemistry","q":"Which disease may spread through contaminated water?","options":["Cholera","Malaria","Influenza","Measles"],"answer":0,"explanation":"Cholera is a common water-borne disease."},{"subject":"chemistry","q":"Which human activity contributes to atmospheric pollution?","options":["Tree planting","Vehicle emissions","Recycling","Soil conservation"],"answer":1,"explanation":"Vehicles release pollutants into the atmosphere."},{"subject":"chemistry","q":"Which of the following helps protect water quality?","options":["Dumping waste in rivers","Treating sewage before discharge","Washing vehicles in streams","Oil spillage"],"answer":1,"explanation":"Sewage treatment reduces water contamination."},{"subject":"chemistry","q":"Which statement about water is correct?","options":["Water is unnecessary for life","Pure water has no boiling point","Water is essential for living organisms","All water is polluted"],"answer":2,"explanation":"Water is vital for biological processes and survival"},{"subject":"chemistry","q":"Which gas is the main greenhouse gas?","options":["Oxygen","Nitrogen","Carbon dioxide","Helium"],"answer":2,"explanation":"Carbon dioxide traps heat in the atmosphere and is a major greenhouse gas."},{"subject":"chemistry","q":"Greenhouse gases cause:","options":["Global cooling only","Global warming","Ozone formation only","Acid formation only"],"answer":1,"explanation":"Greenhouse gases trap heat and increase Earth\u0027s temperature."},{"subject":"chemistry","q":"Which of the following is a greenhouse gas?","options":["Oxygen","Nitrogen","Methane","Argon"],"answer":2,"explanation":"Methane is a powerful greenhouse gas."},{"subject":"chemistry","q":"Which natural disaster may affect the atmosphere?","options":["Volcanic eruption","Reading books","Exercising","Cooking food only"],"answer":0,"explanation":"Volcanic eruptions release gases and particles into the atmosphere."},{"subject":"chemistry","q":"Global warming refers to:","options":["Falling global temperatures","Increase in the Earth\u0027s average temperature","Increase in rainfall only","Formation of clouds only"],"answer":1,"explanation":"Global warming is the gradual rise in Earth\u0027s average temperature."},{"subject":"chemistry","q":"Which human activity increases carbon dioxide levels?","options":["Afforestation","Burning fossil fuels","Water conservation","Recycling paper"],"answer":1,"explanation":"Fossil fuel combustion releases large amounts of carbon dioxide."},{"subject":"chemistry","q":"Which layer protects Earth from harmful ultraviolet radiation?","options":["Troposphere","Mesosphere","Ozone layer","Exosphere"],"answer":2,"explanation":"The ozone layer absorbs most harmful ultraviolet radiation from the sun."},{"subject":"chemistry","q":"The ozone layer is mainly composed of:","options":["OÃ¢â€šâ€š molecules","OÃ¢â€šÆ’ molecules","COÃ¢â€šâ€š molecules","HÃ¢â€šâ€š molecules"],"answer":1,"explanation":"Ozone consists of three oxygen atoms (OÃ¢â€šÆ’)."},{"subject":"chemistry","q":"Which chemicals are largely responsible for ozone depletion?","options":["Chlorofluorocarbons (CFCs)","Hydrogen gas","Nitrogen gas","Water vapour"],"answer":0,"explanation":"CFCs break down ozone molecules in the stratosphere."},{"subject":"chemistry","q":"Ozone depletion leads to:","options":["Reduced UV radiation","Increased UV radiation reaching Earth","Less sunlight","Increased oxygen production"],"answer":1,"explanation":"A thinner ozone layer allows more UV radiation to reach Earth."},{"subject":"chemistry","q":"An effect of excessive UV radiation is:","options":["Increased crop growth only","Skin cancer","Better eyesight","More rainfall"],"answer":1,"explanation":"Increased exposure to UV rays can cause skin cancer and eye damage."},{"subject":"chemistry","q":"Which greenhouse gas is produced in large quantities by livestock?","options":["Methane","Oxygen","Helium","Neon"],"answer":0,"explanation":"Cattle and other livestock release methane during digestion."},{"subject":"chemistry","q":"Which of the following helps reduce global warming?","options":["Deforestation","Burning coal","Planting trees","Increasing fuel consumption"],"answer":2,"explanation":"Trees absorb carbon dioxide from the atmosphere."},{"subject":"chemistry","q":"Air quality refers to:","options":["The amount of soil present","The cleanliness of the atmosphere","The amount of water available","The number of clouds present"],"answer":1,"explanation":"Air quality describes how clean or polluted the air is."},{"subject":"chemistry","q":"Which gas released from factories contributes to the greenhouse effect?","options":["Carbon dioxide","Helium","Hydrogen","Neon"],"answer":0,"explanation":"Industries release carbon dioxide through fuel combustion."},{"subject":"chemistry","q":"What is the greenhouse effect?","options":["Cooling of Earth\u0027s surface","Trapping of heat by atmospheric gases","Formation of oxygen","Water purification process"],"answer":1,"explanation":"Greenhouse gases absorb and re-radiate heat, warming the atmosphere."},{"subject":"chemistry","q":"Which of the following is a consequence of global warming?","options":["Rising sea levels","Reduced evaporation","Increased ozone formation","Reduced temperatures worldwide"],"answer":0,"explanation":"Melting ice caps contribute to rising sea levels."},{"subject":"chemistry","q":"Ozone depletion mainly occurs in the:","options":["Hydrosphere","Lithosphere","Stratosphere","Biosphere"],"answer":2,"explanation":"The ozone layer is found in the stratosphere."},{"subject":"chemistry","q":"Which action helps protect the ozone layer?","options":["Using CFC-based products","Increasing aerosol use with CFCs","Using ozone-friendly products","Burning plastics openly"],"answer":2,"explanation":"Ozone-friendly products reduce ozone depletion."},{"subject":"chemistry","q":"Which statement is correct?","options":["The ozone hole causes global warming directly","Greenhouse gases and ozone are the same thing","The ozone layer protects life by absorbing UV radiation","Carbon dioxide destroys the ozone layer directly"],"answer":2,"explanation":"The ozone layer plays a vital role in protecting living organisms from harmful UV rays."},{"subject":"chemistry","q":"What is waste?","options":["Useful material only","Unwanted material that is discarded","Pure water","Oxygen gas"],"answer":1,"explanation":"Waste refers to unwanted materials that are no longer useful and are discarded."},{"subject":"chemistry","q":"Waste can be classified into:","options":["Solid and liquid waste","Green and blue waste only","Acidic and basic waste only","Hot and cold waste"],"answer":0,"explanation":"Waste is commonly classified as solid or liquid waste."},{"subject":"chemistry","q":"Which of the following is an example of solid waste?","options":["Sewage","Wastewater","Plastic bottle","Industrial effluent"],"answer":2,"explanation":"Plastic bottles are examples of solid waste materials."},{"subject":"chemistry","q":"Which of the following is an example of liquid waste?","options":["Old newspapers","Glass bottles","Sewage","Food wrappers"],"answer":2,"explanation":"Sewage is a common form of liquid waste."},{"subject":"chemistry","q":"Which is a major source of waste?","options":["Homes","Industries","Hospitals","All of the above"],"answer":3,"explanation":"Waste is generated by households, industries, hospitals and many other activities."},{"subject":"chemistry","q":"Biodegradable waste is waste that:","options":["Cannot decay naturally","Can be broken down by microorganisms","Is made of metal only","Lasts forever"],"answer":1,"explanation":"Biodegradable waste decomposes naturally through the action of microorganisms."},{"subject":"chemistry","q":"Which of the following is biodegradable?","options":["Plastic bag","Glass bottle","Food remains","Aluminium can"],"answer":2,"explanation":"Food waste decomposes naturally."},{"subject":"chemistry","q":"Which material is non-biodegradable?","options":["Grass","Paper","Plastic","Fruit peels"],"answer":2,"explanation":"Plastics take a very long time to decompose."},{"subject":"chemistry","q":"What is recycling?","options":["Burning waste only","Converting waste materials into new useful products","Burying waste","Throwing waste into rivers"],"answer":1,"explanation":"Recycling reduces waste by reprocessing materials into useful products."},{"subject":"chemistry","q":"Which material is commonly recycled?","options":["Plastic","Paper","Glass","All of the above"],"answer":3,"explanation":"Plastic, paper and glass can all be recycled."},{"subject":"chemistry","q":"Composting is mainly used for:","options":["Plastic waste","Metal waste","Organic waste","Glass waste"],"answer":2,"explanation":"Composting converts organic materials into manure."},{"subject":"chemistry","q":"A landfill is a place where:","options":["Water is purified","Waste is disposed of by burial","Electricity is generated only","Metals are extracted"],"answer":1,"explanation":"Landfills are designated sites for waste disposal."},{"subject":"chemistry","q":"Open dumping of waste can:","options":["Improve sanitation","Cause pollution and disease","Purify water","Improve air quality"],"answer":1,"explanation":"Open dumping attracts pests and contaminates the environment."},{"subject":"chemistry","q":"Which method is used to treat liquid waste?","options":["Sewage treatment","Recycling paper","Composting","Incineration only"],"answer":0,"explanation":"Sewage treatment removes contaminants from wastewater."},{"subject":"chemistry","q":"Incineration is:","options":["Waste disposal by burning","Waste disposal by freezing","Waste disposal by dissolving","Waste disposal by filtration"],"answer":0,"explanation":"Incineration reduces waste volume through controlled burning."},{"subject":"chemistry","q":"The best approach to waste management is:","options":["Produce more waste","Ignore waste","Reduce, reuse and recycle","Dump waste in rivers"],"answer":2,"explanation":"The 3Rs help minimise environmental pollution."},{"subject":"chemistry","q":"Which disease can result from poor waste management?","options":["Cholera","Typhoid","Dysentery","All of the above"],"answer":3,"explanation":"Poor sanitation can spread several diseases."},{"subject":"chemistry","q":"Which practice helps reduce waste?","options":["Reusing containers","Littering","Burning plastics in open spaces","Dumping rubbish in streams"],"answer":0,"explanation":"Reuse extends the useful life of materials."},{"subject":"chemistry","q":"Industrial waste should be:","options":["Released untreated into rivers","Properly treated before disposal","Dumped anywhere","Mixed with drinking water"],"answer":1,"explanation":"Treatment reduces environmental contamination."},{"subject":"chemistry","q":"Why is proper waste management important?","options":["It protects human health","It protects the environment","It reduces pollution","All of the above"],"answer":3,"explanation":"Proper waste management benefits both people and the environment"},{"subject":"physics","q":"What is a fundamental quantity?","options":["A quantity derived from other quantities","A quantity that cannot be expressed in terms of other quantities","A quantity measured in joules","A quantity measured in pascals"],"answer":1,"explanation":"Fundamental quantities are basic physical quantities that are not derived from other quantities. Examples include length, mass, and time."},{"subject":"physics","q":"Which of the following is a fundamental quantity?","options":["Energy","Pressure","Length","Force"],"answer":2,"explanation":"Length is a fundamental quantity measured in metres (m)."},{"subject":"physics","q":"What is the SI unit of mass?","options":["Gram (g)","Kilogram (kg)","Newton (N)","Pound (lb)"],"answer":1,"explanation":"The SI unit of mass is the kilogram (kg)."},{"subject":"physics","q":"Which of the following is a derived quantity?","options":["Time","Length","Mass","Energy"],"answer":3,"explanation":"Energy is a derived quantity because it is expressed using fundamental quantities."},{"subject":"physics","q":"What is the SI unit of pressure?","options":["Newton","Watt","Pascal","Joule"],"answer":2,"explanation":"Pressure is measured in pascals (Pa)."},{"subject":"physics","q":"Express 1,000,000 in standard form.","options":["1 Ãƒâ€” 10Ã¢ÂÂ»Ã¢ÂÂ¶","1 Ãƒâ€” 10Ã¢ÂÂ¶","10 Ãƒâ€” 10Ã¢ÂÂµ","100 Ãƒâ€” 10Ã¢ÂÂ´"],"answer":1,"explanation":"Standard form expresses numbers as a value between 1 and 10 multiplied by a power of ten."},{"subject":"physics","q":"What is the prefix for 10Ã¢ÂÂ»Ã‚Â³?","options":["Kilo","Mega","Milli","Centi"],"answer":2,"explanation":"Milli represents one-thousandth (10Ã¢ÂÂ»Ã‚Â³)."},{"subject":"physics","q":"What is the prefix for 10Ã‚Â³?","options":["Centi","Kilo","Mega","Deci"],"answer":1,"explanation":"Kilo means one thousand (10Ã‚Â³)."},{"subject":"physics","q":"Which instrument is commonly used to measure large lengths?","options":["Vernier calliper","Micrometer screw gauge","Metre rule","Ammeter"],"answer":2,"explanation":"A metre rule is suitable for measuring relatively large lengths."},{"subject":"physics","q":"Which instrument is most suitable for measuring the diameter of a small rod?","options":["Stopwatch","Vernier calliper","Measuring cylinder","Beam balance"],"answer":1,"explanation":"A Vernier calliper measures small lengths accurately, including diameters."},{"subject":"physics","q":"What is the least count of a Vernier calliper?","options":["1 cm","0.1 cm","0.01 cm","1 mm"],"answer":2,"explanation":"The least count of a standard Vernier calliper is 0.01 cm."},{"subject":"physics","q":"Which instrument is best for measuring the thickness of a paper?","options":["Vernier calliper","Micrometer screw gauge","Tape measure","Thermometer"],"answer":1,"explanation":"A micrometer screw gauge is used for very small measurements such as paper thickness."},{"subject":"physics","q":"What is the SI unit of time?","options":["Minute","Hour","Second","Day"],"answer":2,"explanation":"The SI unit of time is the second (s)."},{"subject":"physics","q":"What is a pendulum?","options":["A device for measuring mass","A bob suspended by a string from a fixed point","A device for measuring temperature","An electric circuit component"],"answer":1,"explanation":"A pendulum consists of a mass suspended by a light string from a fixed point."},{"subject":"physics","q":"What is the period of a pendulum?","options":["Time taken for half an oscillation","Time taken for one complete oscillation","Time taken for ten oscillations","Time between two experiments"],"answer":1,"explanation":"The period is the time taken for one complete oscillation."},{"subject":"physics","q":"What is volume?","options":["Mass of an object","Space occupied by an object","Density of an object","Weight of an object"],"answer":1,"explanation":"Volume is the space occupied by an object."},{"subject":"physics","q":"What is a scientific investigation?","options":["A random experiment","A systematic way of finding solutions to problems","A classroom test","A type of measurement"],"answer":1,"explanation":"Scientific investigation is a systematic way used by scientists to find solutions to problems or answers to questions."},{"subject":"physics","q":"What should be stated first when designing a scientific investigation?","options":["Results","Conclusion","Topic or problem to be solved","References"],"answer":2,"explanation":"The first step is stating the topic or problem clearly and precisely."},{"subject":"physics","q":"A proposed explanation given as a starting point for investigation is called:","options":["Theory","Hypothesis","Variable","Observation"],"answer":1,"explanation":"A hypothesis is a proposed explanation based on limited evidence."},{"subject":"physics","q":"In SMART objectives, the letter \"S\" stands for:","options":["Standard","Suitable","Specific","Scientific"],"answer":2,"explanation":"SMART objectives should be Specific, Achievable, Realistic, and Time-bound."},{"subject":"physics","q":"Which variable is controlled by the researcher?","options":["Dependent variable","Controlled variable","Independent variable","Random variable"],"answer":2,"explanation":"The independent variable is deliberately changed by the researcher."},{"subject":"physics","q":"Which variable responds to changes in the independent variable?","options":["Controlled variable","Dependent variable","Constant variable","Fixed variable"],"answer":1,"explanation":"The dependent variable changes as a result of variations in the independent variable."},{"subject":"physics","q":"Which variable is deliberately kept constant?","options":["Independent variable","Dependent variable","Controlled variable","Test variable"],"answer":2,"explanation":"Controlled variables are kept constant to ensure a fair test."},{"subject":"physics","q":"Apparatus used in an investigation should:","options":["Be expensive","Give accurate readings","Be colourful","Be large"],"answer":1,"explanation":"Apparatus should provide readings with the expected degree of accuracy."},{"subject":"physics","q":"Which of the following is a method of collecting data?","options":["Singing","Recording observations in tables","Guessing","Debating"],"answer":1,"explanation":"Tables are commonly used for collecting and recording data."},{"subject":"physics","q":"Which of the following can be used to analyse data?","options":["Graphs and charts","Songs","Stories","Maps only"],"answer":0,"explanation":"Graphs and charts are tools used in data analysis."},{"subject":"physics","q":"Raw data collected in an experiment should be:","options":["Ignored","Destroyed","Analysed","Memorised only"],"answer":2,"explanation":"Raw data must be analysed to obtain meaningful information."},{"subject":"physics","q":"Which axis is usually used for the dependent variable on a graph?","options":["Horizontal axis","Vertical axis","Diagonal axis","No axis"],"answer":1,"explanation":"The dependent variable is normally plotted on the vertical (y) axis."},{"subject":"physics","q":"The horizontal axis of a graph is called:","options":["Y-axis","Z-axis","X-axis","T-axis"],"answer":2,"explanation":"A graph has a horizontal x-axis and a vertical y-axis."},{"subject":"physics","q":"The slope of a graph is calculated as:","options":["X ÃƒÂ· Y","Change in Y ÃƒÂ· Change in X","X + Y","X Ãƒâ€” Y"],"answer":1,"explanation":"Slope = Change in vertical axis ÃƒÂ· Change in horizontal axis."},{"subject":"physics","q":"What is an experimental error?","options":["Correct measurement","Difference between measured and true value","Size of apparatus","Type of graph"],"answer":1,"explanation":"An error is the difference between a measurement and the accepted value."},{"subject":"physics","q":"Which error arises from faults in measuring instruments?","options":["Random error","Environmental error","Systematic error","Human error"],"answer":2,"explanation":"Systematic errors originate from instrument faults."},{"subject":"physics","q":"What is a zero error?","options":["An instrument reading when it should read zero","A graph error","A mathematical error","A random mistake"],"answer":0,"explanation":"Zero error occurs when an instrument does not read zero correctly."},{"subject":"physics","q":"Which error can be reduced by taking repeated measurements and averaging them?","options":["Systematic error","Random error","Zero error","Calibration error"],"answer":1,"explanation":"Averaging repeated measurements helps reduce random errors."},{"subject":"physics","q":"Which section of a laboratory report contains analysed and interpreted results?","options":["Materials","Methods","Discussion","References"],"answer":2,"explanation":"The discussion section explains and interprets the results."},{"subject":"physics","q":"Which section of a laboratory report lists books and websites used?","options":["Introduction","Aim","Conclusion","References"],"answer":3,"explanation":"References contain all sources consulted during the investigation."},{"subject":"physics","q":"The temperature at which a solid changes to a liquid is called:","options":["Boiling point","Freezing point","Melting point","Condensation point"],"answer":2,"explanation":"Melting point is the temperature at which a solid begins to flow and become a liquid."},{"subject":"physics","q":"Gas laws describe the relationship between:","options":["Mass and density","Pressure, temperature and volume","Force and energy","Distance and time"],"answer":1,"explanation":"Gas laws describe how pressure, temperature and volume are related in a fixed mass of gas."},{"subject":"physics","q":"Which of the following is NOT a gas law?","options":["Boyle\u0027s Law","Charles\u0027 Law","Pressure Law","Ohm\u0027s Law"],"answer":3,"explanation":"Ohm\u0027s Law relates current and voltage, not gases."},{"subject":"physics","q":"The Pressure Law states that for a fixed mass of gas at constant volume, pressure is directly proportional to:","options":["Volume","Mass","Temperature in Kelvin","Density"],"answer":2,"explanation":"Pressure increases as Kelvin temperature increases when volume is constant."},{"subject":"physics","q":"In the Pressure Law, which quantity remains constant?","options":["Temperature","Pressure","Volume","Mass"],"answer":2,"explanation":"The Pressure Law applies at constant volume."},{"subject":"physics","q":"Boyle\u0027s Law states that for a fixed mass of gas at constant temperature, volume is:","options":["Directly proportional to pressure","Inversely proportional to pressure","Equal to pressure","Independent of pressure"],"answer":1,"explanation":"As pressure increases, volume decreases."},{"subject":"physics","q":"Which quantity remains constant in Boyle\u0027s Law?","options":["Pressure","Volume","Temperature","Mass"],"answer":2,"explanation":"Boyle\u0027s Law applies at constant temperature."},{"subject":"physics","q":"If the pressure of a gas doubles at constant temperature, its volume will:","options":["Double","Triple","Remain constant","Halve"],"answer":3,"explanation":"According to Boyle\u0027s Law, volume is inversely proportional to pressure."},{"subject":"physics","q":"Charles\u0027 Law states that volume is directly proportional to:","options":["Pressure","Temperature in Kelvin","Density","Mass"],"answer":1,"explanation":"Charles\u0027 Law relates volume directly to Kelvin temperature at constant pressure."},{"subject":"physics","q":"Which quantity remains constant in Charles\u0027 Law?","options":["Pressure","Temperature","Volume","Density"],"answer":0,"explanation":"Charles\u0027 Law applies when pressure is constant."},{"subject":"physics","q":"Before using Charles\u0027 Law, temperature must be expressed in:","options":["Celsius","Fahrenheit","Kelvin","Rankine"],"answer":2,"explanation":"Temperatures must be converted to Kelvin for gas law calculations."},{"subject":"physics","q":"The combined gas law includes:","options":["Pressure only","Volume only","Temperature only","Pressure, volume and temperature"],"answer":3,"explanation":"The combined gas law relates all three variables."},{"subject":"physics","q":"Which equation represents Boyle\u0027s Law?","options":["V/T = constant","P/T = constant","PV = constant","P + V = constant"],"answer":2,"explanation":"Boyle\u0027s Law states that the product of pressure and volume remains constant."},{"subject":"physics","q":"According to kinetic theory, gases are made up of:","options":["Large particles at rest","Tiny particles in constant random motion","Liquids only","Solid particles only"],"answer":1,"explanation":"Gas molecules are in continuous random motion."},{"subject":"physics","q":"Gas particles move in:","options":["Circular paths only","Straight lines between collisions","Fixed positions","Zigzag paths only"],"answer":1,"explanation":"Gas particles move in straight lines until collisions occur."},{"subject":"physics","q":"Collisions between gas particles are assumed to be:","options":["Inelastic","Weak","Elastic","Impossible"],"answer":2,"explanation":"The kinetic theory assumes all collisions are perfectly elastic."},{"subject":"physics","q":"The force of attraction between gas particles is assumed to be:","options":["Very strong","Moderate","Negligible","Infinite"],"answer":2,"explanation":"Ideal gas particles have negligible attractive forces."},{"subject":"physics","q":"An ideal gas obeys:","options":["Some assumptions of kinetic theory","None of the assumptions","All assumptions of kinetic theory","Boyle\u0027s Law only"],"answer":2,"explanation":"An ideal gas satisfies all assumptions of kinetic theory."},{"subject":"physics","q":"When the temperature of a gas increases at constant volume, the pressure:","options":["Decreases","Remains constant","Increases","Becomes zero"],"answer":2,"explanation":"Pressure is directly proportional to Kelvin temperature."},{"subject":"physics","q":"A gas occupies 20 mÃ‚Â³ at 300 K. At constant pressure, its volume becomes 40 mÃ‚Â³. The new temperature is:","options":["150 K","300 K","450 K","600 K"],"answer":3,"explanation":"Using Charles\u0027 Law: TÃ¢â€šâ€š = (40 Ãƒâ€” 300) ÃƒÂ· 20 = 600 K."},{"subject":"physics","q":"If a gas has volume 100 L at 100 kPa and is compressed to 10 L at constant temperature, the new pressure is:","options":["10 kPa","100 kPa","500 kPa","1000 kPa"],"answer":3,"explanation":"Using Boyle\u0027s Law: PÃ¢â€šâ€š = (100 Ãƒâ€” 100) ÃƒÂ· 10 = 1000 kPa."},{"subject":"physics","q":"A scalar quantity has:","options":["Magnitude and direction","Direction only","Magnitude only","Neither magnitude nor direction"],"answer":2,"explanation":"Scalar quantities have magnitude (size) only."},{"subject":"physics","q":"Which of the following is a scalar quantity?","options":["Velocity","Acceleration","Displacement","Mass"],"answer":3,"explanation":"Mass has magnitude only and no direction."},{"subject":"physics","q":"Which of the following is a vector quantity?","options":["Distance","Speed","Velocity","Volume"],"answer":2,"explanation":"Velocity has both magnitude and direction."},{"subject":"physics","q":"Which quantity is a vector?","options":["Energy","Area","Momentum","Density"],"answer":2,"explanation":"Momentum has both magnitude and direction."},{"subject":"physics","q":"Which one is NOT a scalar quantity?","options":["Pressure","Temperature","Distance","Acceleration"],"answer":3,"explanation":"Acceleration is a vector quantity."},{"subject":"physics","q":"A vector is represented by:","options":["A circle","A straight line with an arrowhead","A square","A dot"],"answer":1,"explanation":"The arrowhead shows direction while the line length shows magnitude."},{"subject":"physics","q":"In a vector diagram, the length of the line represents:","options":["Force only","Direction","Magnitude","Time"],"answer":2,"explanation":"The length corresponds to the magnitude of the vector."},{"subject":"physics","q":"The arrowhead on a vector represents:","options":["Mass","Speed","Direction","Distance"],"answer":2,"explanation":"The arrowhead indicates the direction of the vector."},{"subject":"physics","q":"The sum of two or more vectors is called the:","options":["Component","Gradient","Resultant","Magnitude"],"answer":2,"explanation":"The vector obtained after addition is called the resultant vector."},{"subject":"physics","q":"What is the resultant of 7 N and 12 N acting in the same direction?","options":["5 N","12 N","19 N","84 N"],"answer":2,"explanation":"7 N + 12 N = 19 N."},{"subject":"physics","q":"What is the resultant of 18 N and 10 N acting in opposite directions?","options":["8 N","28 N","180 N","10 N"],"answer":0,"explanation":"Subtract the smaller force from the larger force: 18 N Ã¢Ë†â€™ 10 N = 8 N."},{"subject":"physics","q":"Which method can be used to add non-parallel vectors?","options":["Titration method","Triangle rule","Barometer method","Density method"],"answer":1,"explanation":"The triangle rule is used to add vectors graphically."},{"subject":"physics","q":"In the parallelogram method, the resultant is:","options":["One side of the parallelogram","The area of the parallelogram","The diagonal of the parallelogram","The perimeter"],"answer":2,"explanation":"The diagonal drawn from the common point represents the resultant vector."},{"subject":"physics","q":"A vector can be resolved into:","options":["Two masses","Horizontal and vertical components","Temperature and pressure","Work and energy"],"answer":1,"explanation":"Any vector can be split into horizontal and vertical components."},{"subject":"physics","q":"The vertical component of a vector aaa at angle ÃŽÂ¸ is:","options":["a cos ÃŽÂ¸","a tan ÃŽÂ¸","a sin ÃŽÂ¸","aÃ‚Â²"],"answer":2,"explanation":"Vertical component = a sin ÃŽÂ¸."},{"subject":"physics","q":"The horizontal component of a vector aaa at angle ÃŽÂ¸ is:","options":["a cos ÃŽÂ¸","a sin ÃŽÂ¸","a tan ÃŽÂ¸","aÃ‚Â²"],"answer":0,"explanation":"Horizontal component = a cos ÃŽÂ¸."},{"subject":"physics","q":"Which of the following is a scalar quantity?","options":["Magnetic field","Velocity","Distance","Displacement"],"answer":2,"explanation":"Distance has magnitude only."},{"subject":"physics","q":"Which vector quantity describes the rate of change of velocity?","options":["Speed","Mass","Density","Acceleration"],"answer":3,"explanation":"Acceleration is a vector quantity because it has magnitude and direction."},{"subject":"physics","q":"When a vector is reversed, it is assigned:","options":["A positive value","A negative value","Zero value","Infinite value"],"answer":1,"explanation":"Reversing a vector changes its sign to negative."},{"subject":"physics","q":"Which of the following is NOT a vector quantity?","options":["Momentum","Acceleration","Displacement","Energy"],"answer":3,"explanation":"Energy is a scalar quantity because it has magnitude only."},{"subject":"physics","q":"Linear motion is:","options":["Motion in a circular path","Motion from one place to another","Motion of waves","Rotational motion"],"answer":1,"explanation":"Linear motion is the motion made by a body as it moves from one place to another."},{"subject":"physics","q":"Distance is defined as:","options":["The shortest route between two points","Total length of the path travelled","Change in position only","Speed multiplied by time"],"answer":1,"explanation":"Distance is the total length of the path between two points."},{"subject":"physics","q":"Displacement is:","options":["Total path covered","Distance travelled in a circle","Straight-line distance in a specific direction","Speed of an object"],"answer":2,"explanation":"Displacement is the straight-line distance between two points in a given direction."},{"subject":"physics","q":"The SI unit of displacement is:","options":["Kilometre","Metre","Centimetre","Millimetre"],"answer":1,"explanation":"The SI unit of displacement is the metre (m)."},{"subject":"physics","q":"Speed is:","options":["Distance moved per unit time","Displacement per unit time","Change in velocity","Force per unit area"],"answer":0,"explanation":"Speed is the distance travelled in a unit time."},{"subject":"physics","q":"The SI unit of speed is:","options":["km/h","m/s","cm/s","m/min"],"answer":1,"explanation":"The SI unit of speed is metres per second (m/s)."},{"subject":"physics","q":"Average speed is:","options":["Total distance ÃƒÂ· Total time","Total displacement ÃƒÂ· Total time","Distance Ãƒâ€” Time","Velocity Ãƒâ€” Time"],"answer":0,"explanation":"Average speed is the total distance covered divided by the total time taken."},{"subject":"physics","q":"Velocity is:","options":["Distance moved per unit time","Speed without direction","Displacement per unit time","Change in acceleration"],"answer":2,"explanation":"Velocity is displacement covered per unit time."},{"subject":"physics","q":"Velocity differs from speed because velocity includes:","options":["Distance","Time","Direction","Mass"],"answer":2,"explanation":"Velocity is a vector quantity and has direction."},{"subject":"physics","q":"The SI unit of velocity is:","options":["m/s","km/h","N/s","mÃ‚Â²/s"],"answer":0,"explanation":"Velocity is measured in metres per second (m/s)."},{"subject":"physics","q":"A ticker-tape timer makes how many vibrations each second?","options":["25","50","75","100"],"answer":1,"explanation":"A ticker-tape timer vibrates 50 times every second."},{"subject":"physics","q":"One vibration of a ticker-tape timer represents:","options":["0.01 s","0.02 s","0.05 s","0.20 s"],"answer":1,"explanation":"One vibration = 1/50 second = 0.02 s."},{"subject":"physics","q":"Acceleration is:","options":["Distance travelled per second","Rate of change of velocity","Speed multiplied by time","Change in displacement"],"answer":1,"explanation":"Acceleration is the rate of change of velocity with time."},{"subject":"physics","q":"The SI unit of acceleration is:","options":["m/s","mÃ‚Â²/s","m/sÃ‚Â²","km/sÃ‚Â²"],"answer":2,"explanation":"Acceleration is measured in metres per second squared (m/sÃ‚Â²)."},{"subject":"physics","q":"Negative acceleration is commonly called:","options":["Gravity","Velocity","Deceleration","Momentum"],"answer":2,"explanation":"Negative acceleration means the velocity is decreasing."},{"subject":"physics","q":"Acceleration due to gravity on Earth is approximately:","options":["5 m/sÃ‚Â²","8 m/sÃ‚Â²","9.8 m/sÃ‚Â²","10 m/sÃ‚Â²"],"answer":3,"explanation":"The notes use g = 10 m/sÃ‚Â²."},{"subject":"physics","q":"On a distance-time graph, the gradient represents:","options":["Velocity","Acceleration","Speed","Force"],"answer":2,"explanation":"Gradient of a distance-time graph gives speed."},{"subject":"physics","q":"On a displacement-time graph, the gradient represents:","options":["Speed","Velocity","Distance","Acceleration"],"answer":1,"explanation":"The gradient of a displacement-time graph gives velocity."},{"subject":"physics","q":"On a speed-time graph, the gradient represents:","options":["Distance","Velocity","Acceleration","Momentum"],"answer":2,"explanation":"Acceleration is the gradient of a speed-time graph."},{"subject":"physics","q":"The area under a speed-time graph represents:","options":["Acceleration","Velocity","Distance travelled","Force"],"answer":2,"explanation":"The area under a speed-time graph gives the distance covered by the object"},{"subject":"physics","q":"Work is defined as:","options":["Force Ãƒâ€” Time","Force Ãƒâ€” Distance moved in the direction of the force","Mass Ãƒâ€” Acceleration","Energy Ãƒâ€” Time"],"answer":1,"explanation":"Work is the product of force and distance moved in the direction of the force."},{"subject":"physics","q":"The SI unit of work is:","options":["Newton","Watt","Joule","Pascal"],"answer":2,"explanation":"Work is measured in joules (J)."},{"subject":"physics","q":"The formula for calculating work done is:","options":["W = ma","W = Fd","W = Pt","W = mvÃ‚Â²"],"answer":1,"explanation":"Work done equals force multiplied by distance moved."},{"subject":"physics","q":"A force of 20 N moves an object 5 m. What work is done?","options":["4 J","25 J","100 J","200 J"],"answer":2,"explanation":"W = Fd = 20 Ãƒâ€” 5 = 100 J."},{"subject":"physics","q":"The gravitational force acting on a body is called:","options":["Friction","Effort","Weight","Tension"],"answer":2,"explanation":"Weight is the gravitational force acting on a body."},{"subject":"physics","q":"Work done against gravity is calculated using:","options":["mgh","mvÃ‚Â²","FdÃ‚Â²","Pt"],"answer":0,"explanation":"Work done against gravity = mgh."},{"subject":"physics","q":"Potential energy is the energy due to:","options":["Motion","Heat","Height or position","Sound"],"answer":2,"explanation":"Potential energy is energy possessed because of position or height."},{"subject":"physics","q":"The formula for gravitational potential energy is:","options":["PE = mvÃ‚Â²","PE = mgh","PE = Pt","PE = F/t"],"answer":1,"explanation":"Gravitational potential energy equals mass Ãƒâ€” gravity Ãƒâ€” height."},{"subject":"physics","q":"Kinetic energy is the energy possessed by a body due to its:","options":["Height","Colour","Motion","Temperature"],"answer":2,"explanation":"Kinetic energy is energy a body possesses because it is moving."},{"subject":"physics","q":"The formula for kinetic energy is:","options":["mgh","Ã‚Â½mvÃ‚Â²","Fd","Pt"],"answer":1,"explanation":"Kinetic energy is calculated as Ã‚Â½mvÃ‚Â²."},{"subject":"physics","q":"A 2 kg object moving at 4 m/s has kinetic energy:","options":["8 J","12 J","16 J","32 J"],"answer":2,"explanation":"KE = Ã‚Â½ Ãƒâ€” 2 Ãƒâ€” 4Ã‚Â² = 16 J."},{"subject":"physics","q":"Elastic potential energy is stored in:","options":["A moving car","A stretched or compressed spring","Flowing water","Hot metal"],"answer":1,"explanation":"Elastic potential energy exists in stretched or compressed springs."},{"subject":"physics","q":"The formula for elastic potential energy is:","options":["Ã‚Â½Fe","Fd","mgh","mv"],"answer":0,"explanation":"Elastic potential energy = Ã‚Â½Fe, where e is extension."},{"subject":"physics","q":"According to the law of conservation of energy:","options":["Energy can be created","Energy can be destroyed","Energy can neither be created nor destroyed","Energy disappears during motion"],"answer":2,"explanation":"Energy can only be transformed from one form to another."},{"subject":"physics","q":"When an object falls freely:","options":["Potential energy increases","Kinetic energy decreases","Potential energy changes into kinetic energy","Energy is lost completely"],"answer":2,"explanation":"As an object falls, gravitational potential energy is converted into kinetic energy."},{"subject":"physics","q":"The energy-work theorem states that:","options":["Work equals force only","Net work done equals change in kinetic energy","Work equals potential energy only","Energy equals power Ãƒâ€” time"],"answer":1,"explanation":"The net work done on a body equals the change in its kinetic energy."},{"subject":"physics","q":"Which of the following is a unit of energy?","options":["Joule","Newton","Pascal","Metre"],"answer":0,"explanation":"Energy is measured in joules (J)."},{"subject":"physics","q":"A body of mass 5 kg is raised 4 m. Take g = 10 N/kg. What is its potential energy?","options":["50 J","100 J","150 J","200 J"],"answer":3,"explanation":"PE = mgh = 5 Ãƒâ€” 10 Ãƒâ€” 4 = 200 J."},{"subject":"physics","q":"If an object\u0027s kinetic energy increases, its speed:","options":["Decreases","Remains constant","Increases","Becomes zero"],"answer":2,"explanation":"Since KE = Ã‚Â½mvÃ‚Â², kinetic energy increases with speed."},{"subject":"physics","q":"Just before an object dropped from a height hits the ground, most of its energy is:","options":["Sound energy","Gravitational potential energy","Kinetic energy","Electrical energy"],"answer":2,"explanation":"As it falls, potential energy is converted into kinetic energy, which is greatest just before impact."},{"subject":"physics","q":"A machine is a device that:","options":["Produces electricity","Makes work easier","Measures force","Stores energy"],"answer":1,"explanation":"A machine is a device that makes work easier."},{"subject":"physics","q":"Mechanical Advantage (M.A.) is the ratio of:","options":["Effort to Load","Load to Effort","Distance to Time","Work to Energy"],"answer":1,"explanation":"Mechanical Advantage = Load ÃƒÂ· Effort."},{"subject":"physics","q":"The formula for mechanical advantage is:","options":["M.A. = Effort/Load","M.A. = Load Ãƒâ€” Effort","M.A. = Load/Effort","M.A. = Distance/Time"],"answer":2,"explanation":"Mechanical Advantage is calculated by dividing load by effort."},{"subject":"physics","q":"Velocity Ratio (V.R.) is:","options":["Load ÃƒÂ· Effort","Distance moved by effort ÃƒÂ· Distance moved by load","Work output ÃƒÂ· Work input","Power ÃƒÂ· Time"],"answer":1,"explanation":"Velocity Ratio compares the distance moved by the effort to that moved by the load."},{"subject":"physics","q":"Efficiency is:","options":["Input energy ÃƒÂ· Output energy Ãƒâ€” 100","Output energy ÃƒÂ· Input energy Ãƒâ€” 100","Load Ãƒâ€” Effort","Work Ãƒâ€” Time"],"answer":1,"explanation":"Efficiency is the percentage of input energy converted into useful output energy."},{"subject":"physics","q":"No machine is 100% efficient because:","options":["Energy is created","Some energy is lost due to friction","Machines have no load","Loads are too small"],"answer":1,"explanation":"Friction causes some energy to be lost in machines."},{"subject":"physics","q":"A machine used to lift a 400 N load with an 80 N effort has a mechanical advantage of:","options":["4","5","6","8"],"answer":1,"explanation":"M.A. = 400 ÃƒÂ· 80 = 5."},{"subject":"physics","q":"Which machine is a force multiplier?","options":["Bicycle gears","Hydraulic press","Speedometer","Thermometer"],"answer":1,"explanation":"Hydraulic presses allow a small effort to lift a large load."},{"subject":"physics","q":"Which machine is a distance or speed multiplier?","options":["Hydraulic jack","Wheelbarrow","Bicycle gears","Screw jack"],"answer":2,"explanation":"Bicycle gears increase the distance or speed moved by the load."},{"subject":"physics","q":"In a first-class lever, the ______ is between the load and effort.","options":["Force","Pivot (Fulcrum)","Wheel","Axle"],"answer":1,"explanation":"In a first-order lever, the pivot lies between the effort and load."},{"subject":"physics","q":"Which of the following is a first-class lever?","options":["Wheelbarrow","Bottle opener","Crowbar","Fishing rod"],"answer":2,"explanation":"A crowbar is a first-order lever."},{"subject":"physics","q":"In a second-class lever, the ______ is between the pivot and effort.","options":["Load","Wheel","Force","Rope"],"answer":0,"explanation":"Second-order levers have the load between the pivot and effort."},{"subject":"physics","q":"Which of the following is a second-class lever?","options":["Tweezers","Fishing rod","Wheelbarrow","Spanner"],"answer":2,"explanation":"A wheelbarrow is a second-order lever."},{"subject":"physics","q":"In a third-class lever, the ______ is between the pivot and load.","options":["Effort","Wheel","Friction","Gravity"],"answer":0,"explanation":"Third-order levers have the effort between the pivot and load."},{"subject":"physics","q":"Which of the following is a third-class lever?","options":["Wheelbarrow","Fishing rod","Seesaw","Claw hammer"],"answer":1,"explanation":"A fishing rod is a third-order lever."},{"subject":"physics","q":"A pulley with a fixed support that does not move is called:","options":["Moving pulley","Block and tackle","Single fixed pulley","Wheel and axle"],"answer":2,"explanation":"A single fixed pulley has a fixed point of support."},{"subject":"physics","q":"The mechanical advantage of an ideal single fixed pulley is:","options":["1","2","3","4"],"answer":0,"explanation":"For an ideal fixed pulley, load equals effort, so M.A. = 1."},{"subject":"physics","q":"The mechanical advantage of an ideal single moving pulley is:","options":["1","2","3","4"],"answer":1,"explanation":"In a single moving pulley, the load is twice the effort."},{"subject":"physics","q":"The distance between two successive threads of a screw is called:","options":["Radius","Diameter","Pitch","Circumference"],"answer":2,"explanation":"The distance between adjacent screw threads is called the pitch."},{"subject":"physics","q":"Which of the following is an example of a wheel and axle?","options":["Thermometer","Syringe","Screwdriver","Hydrometer"],"answer":2,"explanation":"A screwdriver is a common example of a wheel-and-axle machine"},{"subject":"physics","q":"Electric current is:","options":["Energy stored in a battery","The rate of flow of charge","Force acting on a wire","Resistance to current flow"],"answer":1,"explanation":"Electric current is the rate at which electric charge flows."},{"subject":"physics","q":"Electric current is mainly due to the movement of:","options":["Protons","Neutrons","Electrons","Molecules"],"answer":2,"explanation":"Electric current in a conductor is produced by moving electrons."},{"subject":"physics","q":"The path through which electric current flows is called:","options":["Circuit","Resistor","Generator","Fuse"],"answer":0,"explanation":"The conducting path through which electrons move is called an electric circuit."},{"subject":"physics","q":"The SI unit of electric current is:","options":["Volt","Ohm","Coulomb","Ampere"],"answer":3,"explanation":"Electric current is measured in amperes (A)."},{"subject":"physics","q":"The formula for current is:","options":["I = V/R","I = Q/t","I = Pt","I = F/A"],"answer":1,"explanation":"Current equals charge divided by time."},{"subject":"physics","q":"One ampere is equal to:","options":["One volt per second","One joule per coulomb","One coulomb per second","One ohm per second"],"answer":2,"explanation":"1 A = 1 C/s."},{"subject":"physics","q":"How much charge flows when a current of 2 A passes for 5 seconds?","options":["2 C","5 C","7 C","10 C"],"answer":3,"explanation":"Q = It = 2 Ãƒâ€” 5 = 10 C."},{"subject":"physics","q":"Which instrument is used to measure electric current?","options":["Voltmeter","Ammeter","Thermometer","Barometer"],"answer":1,"explanation":"An ammeter is used to measure current."},{"subject":"physics","q":"An ammeter is connected in:","options":["Parallel","Series","Either series or parallel","Not connected to the circuit"],"answer":1,"explanation":"An ammeter is connected in series with the circuit component."},{"subject":"physics","q":"In a series circuit, current is:","options":["Different at every point","Zero","The same at every point","Larger near the battery"],"answer":2,"explanation":"Current remains the same throughout a series circuit."},{"subject":"physics","q":"In a parallel circuit, the total current is:","options":["Equal to one branch current","Zero","The sum of branch currents","Less than all branch currents"],"answer":2,"explanation":"Total current equals the sum of the currents in each branch."},{"subject":"physics","q":"Potential difference (p.d.) is:","options":["The rate of charge flow","Work done per unit charge","Energy produced per second","Resistance per unit current"],"answer":1,"explanation":"Potential difference is the work done in moving one coulomb of charge."},{"subject":"physics","q":"The SI unit of potential difference is:","options":["Ampere","Coulomb","Watt","Volt"],"answer":3,"explanation":"Potential difference is measured in volts (V)."},{"subject":"physics","q":"One volt is equal to:","options":["One joule per coulomb","One coulomb per joule","One ampere per second","One watt per ampere"],"answer":0,"explanation":"1 V = 1 J/C."},{"subject":"physics","q":"Which instrument measures potential difference?","options":["Ammeter","Galvanometer","Voltmeter","Hydrometer"],"answer":2,"explanation":"A voltmeter is used to measure potential difference."},{"subject":"physics","q":"A voltmeter is connected in:","options":["Series","Parallel","Either way","No connection required"],"answer":1,"explanation":"Voltmeters are connected in parallel across a component."},{"subject":"physics","q":"Electromotive force (emf) is:","options":["Resistance in a circuit","Charge per second","Energy supplied per coulomb by a source","Current in a battery"],"answer":2,"explanation":"emf is the energy available per coulomb from a cell."},{"subject":"physics","q":"In a series circuit, the total voltage is:","options":["The average of voltages","The largest voltage only","The sum of all voltages","Zero"],"answer":2,"explanation":"Total voltage equals the sum of the individual voltages."},{"subject":"physics","q":"In a parallel circuit, voltage across the branches is:","options":["Different in each branch","Equal in all branches","Zero in some branches","Always increasing"],"answer":1,"explanation":"The potential difference is the same across all parallel branches."},{"subject":"physics","q":"A current of 0.5 A flows for 3 seconds. How much charge passes?","options":["0.5 C","1.0 C","1.5 C","3.5 C"],"answer":2,"explanation":"Q = It = 0.5 Ãƒâ€” 3 = 1.5 C."},{"subject":"physics","q":"Electrical resistance is:","options":["The flow of electrons","The opposition to the flow of electric current","The production of energy","The movement of charge"],"answer":1,"explanation":"Resistance is the opposition to the flow of electric current in a circuit."},{"subject":"physics","q":"The SI unit of resistance is:","options":["Ampere (A)","Volt (V)","Ohm (ÃŽÂ©)","Coulomb (C)"],"answer":2,"explanation":"Electrical resistance is measured in ohms (ÃŽÂ©)."},{"subject":"physics","q":"The formula for resistance is:","options":["R = I/V","R = V/I","R = VI","R = Q/t"],"answer":1,"explanation":"Resistance is the ratio of potential difference to current."},{"subject":"physics","q":"If the voltage across a resistor is 12 V and the current is 3 A, the resistance is:","options":["4 ÃŽÂ©","9 ÃŽÂ©","15 ÃŽÂ©","36 ÃŽÂ©"],"answer":0,"explanation":"R = V ÃƒÂ· I = 12 ÃƒÂ· 3 = 4 ÃŽÂ©."},{"subject":"physics","q":"Which factor affects the resistance of a conductor?","options":["Length of the conductor","Cross-sectional area","Temperature","All of the above"],"answer":3,"explanation":"Resistance depends on length, area, material, and temperature."},{"subject":"physics","q":"Ohm\u0027s Law states that current is directly proportional to:","options":["Resistance","Potential difference","Temperature","Length"],"answer":1,"explanation":"Current is directly proportional to voltage when temperature remains constant."},{"subject":"physics","q":"Who formulated Ohm\u0027s Law?","options":["Isaac Newton","Michael Faraday","George Simon Ohm","Thomas Edison"],"answer":2,"explanation":"Ohm\u0027s Law was established by George Simon Ohm."},{"subject":"physics","q":"Which equation represents Ohm\u0027s Law?","options":["V = IR","P = IV","W = Fd","Q = It"],"answer":0,"explanation":"Voltage equals current multiplied by resistance."},{"subject":"physics","q":"Materials which obey Ohm\u0027s Law are called:","options":["Conductors","Ohmic conductors","Insulators","Semiconductors"],"answer":1,"explanation":"Ohmic conductors obey Ohm\u0027s Law."},{"subject":"physics","q":"Materials that do not obey Ohm\u0027s Law are called:","options":["Metals","Conductors","Non-ohmic conductors","Resistors"],"answer":2,"explanation":"Non-ohmic conductors do not follow Ohm\u0027s Law."},{"subject":"physics","q":"A resistor whose resistance remains almost constant is called:","options":["Variable resistor","Fixed resistor","Rheostat","Thermistor"],"answer":1,"explanation":"Fixed resistors have nearly constant resistance values."},{"subject":"physics","q":"How many colour bands are normally used on a carbon resistor?","options":["2","3","4","5"],"answer":2,"explanation":"Carbon resistors commonly have four colour bands."},{"subject":"physics","q":"In resistor colour coding, the first two bands represent:","options":["Tolerance only","Digits of resistance value","Number of zeros only","Temperature"],"answer":1,"explanation":"The first and second bands give the first two digits of the resistor value."},{"subject":"physics","q":"A resistor whose resistance can be changed is called:","options":["Fixed resistor","Cell","Variable resistor","Fuse"],"answer":2,"explanation":"Variable resistors allow adjustment of resistance."},{"subject":"physics","q":"Another name for a variable resistor is:","options":["Ammeter","Rheostat","Voltmeter","Capacitor"],"answer":1,"explanation":"A rheostat is a variable resistor."},{"subject":"physics","q":"Internal resistance is found:","options":["Outside the circuit","In connecting wires only","Inside a cell or battery","In resistors only"],"answer":2,"explanation":"Internal resistance arises from materials used inside the cell."},{"subject":"physics","q":"Electromotive force (emf) is used to:","options":["Overcome internal resistance only","Overcome external resistance only","Overcome both internal and external resistance","Produce heat only"],"answer":2,"explanation":"emf provides energy to overcome both internal and external resistances."},{"subject":"physics","q":"The symbol ÃŽÂ© stands for:","options":["Voltage","Current","Resistance","Charge"],"answer":2,"explanation":"ÃŽÂ© (Ohm) is the unit of resistance."},{"subject":"physics","q":"If the current through a conductor doubles while resistance remains constant, the voltage will:","options":["Halve","Remain the same","Double","Become zero"],"answer":2,"explanation":"From V = IR, doubling current doubles voltage if resistance is constant."},{"subject":"physics","q":"According to Ohm\u0027s Law, resistance is:","options":["R = V/I","R = IV","R = I/V","R = Q/t"],"answer":0,"explanation":"Resistance is found by dividing voltage by current"},{"subject":"physics","q":"Electrical energy is:","options":["The rate of doing work","The amount of work done by electricity","Resistance in a circuit","The flow of charge"],"answer":1,"explanation":"Electrical energy is the amount of work done when electric current flows through a circuit."},{"subject":"physics","q":"In a series circuit, the total resistance is:","options":["The product of all resistances","The sum of all resistances","The average resistance","Zero"],"answer":1,"explanation":"For resistors in series, RT=R1+R2+R3R_T = R_1 + R_2 + R_3RTÃ¢â‚¬â€¹=R1Ã¢â‚¬â€¹+R2Ã¢â‚¬â€¹+R3Ã¢â‚¬â€¹."},{"subject":"physics","q":"Three resistors of 2 ÃŽÂ©, 3 ÃŽÂ© and 5 ÃŽÂ© are connected in series. What is the total resistance?","options":["5 ÃŽÂ©","8 ÃŽÂ©","10 ÃŽÂ©","30 ÃŽÂ©"],"answer":2,"explanation":"Total resistance = 2 + 3 + 5 = 10 ÃŽÂ©."},{"subject":"physics","q":"In a parallel circuit:","options":["Resistances are added directly","Current is the same in all branches","The inverse of total resistance equals the sum of inverses","Voltage is zero"],"answer":2,"explanation":"Parallel resistors follow the reciprocal rule."},{"subject":"physics","q":"Which of the following affects the heating effect of electric current?","options":["Current","Resistance","Time","All of the above"],"answer":3,"explanation":"Heating depends on current, resistance, time and potential difference."},{"subject":"physics","q":"Electrical energy is measured in:","options":["Watts","Joules","Amperes","Volts"],"answer":1,"explanation":"Electrical energy is measured in joules (J)."},{"subject":"physics","q":"The equation for electrical energy is:","options":["E = IV","E = VQ","E = IR","E = V/I"],"answer":1,"explanation":"Electrical energy equals potential difference multiplied by charge."},{"subject":"physics","q":"Which equation represents electrical energy in terms of current, resistance and time?","options":["E = IÃ‚Â²Rt","E = IV","E = V/R","E = It"],"answer":0,"explanation":"Electrical energy can be calculated using E = IÃ‚Â²Rt."},{"subject":"physics","q":"Electrical power is:","options":["The amount of energy stored","The rate of converting electrical energy","Resistance to current flow","Charge per second"],"answer":1,"explanation":"Electrical power is the rate at which electrical energy is converted."},{"subject":"physics","q":"The SI unit of power is:","options":["Joule","Watt","Ohm","Coulomb"],"answer":1,"explanation":"Power is measured in watts (W)."},{"subject":"physics","q":"The formula for power is:","options":["P = E/t","P = IVt","P = V/I","P = It"],"answer":0,"explanation":"Power equals energy divided by time."},{"subject":"physics","q":"Another formula for electrical power is:","options":["P = IR","P = IV","P = VQ","P = Rt"],"answer":1,"explanation":"Power can be calculated by multiplying voltage and current."},{"subject":"physics","q":"A bulb rated 2.5 V and 0.3 A has a power of:","options":["0.75 W","1.25 W","2.8 W","7.5 W"],"answer":0,"explanation":"P = IV = 2.5 Ãƒâ€” 0.3 = 0.75 W."},{"subject":"physics","q":"The commercial unit of electrical energy is:","options":["Joule","Watt","Kilowatt-hour","Newton"],"answer":2,"explanation":"Electrical energy used in homes is measured in kilowatt-hours (kWh)."},{"subject":"physics","q":"One kilowatt-hour (kWh) is a unit of:","options":["Power","Current","Energy","Resistance"],"answer":2,"explanation":"kWh is a commercial unit of energy."},{"subject":"physics","q":"In domestic wiring, the switch should be connected to the:","options":["Earth wire","Neutral wire","Live wire","Fuse wire only"],"answer":2,"explanation":"The switch is fitted in the live wire so that the appliance can be safely switched on or off."},{"subject":"physics","q":"What colour is the live wire in modern wiring?","options":["Blue","Green/Yellow","Brown","Black"],"answer":2,"explanation":"Brown is the standard colour for the live wire."},{"subject":"physics","q":"The purpose of a fuse is to:","options":["Increase voltage","Store charge","Prevent dangerously large currents","Measure current"],"answer":2,"explanation":"A fuse melts when current exceeds its rated value, protecting the circuit."},{"subject":"physics","q":"The earth wire is mainly used to:","options":["Increase current flow","Prevent electric shock","Increase power","Reduce voltage"],"answer":1,"explanation":"Earthing prevents the metal case of an appliance from becoming live."},{"subject":"physics","q":"Which of the following is an electrical hazard?","options":["Using a correct fuse","Dry hands when touching appliances","Overloading a socket outlet","Replacing broken plugs"],"answer":2,"explanation":"Overloading outlets can cause overheating and electrical fires."},{"subject":"physics","q":"An oscillation is:","options":["Motion in a straight line only","Repeated to-and-fro motion about a fixed position","Motion around a circle only","Random motion"],"answer":1,"explanation":"Oscillation is a repeated to-and-fro motion about a mean position."},{"subject":"physics","q":"A simple pendulum undergoes:","options":["Translational motion","Circular motion","Oscillatory motion","Random motion"],"answer":2,"explanation":"A simple pendulum swings back and forth in oscillatory motion."},{"subject":"physics","q":"The time taken for one complete oscillation is called:","options":["Frequency","Amplitude","Period","Wavelength"],"answer":2,"explanation":"The period is the time required for one complete oscillation."},{"subject":"physics","q":"The SI unit of period is:","options":["Hertz","Metre","Second","Joule"],"answer":2,"explanation":"Period is measured in seconds (s)."},{"subject":"physics","q":"Frequency is defined as:","options":["Time for one oscillation","Number of oscillations per second","Distance travelled by a wave","Maximum displacement"],"answer":1,"explanation":"Frequency is the number of complete oscillations every second."},{"subject":"physics","q":"The SI unit of frequency is:","options":["Metre","Second","Hertz","Newton"],"answer":2,"explanation":"Frequency is measured in hertz (Hz)."},{"subject":"physics","q":"The maximum displacement from the mean position is called:","options":["Wavelength","Amplitude","Frequency","Velocity"],"answer":1,"explanation":"Amplitude is the greatest distance from the equilibrium position."},{"subject":"physics","q":"Which of the following affects oscillations?","options":["Length of a pendulum","Mass of the bob","Amplitude","Length of string"],"answer":3,"explanation":"The period of a pendulum is affected mainly by the length of the string."},{"subject":"physics","q":"A pulse is:","options":["A continuous wave","A single disturbance travelling through a medium","A sound wave only","An electric current"],"answer":1,"explanation":"A pulse is a single disturbance that moves through a medium."},{"subject":"physics","q":"A wave is:","options":["A series of pulses travelling through a medium","A solid object","A force only","A form of matter"],"answer":0,"explanation":"Waves are produced by repeated pulses moving through a medium."},{"subject":"physics","q":"Waves transfer:","options":["Matter only","Energy only","Matter and energy","Mass only"],"answer":1,"explanation":"Waves transfer energy from one point to another."},{"subject":"physics","q":"The distance between two successive crests is called:","options":["Amplitude","Frequency","Wavelength","Period"],"answer":2,"explanation":"Wavelength is the distance between corresponding points on successive waves."},{"subject":"physics","q":"The symbol commonly used for wavelength is:","options":["f","T","ÃŽÂ»","v"],"answer":2,"explanation":"Wavelength is represented by the Greek letter lambda (ÃŽÂ»)."},{"subject":"physics","q":"The speed of a wave is given by:","options":["v = fÃŽÂ»","v = f/ÃŽÂ»","v = ÃŽÂ»/f","v = Tf"],"answer":0,"explanation":"Wave speed equals frequency multiplied by wavelength."},{"subject":"physics","q":"As frequency increases, the period:","options":["Increases","Decreases","Remains constant","Becomes zero"],"answer":1,"explanation":"Frequency and period are inversely related."},{"subject":"physics","q":"The relationship between frequency and period is:","options":["f = T","f = 1/T","f = TÃ‚Â²","f = 2T"],"answer":1,"explanation":"Frequency is the reciprocal of period."},{"subject":"physics","q":"Which part of a transverse wave is the highest point?","options":["Trough","Node","Crest","Pulse"],"answer":2,"explanation":"The crest is the highest point on a transverse wave."},{"subject":"physics","q":"The lowest point of a transverse wave is called:","options":["Crest","Trough","Amplitude","Wavelength"],"answer":1,"explanation":"The trough is the lowest point on a transverse wave."},{"subject":"physics","q":"If a wave has a frequency of 5 Hz and a wavelength of 2 m, its speed is:","options":["2.5 m/s","7 m/s","10 m/s","15 m/s"],"answer":2,"explanation":"v = fÃŽÂ» = 5 Ãƒâ€” 2 = 10 m/s."},{"subject":"physics","q":"A wave with a period of 0.2 s has a frequency of:","options":["0.2 Hz","2 Hz","5 Hz","10 Hz"],"answer":2,"explanation":"Frequency = 1 ÃƒÂ· 0.2 = 5 Hz"},{"subject":"physics","q":"Sound is produced by:","options":["Light","Heat","Vibrations","Magnets"],"answer":2,"explanation":"Sound is produced when an object vibrates."},{"subject":"physics","q":"Sound travels in the form of:","options":["Longitudinal waves","Transverse waves","Electromagnetic waves","Light waves"],"answer":0,"explanation":"Sound propagates through a medium as longitudinal waves."},{"subject":"physics","q":"Which of the following is necessary for sound to travel?","options":["Vacuum","Medium","Light","Electricity"],"answer":1,"explanation":"Sound requires a material medium such as air, water or solids."},{"subject":"physics","q":"Sound cannot travel through:","options":["Air","Water","Steel","Vacuum"],"answer":3,"explanation":"Sound needs particles to transmit vibrations and cannot travel in a vacuum."},{"subject":"physics","q":"Which part of a sound wave has particles closest together?","options":["Rarefaction","Compression","Crest","Trough"],"answer":1,"explanation":"A compression is a region where particles are crowded together."},{"subject":"physics","q":"Which part of a sound wave has particles furthest apart?","options":["Compression","Reflection","Rarefaction","Vibration"],"answer":2,"explanation":"Rarefactions are regions where particles are spread apart."},{"subject":"physics","q":"The loudness of sound mainly depends on:","options":["Wavelength","Amplitude","Frequency","Velocity"],"answer":1,"explanation":"Greater amplitude produces a louder sound."},{"subject":"physics","q":"Pitch depends on:","options":["Amplitude","Frequency","Speed","Distance"],"answer":1,"explanation":"Higher frequency produces a higher pitch."},{"subject":"physics","q":"A high-pitched sound has:","options":["Low frequency","High frequency","Low amplitude","Long wavelength only"],"answer":1,"explanation":"Pitch increases as frequency increases."},{"subject":"physics","q":"The SI unit of frequency is:","options":["Metre","Decibel","Hertz","Second"],"answer":2,"explanation":"Frequency is measured in hertz (Hz)."},{"subject":"physics","q":"The audible range of sound for a healthy human ear is approximately:","options":["2 Hz Ã¢â‚¬â€œ 200 Hz","20 Hz Ã¢â‚¬â€œ 20,000 Hz","200 Hz Ã¢â‚¬â€œ 2,000 Hz","2,000 Hz Ã¢â‚¬â€œ 200,000 Hz"],"answer":1,"explanation":"Humans typically hear sounds between 20 Hz and 20,000 Hz."},{"subject":"physics","q":"Vibrations that occur naturally without any external force are called:","options":["Forced vibrations","Resonant vibrations","Free vibrations","Random vibrations"],"answer":2,"explanation":"Free vibrations occur when an object vibrates on its own after being disturbed."},{"subject":"physics","q":"Vibrations caused by an external periodic force are called:","options":["Free vibrations","Forced vibrations","Resonance","Wave motion"],"answer":1,"explanation":"Forced vibrations are maintained by an external force."},{"subject":"physics","q":"Resonance occurs when:","options":["Frequency is zero","Two bodies vibrate at different frequencies","The frequency of a driving force equals the natural frequency","Sound stops completely"],"answer":2,"explanation":"Resonance results in large vibrations when matching frequencies occur."},{"subject":"physics","q":"Sound travels fastest in:","options":["Air","Vacuum","Water","Solids"],"answer":3,"explanation":"Particles in solids are closely packed, allowing sound to travel faster."},{"subject":"physics","q":"Sound travels slowest in:","options":["Solids","Liquids","Gases","Metals"],"answer":2,"explanation":"Particles in gases are further apart, so sound travels more slowly."},{"subject":"physics","q":"An echo is caused by:","options":["Refraction of sound","Reflection of sound","Absorption of sound","Dispersion of sound"],"answer":1,"explanation":"Echoes occur when sound waves are reflected from a surface."},{"subject":"physics","q":"Which of the following is an example of sound pollution?","options":["Library silence","Bird songs","Excessive traffic noise","Soft conversation"],"answer":2,"explanation":"Loud unwanted sounds such as traffic noise contribute to sound pollution."},{"subject":"physics","q":"Sound pollution can lead to:","options":["Improved hearing","Hearing problems and stress","Increased light intensity","Faster sound speed"],"answer":1,"explanation":"Prolonged exposure to loud noise may cause hearing loss and stress."},{"subject":"physics","q":"Which device converts sound energy into electrical energy?","options":["Loudspeaker","Generator","Microphone","Battery"],"answer":2,"explanation":"A microphone converts sound vibrations into electrical signals."},{"subject":"physics","q":"What is a wave?","options":["A substance that carries energy","A disturbance that travels through a medium","A force that creates sound","A stationary vibration"],"answer":1,"explanation":"A wave is a disturbance that travels through a medium from one location to another."},{"subject":"physics","q":"What is a pulse?","options":["A continuous vibration","A single disturbance moving through a medium","A reflected wave","An electromagnetic wave"],"answer":1,"explanation":"A pulse is a single disturbance that moves through a medium."},{"subject":"physics","q":"What is meant by a medium?","options":["A source of energy","A material that carries a wave","A vibrating object","A type of wave"],"answer":1,"explanation":"A medium is the substance through which a wave travels."},{"subject":"physics","q":"In a transverse wave, particles vibrate:","options":["Parallel to wave motion","Opposite to wave motion","Perpendicular to wave motion","Circularly"],"answer":2,"explanation":"In transverse waves, particles vibrate at right angles to the direction of energy transfer."},{"subject":"physics","q":"The highest point of a transverse wave is called:","options":["Trough","Crest","Compression","Node"],"answer":1,"explanation":"The crest is the point of maximum upward displacement."},{"subject":"physics","q":"The lowest point of a transverse wave is called:","options":["Crest","Antinode","Compression","Trough"],"answer":3,"explanation":"A trough is the point of maximum downward displacement."},{"subject":"physics","q":"Amplitude is:","options":["Distance between two crests","Number of vibrations per second","Maximum displacement from the rest position","Time for one vibration"],"answer":2,"explanation":"Amplitude is the maximum distance a particle moves from its equilibrium position."},{"subject":"physics","q":"Wavelength is:","options":["Distance travelled in one second","Length of one complete wave cycle","Number of waves per second","Height of a wave"],"answer":1,"explanation":"Wavelength is the distance between corresponding points on successive waves."},{"subject":"physics","q":"Frequency is measured in:","options":["Metres","Seconds","Hertz","Newtons"],"answer":2,"explanation":"Frequency is measured in Hertz (Hz), where 1 Hz equals one cycle per second."},{"subject":"physics","q":"The period of a wave is:","options":["Height of a wave","Time taken for one complete vibration","Number of waves produced","Speed of the wave"],"answer":1,"explanation":"Period is the time required for one complete cycle."},{"subject":"physics","q":"In a longitudinal wave, particles vibrate:","options":["Perpendicular to wave motion","Parallel to wave motion","Up and down only","In circles"],"answer":1,"explanation":"Longitudinal waves involve vibrations parallel to the direction of energy transfer."},{"subject":"physics","q":"A region of maximum density in a longitudinal wave is called:","options":["Trough","Rarefaction","Compression","Crest"],"answer":2,"explanation":"Compression is the region where particles are closest together."},{"subject":"physics","q":"A rarefaction is a region of:","options":["Maximum density","Minimum density","Maximum amplitude","Maximum speed"],"answer":1,"explanation":"Rarefaction occurs where particles are spread apart."},{"subject":"physics","q":"The SI unit of wave speed is:","options":["Hz","N","m/s","kg"],"answer":2,"explanation":"Wave speed is measured in metres per second (m/s)."},{"subject":"physics","q":"The wave equation is:","options":["v = f/ÃŽÂ»","v = fÃŽÂ»","ÃŽÂ» = fvÃ‚Â²","f = ÃŽÂ»vÃ‚Â²"],"answer":1,"explanation":"Wave speed equals frequency multiplied by wavelength."},{"subject":"physics","q":"Which type of wave requires a medium for transmission?","options":["Electromagnetic wave","Radio wave","Mechanical wave","Light wave"],"answer":2,"explanation":"Mechanical waves need a material medium to travel through."},{"subject":"physics","q":"Which of the following is an electromagnetic wave?","options":["Sound wave","Water wave","Seismic wave","Light wave"],"answer":3,"explanation":"Light is an electromagnetic wave and can travel through a vacuum."},{"subject":"physics","q":"Which wave can travel through a vacuum?","options":["Water wave","Sound wave","Electromagnetic wave","Seismic wave"],"answer":2,"explanation":"Electromagnetic waves do not need a medium."},{"subject":"physics","q":"Examples of mechanical waves include:","options":["Radio and X-rays","Light and gamma rays","Sound and water waves","Infrared and ultraviolet rays"],"answer":2,"explanation":"Sound and water waves require a medium and are mechanical waves."},{"subject":"physics","q":"If a wave has a frequency of 5 Hz and a wavelength of 2 m, its speed is:","options":["2.5 m/s","7 m/s","10 m/s","20 m/s"],"answer":2,"explanation":"Using v = fÃŽÂ», v = 5 Ãƒâ€” 2 = 10 m/s."},{"subject":"physics","q":"Which of the following is the change in direction of a wave that causes it to return into the same medium?","options":["Refraction","Diffraction","Reflection","Interference"],"answer":2,"explanation":"Reflection occurs when a wave bounces back into the medium from which it originated."},{"subject":"physics","q":"The law of reflection states that:","options":["Angle of incidence is greater than angle of reflection","Angle of incidence equals angle of reflection","Reflected angle is always 90Ã‚Â°","Waves stop at the boundary"],"answer":1,"explanation":"The angle of incidence is equal to the angle of reflection."},{"subject":"physics","q":"During reflection, the wavelength of the reflected wave is:","options":["Greater than the incident wave","Smaller than the incident wave","The same as the incident wave","Zero"],"answer":2,"explanation":"Reflection does not change the wavelength of the wave."},{"subject":"physics","q":"Which characteristic remains unchanged during reflection?","options":["Frequency","Wavelength","Speed","All of the above"],"answer":3,"explanation":"Frequency, wavelength, and speed remain unchanged during reflection."},{"subject":"physics","q":"Reflection from a smooth surface is called:","options":["Diffuse reflection","Specular reflection","Refraction","Interference"],"answer":1,"explanation":"Specular reflection occurs on smooth surfaces."},{"subject":"physics","q":"A ripple tank is used to demonstrate:","options":["Atomic structure","Electric circuits","Wave properties","Radioactivity"],"answer":2,"explanation":"A ripple tank is used to demonstrate reflection, refraction, diffraction and interference."},{"subject":"physics","q":"Refraction is:","options":["Bending of waves due to a change of medium","Mixing of waves","Reflection of sound","Absorption of waves"],"answer":0,"explanation":"Refraction occurs when a wave changes direction as it enters a different medium."},{"subject":"physics","q":"During refraction, the frequency of a wave:","options":["Increases","Decreases","Remains constant","Becomes zero"],"answer":2,"explanation":"Refraction changes wave speed but not frequency."},{"subject":"physics","q":"The refractive index describes:","options":["The loudness of sound","The speed of light in a medium","Wave amplitude","Wave interference"],"answer":1,"explanation":"Refractive index indicates how light travels through a medium."},{"subject":"physics","q":"Which phenomenon occurs when two waves combine?","options":["Reflection","Refraction","Interference","Diffraction"],"answer":2,"explanation":"Interference is the superposition of two or more waves."},{"subject":"physics","q":"Constructive interference occurs when:","options":["Waves cancel each other","Waves have opposite displacements","Waves have displacements in the same direction","Waves stop moving"],"answer":2,"explanation":"Constructive interference increases amplitude because the waves reinforce each other."},{"subject":"physics","q":"Destructive interference occurs when:","options":["Waves move together","Waves have opposite displacements","Amplitudes increase","Frequency doubles"],"answer":1,"explanation":"Opposite displacements reduce or cancel the resultant amplitude."},{"subject":"physics","q":"What is diffraction?","options":["Reflection of waves","Combination of waves","Change in direction of waves through an opening or around an obstacle","Absorption of waves"],"answer":2,"explanation":"Diffraction occurs when waves bend around barriers or spread through openings."},{"subject":"physics","q":"Diffraction is most noticeable when:","options":["The obstacle is much larger than the wavelength","The obstacle is comparable to the wavelength","There is no obstacle","Frequency is zero"],"answer":1,"explanation":"Diffraction effects are greatest when obstacle size is similar to the wavelength."},{"subject":"physics","q":"Sound heard around a corner is an example of:","options":["Reflection","Refraction","Constructive interference","Diffraction"],"answer":3,"explanation":"Sound waves bend around corners due to diffraction."},{"subject":"physics","q":"SONAR works mainly by:","options":["Refraction","Reflection of sound waves","Diffraction","Polarisation"],"answer":1,"explanation":"SONAR uses echoes produced by reflected sound waves."},{"subject":"physics","q":"Which application uses destructive interference?","options":["Noise-cancelling headphones","Mirrors","Magnifying lenses","Radio broadcasting"],"answer":0,"explanation":"Noise-cancelling devices produce opposing sound waves to reduce noise."},{"subject":"physics","q":"Formation of a spectrum using a prism is an application of:","options":["Reflection","Diffraction","Refraction","Interference"],"answer":2,"explanation":"A prism splits light into colours through refraction."},{"subject":"physics","q":"Holograms are produced using:","options":["Reflection only","Refraction only","Interference of waves","Conduction"],"answer":2,"explanation":"Interference patterns are used to create holograms."},{"subject":"physics","q":"X-ray diffraction is used to:","options":["Measure temperature","Determine crystal structures","Produce sound","Increase wave speed"],"answer":1,"explanation":"X-ray diffraction helps scientists determine the structure of crystals and materials"},{"subject":"physics","q":"Mechanical waves are waves that:","options":["Travel only in a vacuum","Require a medium for transmission","Are formed by light only","Travel without energy"],"answer":1,"explanation":"Mechanical waves need a material medium such as air, water, or solids to travel."},{"subject":"physics","q":"Which of the following is a mechanical wave?","options":["Radio wave","X-ray","Sound wave","Gamma ray"],"answer":2,"explanation":"Sound waves require a medium and are therefore mechanical waves."},{"subject":"physics","q":"Electromagnetic waves:","options":["Require a medium","Require water only","Cannot travel in space","Do not require a medium"],"answer":3,"explanation":"Electromagnetic waves can travel through a vacuum."},{"subject":"physics","q":"Which of the following is an electromagnetic wave?","options":["Water wave","Sound wave","Light wave","Seismic wave"],"answer":2,"explanation":"Light is an electromagnetic wave and does not require a medium."},{"subject":"physics","q":"A transverse wave is one in which particles vibrate:","options":["Parallel to wave movement","Perpendicular to wave movement","Randomly","In circles only"],"answer":1,"explanation":"In transverse waves, particle vibration is at right angles to the direction of wave movement."},{"subject":"physics","q":"A longitudinal wave is one in which particles vibrate:","options":["Perpendicular to the wave direction","At 45Ã‚Â° to the wave direction","Parallel to the wave direction","In a circular path"],"answer":2,"explanation":"Longitudinal waves involve vibrations in the same direction as wave travel."},{"subject":"physics","q":"Which instrument can be used to demonstrate transverse waves?","options":["Thermometer","Slinky spring shaken up and down","Voltmeter","Barometer"],"answer":1,"explanation":"Moving a slinky up and down creates a transverse wave."},{"subject":"physics","q":"Sound waves are examples of:","options":["Electromagnetic waves","Surface waves","Longitudinal waves","Radio waves"],"answer":2,"explanation":"Sound travels through compressions and rarefactions, making it longitudinal."},{"subject":"physics","q":"In a longitudinal wave, regions of high particle density are called:","options":["Nodes","Rarefactions","Troughs","Compressions"],"answer":3,"explanation":"Compressions are crowded regions in a longitudinal wave."},{"subject":"physics","q":"Regions of low particle density in a longitudinal wave are called:","options":["Crests","Rarefactions","Compressions","Antinodes"],"answer":1,"explanation":"Rarefactions are areas where particles are spread apart."},{"subject":"physics","q":"Surface waves travel:","options":["Through a vacuum","Along the boundary between two media","Only in air","Only underground"],"answer":1,"explanation":"Surface waves move along the interface between two materials."},{"subject":"physics","q":"Ocean waves are examples of:","options":["Surface waves","Electromagnetic waves","Radio waves","X-rays"],"answer":0,"explanation":"Ocean waves exhibit both transverse and longitudinal characteristics."},{"subject":"physics","q":"During an earthquake, the first waves produced are:","options":["Surface waves","Secondary waves","Primary waves","Radio waves"],"answer":2,"explanation":"Primary waves (P-waves) arrive before all other earthquake waves."},{"subject":"physics","q":"Electromagnetic waves are:","options":["Longitudinal only","Surface only","Transverse only","Mechanical only"],"answer":2,"explanation":"Electromagnetic waves are transverse in nature."},{"subject":"physics","q":"The speed of electromagnetic waves in a vacuum is:","options":["3 Ãƒâ€” 10Ã¢ÂÂ´ m/s","3 Ãƒâ€” 10Ã¢ÂÂ¶ m/s","3 Ãƒâ€” 10Ã¢ÂÂ¸ m/s","3 Ãƒâ€” 10Ã‚Â¹Ã¢ÂÂ° m/s"],"answer":2,"explanation":"Electromagnetic waves travel at the speed of light, 3 Ãƒâ€” 10Ã¢ÂÂ¸ m/s."},{"subject":"physics","q":"Frequency and wavelength are related by:","options":["They are directly proportional","They are inversely proportional","They are equal","They are unrelated"],"answer":1,"explanation":"As frequency increases, wavelength decreases when wave speed remains constant."},{"subject":"physics","q":"The wave equation is:","options":["f = ÃŽÂ»/v","ÃŽÂ» = vf","v = fÃŽÂ»","v = ÃŽÂ»/fÃ‚Â²"],"answer":2,"explanation":"Wave speed equals frequency multiplied by wavelength."},{"subject":"physics","q":"If a wave has frequency 20 Hz and wavelength 5 m, its speed is:","options":["4 m/s","25 m/s","100 m/s","400 m/s"],"answer":2,"explanation":"v = fÃŽÂ» = 20 Ãƒâ€” 5 = 100 m/s."},{"subject":"physics","q":"Which statement is true about mechanical waves?","options":["They travel through a vacuum","They require no medium","They require a medium to propagate","They move at the speed of light"],"answer":2,"explanation":"Mechanical waves need a material substance for transmission."},{"subject":"physics","q":"Examples of electromagnetic waves include:","options":["Sound and water waves","Light and radio waves","Seismic and ocean waves","Water and sound waves"],"answer":1,"explanation":"Light and radio waves are e1. Sound is produced by:"},{"subject":"physics","q":"Answer: BExplanation: Light and radio waves are e1. Sound is produced by:","options":["Light waves","Vibrating objects","Magnetic fields","Electric charges"],"answer":1,"explanation":"Sound is produced when objects vibrate and create disturbances in a medium."},{"subject":"physics","q":"Which of the following is a source of sound?","options":["Vibrating solids","Vacuum","Empty space","Shadow"],"answer":0,"explanation":"Vibrating solids are one of the major sources of sound waves."},{"subject":"physics","q":"Sound waves require:","options":["A vacuum","A medium","Sunlight","Electricity"],"answer":1,"explanation":"Sound is a mechanical wave and requires a material medium for transmission."},{"subject":"physics","q":"The normal human hearing range is:","options":["2 Hz Ã¢â‚¬â€œ 200 Hz","20 Hz Ã¢â‚¬â€œ 20,000 Hz","200 Hz Ã¢â‚¬â€œ 200,000 Hz","1 Hz Ã¢â‚¬â€œ 10 Hz"],"answer":1,"explanation":"Humans can normally hear sounds between 20 Hz and 20,000 Hz."},{"subject":"physics","q":"The range of frequencies that can be heard by humans is called:","options":["Resonance range","Audible range","Wave range","Pitch range"],"answer":1,"explanation":"Audibility range refers to frequencies that can be heard by humans."},{"subject":"physics","q":"Which animals can hear frequencies up to 100 kHz?","options":["Dogs and cats","Cows and goats","Dolphins and bats","Horses and sheep"],"answer":2,"explanation":"Dolphins and bats can hear frequencies much higher than humans."},{"subject":"physics","q":"The organ responsible for hearing is the:","options":["Eye","Tongue","Ear","Nose"],"answer":2,"explanation":"The ear detects sound and helps maintain balance."},{"subject":"physics","q":"The visible external part of the ear is called the:","options":["Cochlea","Pinna (Auricle)","Tympanum","Labyrinth"],"answer":1,"explanation":"The pinna collects sound waves and directs them into the ear canal."},{"subject":"physics","q":"The eardrum is also known as the:","options":["Cochlea","Vestibule","Tympanic membrane","Organ of Corti"],"answer":2,"explanation":"The tympanic membrane separates the outer ear from the middle ear."},{"subject":"physics","q":"The middle ear is also called the:","options":["Labyrinth","Tympanum","Cochlea","Pinna"],"answer":1,"explanation":"The middle ear is commonly known as the tympanum."},{"subject":"physics","q":"Which part of the ear converts sound vibrations into electrical impulses?","options":["Pinna","Ear canal","Cochlea","Eardrum"],"answer":2,"explanation":"The cochlea contains hair cells that convert sound into electrical signals."},{"subject":"physics","q":"The inner ear is also known as the:","options":["Auricle","Tympanum","Labyrinth","Canal"],"answer":2,"explanation":"The inner ear is called the labyrinth."},{"subject":"physics","q":"Hearing impulses are carried to the brain through the:","options":["Optic nerve","Auditory nerve","Spinal cord","Motor nerve"],"answer":1,"explanation":"The auditory (hearing) nerve transmits sound information to the brain."},{"subject":"physics","q":"Which structure in the cochlea contains hair cells?","options":["Organ of Corti","Pinna","Eardrum","Ear canal"],"answer":0,"explanation":"The Organ of Corti contains specialized hair cells for hearing."},{"subject":"physics","q":"Sound reaches the brain after being converted into:","options":["Light waves","Magnetic waves","Electrical impulses","Heat energy"],"answer":2,"explanation":"The cochlea converts sound vibrations into electrical impulses sent to the brain."},{"subject":"physics","q":"An audiogram measures:","options":["Eye defects","Hearing thresholds","Blood pressure","Heartbeat rate"],"answer":1,"explanation":"An audiogram shows the minimum sound level detectable at different frequencies."},{"subject":"physics","q":"The hearing range generally decreases with:","options":["Exercise","Height","Age","Weight"],"answer":2,"explanation":"Sensitivity to high frequencies usually decreases as people get older."},{"subject":"physics","q":"Which part of the ear helps maintain body balance?","options":["Pinna","Outer ear","Inner ear","Eardrum"],"answer":2,"explanation":"The inner ear plays an important role in balance and body position."},{"subject":"physics","q":"Sound waves are examples of:","options":["Electromagnetic waves","Mechanical waves","Radio waves","Light waves"],"answer":1,"explanation":"Sound waves require a medium and are mechanical waves."},{"subject":"physics","q":"The cochlea is found in the:","options":["Outer ear","Middle ear","Inner ear","Ear canal"],"answer":2,"explanation":"The cochlea is located in the inner ear and is responsible for hearing"},{"subject":"physics","q":"An echo is produced when:","options":["Sound is absorbed","Sound is reflected","Sound is refracted","Sound is diffracted"],"answer":1,"explanation":"An echo is produced when a sound wave is reflected back to the listener after a time delay."},{"subject":"physics","q":"Echo is caused by:","options":["Absorption of sound waves","Reflection of sound waves from obstacles","Refraction of light","Diffraction of sound"],"answer":1,"explanation":"Sound waves strike an obstacle and reflect back, producing an echo."},{"subject":"physics","q":"Which of the following is an application of echo?","options":["Measuring distance","Photosynthesis","Nuclear fission","Magnetism"],"answer":0,"explanation":"Echoes can be used to calculate distances by measuring the time taken for the reflected sound to return."},{"subject":"physics","q":"SONAR stands for:","options":["Sound Navigation and Ranging","Signal Navigation and Radar","Sound Navigation and Radio","Signal Navigation and Reflection"],"answer":0,"explanation":"SONAR means Sound Navigation and Ranging and uses echoes to locate underwater objects."},{"subject":"physics","q":"SONAR is mainly used:","options":["In space travel","Underwater detection and depth measurement","Measuring temperature","Measuring pressure"],"answer":1,"explanation":"SONAR detects underwater objects and measures water depth using reflected sound waves."},{"subject":"physics","q":"Which type of sound is normally used in SONAR?","options":["Audible sound","Ultrasound","Infrasound","Noise"],"answer":1,"explanation":"Ultrasound is used because it has high energy and travels effectively through water."},{"subject":"physics","q":"Bats locate insects by using:","options":["Reflection of light","Photosynthesis","Echoes","Refraction"],"answer":2,"explanation":"Bats emit sounds and use returning echoes to locate prey."},{"subject":"physics","q":"Reverberation is:","options":["Direct sound from the source","Collection of reflected sounds in an enclosure","Absorption of sound","Refraction of sound"],"answer":1,"explanation":"Reverberation is the persistence of sound due to multiple reflections in a room or hall."},{"subject":"physics","q":"Reverberation occurs when the reflected sound reaches the observer in:","options":["More than 1 second","Less than 0.1 second","5 seconds","10 seconds"],"answer":1,"explanation":"In reverberation, reflected sound arrives in less than 0.1 s and blends with the original sound."},{"subject":"physics","q":"Which statement correctly distinguishes echo from reverberation?","options":["Echo involves short distances only","Reverberation involves long distances only","Echo occurs over longer distances, reverberation over shorter distances","They are exactly the same"],"answer":2,"explanation":"Echoes involve larger distances and noticeable delays, whereas reverberation occurs over short distances."},{"subject":"physics","q":"Excessive reverberation in an auditorium causes:","options":["Better sound quality","Muddy and unclear sound","Increased pitch","Increased frequency"],"answer":1,"explanation":"Too much reverberation makes sounds overlap and lose clarity."},{"subject":"physics","q":"The Doppler Effect refers to:","options":["Reflection of sound","Change in frequency due to relative motion","Refraction of sound","Absorption of waves"],"answer":1,"explanation":"The Doppler Effect is the change in observed frequency caused by motion between source and observer."},{"subject":"physics","q":"When an object moves towards an observer, the observed pitch:","options":["Becomes lower","Remains unchanged","Becomes higher","Disappears"],"answer":2,"explanation":"Approaching objects produce a higher observed frequency and pitch."},{"subject":"physics","q":"The change in sound of a passing ambulance siren demonstrates:","options":["Interference","Diffraction","Doppler Effect","Refraction"],"answer":2,"explanation":"The pitch changes because of the relative motion between the ambulance and the observer."},{"subject":"physics","q":"Sound can travel through:","options":["Solids only","Liquids only","Gases only","Solids, liquids and gases"],"answer":3,"explanation":"Sound requires a medium and can travel through solids, liquids and gases."},{"subject":"physics","q":"Sound cannot travel through:","options":["Water","Steel","Air","Vacuum"],"answer":3,"explanation":"Sound is a mechanical wave and needs a medium to travel."},{"subject":"physics","q":"The approximate speed of sound in air is:","options":["34 m/s","340 m/s","3400 m/s","3 Ãƒâ€” 10Ã¢ÂÂ¸ m/s"],"answer":1,"explanation":"The speed of sound in air is approximately 340 m/s."},{"subject":"physics","q":"As temperature increases, the speed of sound in air:","options":["Decreases","Remains constant","Increases","Becomes zero"],"answer":2,"explanation":"Higher temperatures increase the speed of sound in air."},{"subject":"physics","q":"Sound travels fastest in:","options":["Air","Vacuum","Liquids","Solids"],"answer":3,"explanation":"Sound travels faster in solids than in liquids and gases."},{"subject":"physics","q":"If a sound echo returns after 2 seconds and the speed of sound is 340 m/s, the total distance travelled by the sound is:","options":["170 m","340 m","680 m","1360 m"],"answer":2,"explanation":"Distance = Speed Ãƒâ€” Time = 340 Ãƒâ€” 2 = 680 m. The sound travels to the obstacle and back"},{"subject":"physics","q":"Music can be defined as:","options":["Random sound","Organised sound with a pattern","Noise only","Echoes of sound"],"answer":1,"explanation":"Music is organised sound that follows a pattern and is generally pleasant to the human ear."},{"subject":"physics","q":"Noise is:","options":["Organised sound","Sound with fixed frequencies","Random sound without structure","Musical notes"],"answer":2,"explanation":"Noise is random and lacks the organised structure found in music."},{"subject":"physics","q":"Loudness of a sound mainly depends on:","options":["Frequency","Amplitude","Wavelength","Speed"],"answer":1,"explanation":"The greater the amplitude of a sound wave, the louder the sound."},{"subject":"physics","q":"Pitch of a musical note depends on:","options":["Amplitude","Intensity","Frequency","Colour"],"answer":2,"explanation":"Higher frequencies produce higher pitches, while lower frequencies produce lower pitches."},{"subject":"physics","q":"Timbre refers to:","options":["Loudness of sound","Speed of sound","Quality or colour of sound","Frequency of sound"],"answer":2,"explanation":"Timbre is the characteristic quality that makes one musical instrument sound different from another."},{"subject":"physics","q":"Which property makes a guitar sound different from a flute playing the same note?","options":["Frequency","Timbre","Wavelength","Speed"],"answer":1,"explanation":"Timbre distinguishes sounds even when pitch and loudness are the same."},{"subject":"physics","q":"Which of the following is a wind instrument?","options":["Guitar","Violin","Flute","Drum"],"answer":2,"explanation":"Wind instruments produce sound through vibrating air columns."},{"subject":"physics","q":"The pitch produced by a wind instrument depends mainly on:","options":["Colour of the instrument","Length of air column","Mass of the instrument","Shape only"],"answer":1,"explanation":"Longer air columns produce lower pitches, while shorter ones produce higher pitches."},{"subject":"physics","q":"Which of the following is a percussion instrument?","options":["Clarinet","Harp","Drum","Violin"],"answer":2,"explanation":"Percussion instruments produce sound when struck."},{"subject":"physics","q":"A xylophone is classified as a:","options":["Wind instrument","Percussion instrument","String instrument","Electronic instrument"],"answer":1,"explanation":"A xylophone produces sound when its bars are struck."},{"subject":"physics","q":"Which of the following is a string instrument?","options":["Flute","Trumpet","Guitar","Drum"],"answer":2,"explanation":"String instruments produce sound through vibrating strings."},{"subject":"physics","q":"The pitch of a string instrument depends on:","options":["Length and thickness of the string","Colour of the string","Shape of the room","Temperature only"],"answer":0,"explanation":"Length, thickness and tension of strings affect pitch."},{"subject":"physics","q":"A stationary wave is:","options":["A wave that continuously travels","A wave with constant amplitude at each point","A wave in vacuum","An electromagnetic wave"],"answer":1,"explanation":"A stationary wave has points with fixed amplitudes caused by interference of opposite waves."},{"subject":"physics","q":"Nodes are points where:","options":["Amplitude is maximum","Frequency is maximum","Amplitude is minimum","Speed is maximum"],"answer":2,"explanation":"Nodes are points in a stationary wave with minimum or zero amplitude."},{"subject":"physics","q":"Antinodes are points where:","options":["Amplitude is maximum","Amplitude is minimum","Frequency is zero","Speed is zero"],"answer":0,"explanation":"Antinodes are points of maximum vibration in a stationary wave."},{"subject":"physics","q":"The frequency of a musical note depends on:","options":["Length of vibrating string","Tension in the string","Mass per unit length of the string","All of the above"],"answer":3,"explanation":"Frequency depends on string length, tension and linear mass density."},{"subject":"physics","q":"The fundamental note is:","options":["The highest frequency produced","The lowest resonant frequency","The second harmonic","Any overtone"],"answer":1,"explanation":"The fundamental note is the lowest natural frequency of a vibrating object."},{"subject":"physics","q":"An overtone is:","options":["A frequency lower than the fundamental","The fundamental frequency itself","Any frequency higher than the fundamental","A reflected sound"],"answer":2,"explanation":"Overtones are frequencies greater than the fundamental frequency."},{"subject":"physics","q":"The first overtone corresponds to:","options":["First harmonic","Second harmonic","Third harmonic","Fourth harmonic"],"answer":1,"explanation":"The first overtone is the second harmonic."},{"subject":"physics","q":"Resonance occurs when:","options":["Sound disappears completely","A system vibrates with greater amplitude at a particular frequency","Frequency becomes zero","Waves stop moving"],"answer":1,"explanation":"Resonance occurs when a vibrating system is driven at its natural frequency, producing large amplitudes."},{"subject":"physics","q":"The electromagnetic spectrum is:","options":["A range of sound frequencies","A range of all possible electromagnetic frequencies","A range of water waves","A range of mechanical waves"],"answer":1,"explanation":"The electromagnetic spectrum consists of all possible frequencies of electromagnetic radiation."},{"subject":"physics","q":"Electromagnetic waves can travel:","options":["Only in air","Only in water","Only in solids","Through a vacuum"],"answer":3,"explanation":"Electromagnetic waves do not require a medium and can travel through a vacuum."},{"subject":"physics","q":"Which electromagnetic wave has the longest wavelength?","options":["Gamma rays","X-rays","Visible light","Radio waves"],"answer":3,"explanation":"Radio waves have the longest wavelengths in the electromagnetic spectrum."},{"subject":"physics","q":"Radio waves are mainly used for:","options":["Cooking food only","Broadcasting and communication","Medical imaging only","Photography"],"answer":1,"explanation":"Radio waves are used in communication, broadcasting, radar and satellite systems."},{"subject":"physics","q":"Radio waves are generated by:","options":["Nuclear reactors","Radio transmitters","Thermometers","Magnets only"],"answer":1,"explanation":"Radio transmitters generate radio waves and receivers detect them."},{"subject":"physics","q":"Microwaves are commonly used in:","options":["Cooking food","Measuring mass","Producing sound","Generating electricity"],"answer":0,"explanation":"Microwaves are widely used in microwave ovens."},{"subject":"physics","q":"Another important application of microwaves is:","options":["Radar systems","Plant growth","Echo formation","Hearing tests"],"answer":0,"explanation":"Microwaves are used in radar and long-distance communication systems."},{"subject":"physics","q":"Infrared radiation is mainly associated with:","options":["Cooling effect","Heating effect","Magnetism","Radioactivity"],"answer":1,"explanation":"Infrared radiation is commonly experienced as heat."},{"subject":"physics","q":"Infrared radiation is emitted by:","options":["Cold objects only","Hot bodies","Magnets only","Batteries only"],"answer":1,"explanation":"All hot bodies emit infrared radiation."},{"subject":"physics","q":"Visible light is:","options":["The part of the spectrum detected by human eyes","Long radio waves","Sound energy","Mechanical radiation"],"answer":0,"explanation":"Visible light is the narrow range of electromagnetic frequencies visible to humans."},{"subject":"physics","q":"Ultraviolet radiation can be detected using:","options":["Microphones","Thermometers","Photographic films","Loudspeakers"],"answer":2,"explanation":"Photographic films and fluorescent materials can detect ultraviolet radiation."},{"subject":"physics","q":"Infrared radiation can be detected by:","options":["Black bulb thermometers","Compass needles","Spring balances","Hydrometers"],"answer":0,"explanation":"Black bulb thermometers are among the devices used to detect infrared radiation."},{"subject":"physics","q":"Which electromagnetic radiation is commonly used for medical imaging?","options":["Radio waves","Microwaves","X-rays","Infrared"],"answer":2,"explanation":"X-rays are widely used in medicine to examine bones and internal structures."},{"subject":"physics","q":"Gamma rays are used in:","options":["Agriculture and medicine","Sound production","Transport systems","Water waves"],"answer":0,"explanation":"Gamma rays are used in agriculture and in medical treatment."},{"subject":"physics","q":"Which electromagnetic wave is used in radar systems?","options":["Microwaves","Gamma rays","Visible light","Infrared"],"answer":0,"explanation":"Radar systems operate using microwaves."},{"subject":"physics","q":"The electromagnetic spectrum is:","options":["Discontinuous","Continuous","Fixed at one wavelength","Made of sound waves"],"answer":1,"explanation":"The electromagnetic spectrum is continuous with no gaps between different regions."},{"subject":"physics","q":"Which electromagnetic radiation supports photosynthesis?","options":["Visible light","Ultrasound","Seismic waves","Sound waves"],"answer":0,"explanation":"Visible light provides the energy needed for photosynthesis."},{"subject":"physics","q":"Ultraviolet radiation can be used to:","options":["Purify water and air","Generate sound waves","Measure mass","Produce echoes"],"answer":0,"explanation":"Ultraviolet radiation helps destroy microorganisms in water and air."},{"subject":"physics","q":"Astronomers use radio telescopes to:","options":["Hear sounds from planets","Study radio waves from stars and galaxies","Measure rainfall","Detect earthquakes"],"answer":1,"explanation":"Radio telescopes collect radio waves emitted by celestial bodies."},{"subject":"physics","q":"Which arrangement shows increasing frequency?","options":["Gamma rays Ã¢â€ â€™ X-rays Ã¢â€ â€™ Radio waves","Radio waves Ã¢â€ â€™ Microwaves Ã¢â€ â€™ Visible light","X-rays Ã¢â€ â€™ Microwaves Ã¢â€ â€™ Radio waves","Visible light Ã¢â€ â€™ Infrared Ã¢â€ â€™ Radio waves"],"answer":1,"explanation":"Frequency increases from radio waves to microwaves and then to visible light."},{"subject":"physics","q":"Electromagnetism is the interaction between:","options":["Heat and sound","Electric current and magnetic field","Light and heat","Gravity and motion"],"answer":1,"explanation":"Electromagnetism is the effect produced by the interaction of electric current and magnetic fields."},{"subject":"physics","q":"When current flows through a conductor, it produces:","options":["Sound waves","Light only","A magnetic field","Gravity"],"answer":2,"explanation":"An electric current generates a magnetic field around the conductor."},{"subject":"physics","q":"The magnetic field around a straight current-carrying conductor has:","options":["Square patterns","Circular field lines","Triangular field lines","No pattern"],"answer":1,"explanation":"The magnetic field lines form concentric circles around the conductor."},{"subject":"physics","q":"A dot (Ã¢â‚¬Â¢) in a conductor diagram indicates current:","options":["Going into the page","Coming out of the page","Moving left","Moving right"],"answer":1,"explanation":"A dot represents current coming out of the plane of the page."},{"subject":"physics","q":"A cross (Ãƒâ€”) in a conductor diagram indicates current:","options":["Coming out of the page","Moving upward","Going into the page","Moving downward"],"answer":2,"explanation":"A cross represents current moving into the plane of the page."},{"subject":"physics","q":"Increasing the current in a conductor will:","options":["Weaken the magnetic field","Have no effect","Strengthen the magnetic field","Stop the magnetic field"],"answer":2,"explanation":"The strength of the magnetic field increases with electric current."},{"subject":"physics","q":"The magnetic field strength decreases when:","options":["Current increases","Distance from conductor increases","The conductor is thicker","Voltage increases"],"answer":1,"explanation":"Magnetic field strength reduces as you move farther from the conductor."},{"subject":"physics","q":"Which rule is commonly used to determine the direction of magnetic field lines around a conductor?","options":["FlemingÃ¢â‚¬â„¢s Left-Hand Rule","NewtonÃ¢â‚¬â„¢s Rule","Right-Hand Grip Rule","LenzÃ¢â‚¬â„¢s Rule"],"answer":2,"explanation":"The Right-Hand Grip Rule determines magnetic field direction around a conductor."},{"subject":"physics","q":"In the Right-Hand Grip Rule, the thumb points in the direction of:","options":["Magnetic field","Force","Conventional current","Velocity"],"answer":2,"explanation":"The thumb points in the direction of conventional current flow."},{"subject":"physics","q":"In the Right-Hand Grip Rule, the curled fingers indicate:","options":["Current direction","Field direction","Force direction","Voltage direction"],"answer":1,"explanation":"The curled fingers show the direction of magnetic field lines."},{"subject":"physics","q":"A solenoid is:","options":["A straight wire","A permanent magnet","A long coil of wire","A battery"],"answer":2,"explanation":"A solenoid is a long coil containing many closely wound turns of wire."},{"subject":"physics","q":"For a solenoid, the thumb in the Right-Hand Grip Rule points toward:","options":["South pole","Electric field","North pole","Current source"],"answer":2,"explanation":"The thumb points toward the magnetic north pole of the solenoid."},{"subject":"physics","q":"MaxwellÃ¢â‚¬â„¢s Cork Screw Rule states that:","options":["Rotation indicates magnetic field direction","Rotation indicates voltage","Rotation indicates resistance","Rotation indicates gravity"],"answer":0,"explanation":"The direction of screw rotation represents the magnetic field direction."},{"subject":"physics","q":"The direction of force on a current-carrying conductor in a magnetic field is determined by:","options":["Right-Hand Grip Rule","FlemingÃ¢â‚¬â„¢s Left-Hand Rule","FaradayÃ¢â‚¬â„¢s Law","OhmÃ¢â‚¬â„¢s Law"],"answer":1,"explanation":"FlemingÃ¢â‚¬â„¢s Left-Hand Rule is used to determine the direction of force."},{"subject":"physics","q":"In FlemingÃ¢â‚¬â„¢s Left-Hand Rule, the first finger represents:","options":["Current","Force","Magnetic field","Voltage"],"answer":2,"explanation":"The first finger points in the direction of the magnetic field."},{"subject":"physics","q":"In FlemingÃ¢â‚¬â„¢s Left-Hand Rule, the middle finger represents:","options":["Current","Force","Magnetic field","Resistance"],"answer":0,"explanation":"The middle finger points in the direction of the current."},{"subject":"physics","q":"In FlemingÃ¢â‚¬â„¢s Left-Hand Rule, the thumb represents:","options":["Resistance","Voltage","Force or motion","Current"],"answer":2,"explanation":"The thumb indicates the direction of the force acting on the conductor."},{"subject":"physics","q":"Two parallel conductors carrying currents in the same direction will:","options":["Repel each other","Attract each other","Remain stationary","Produce no field"],"answer":1,"explanation":"Currents flowing in the same direction cause attraction between conductors."},{"subject":"physics","q":"Two parallel conductors carrying currents in opposite directions will:","options":["Attract each other","Produce no interaction","Repel each other","Stop current flow"],"answer":2,"explanation":"Opposite current directions cause repulsion between conductors."},{"subject":"physics","q":"The attraction between conductors carrying currents in the same direction occurs because:","options":["The magnetic field between them is weaker than outside","Their masses increase","Their resistance decreases","Voltage becomes zero"],"answer":0,"explanation":"The magnetic fields cancel between the conductors and reinforce outside, causing attraction"},{"subject":"physics","q":"Electromagnetic induction is the production of:","options":["Heat energy","Light energy","E.M.F due to changing magnetic flux","Sound energy"],"answer":2,"explanation":"Electromagnetic induction is the production of an e.m.f whenever there is a change in magnetic flux linking a conductor."},{"subject":"physics","q":"The e.m.f produced by electromagnetic induction is called:","options":["Resistance","Induced e.m.f","Power","Voltage drop"],"answer":1,"explanation":"The voltage produced due to electromagnetic induction is called induced e.m.f."},{"subject":"physics","q":"Which scientist formulated the law relating induced e.m.f to changing magnetic flux?","options":["Newton","Ohm","Faraday","Maxwell"],"answer":2,"explanation":"Faraday\u0027s Law relates induced e.m.f to the rate of change of magnetic flux."},{"subject":"physics","q":"Faraday\u0027s Law states that induced e.m.f is proportional to:","options":["Resistance","Current","Rate of change of magnetic flux","Length of wire only"],"answer":2,"explanation":"The larger the rate of change of magnetic flux, the greater the induced e.m.f."},{"subject":"physics","q":"According to Lenz\u0027s Law, the induced current:","options":["Assists the change producing it","Opposes the change producing it","Stops immediately","Has no direction"],"answer":1,"explanation":"Lenz\u0027s Law states that induced current opposes the change causing it."},{"subject":"physics","q":"Which factor affects the magnitude of induced e.m.f?","options":["Strength of magnetic field","Speed of motion","Area of conductor in the field","All of the above"],"answer":3,"explanation":"Faraday\u0027s Law states that all these factors influence induced e.m.f."},{"subject":"physics","q":"Self-induction occurs when:","options":["One coil induces a current in another coil","A conductor induces e.m.f in itself","A battery charges itself","A magnet attracts iron"],"answer":1,"explanation":"Self-induction occurs when a changing current creates an e.m.f in the same conductor."},{"subject":"physics","q":"The induced voltage in self-induction is often called:","options":["Forward e.m.f","Electric field","Back e.m.f","Static voltage"],"answer":2,"explanation":"Self-induction produces a back e.m.f that opposes the original current change."},{"subject":"physics","q":"When current in a coil increases, the induced current:","options":["Supports the increase","Opposes the increase","Becomes zero","Reverses permanently"],"answer":1,"explanation":"The induced current opposes changes in current according to Lenz\u0027s Law."},{"subject":"physics","q":"Mutual induction occurs when:","options":["A magnet rotates","Two batteries are connected","A changing current in one coil induces current in another coil","A resistor heats up"],"answer":2,"explanation":"Mutual induction involves two nearby coils."},{"subject":"physics","q":"In mutual induction, the coil with changing current is called the:","options":["Secondary coil","Primary coil","Solenoid","Armature"],"answer":1,"explanation":"The primary coil produces the changing magnetic field."},{"subject":"physics","q":"The coil in which current is induced is called the:","options":["Primary coil","Motor coil","Secondary coil","Field coil"],"answer":2,"explanation":"The secondary coil receives the induced current."},{"subject":"physics","q":"An induction coil is used to produce:","options":["Low-voltage DC","High-voltage AC from low-voltage DC","Mechanical energy","Heat energy only"],"answer":1,"explanation":"An induction coil transforms low-voltage DC into high-voltage AC."},{"subject":"physics","q":"An induction coil consists of:","options":["One coil only","Two coils wound on an iron core","Two magnets only","One battery and one coil"],"answer":1,"explanation":"It contains a primary and secondary coil wound on an iron core."},{"subject":"physics","q":"The secondary coil in an induction coil usually has:","options":["Fewer turns than the primary","Equal turns to the primary","More turns than the primary","No turns"],"answer":2,"explanation":"Thousands of turns help produce very high voltages."},{"subject":"physics","q":"One application of an induction coil is in:","options":["Refrigerators only","Ignition systems of vehicles","Water pumps only","Thermometers"],"answer":1,"explanation":"Induction coils are used in internal combustion engine ignition systems."},{"subject":"physics","q":"A generator works based on:","options":["Reflection","Electromagnetic induction","Gravity","Refraction"],"answer":1,"explanation":"Generators convert mechanical energy into electrical energy through electromagnetic induction."},{"subject":"physics","q":"An A.C. generator uses:","options":["Commutators","Slip rings","Resistors","Capacitors"],"answer":1,"explanation":"Slip rings allow the production of alternating current."},{"subject":"physics","q":"A D.C. generator differs from an A.C. generator because it uses:","options":["A commutator","Slip rings only","Solenoids only","No magnetic field"],"answer":0,"explanation":"The commutator ensures current flows in one direction in the external circuit."},{"subject":"physics","q":"A transformer works on the principle of:","options":["Self-induction only","Mutual induction","Reflection","Electrolysis"],"answer":1,"explanation":"Transformers operate using mutual induction between primary and secondary coils."},{"subject":"physics","q":"A generator is a device that converts:","options":["Electrical energy into mechanical energy","Mechanical energy into electrical energy","Heat energy into light energy","Sound energy into electrical energy"],"answer":1,"explanation":"A generator produces electricity through electromagnetic induction."},{"subject":"physics","q":"An A.C. generator is also called:","options":["Rectifier","Transformer","Alternator","Motor"],"answer":2,"explanation":"An A.C. generator is commonly known as an alternator."},{"subject":"physics","q":"The principle used in generators is:","options":["Reflection","Electromagnetic induction","Refraction","Electrolysis"],"answer":1,"explanation":"Generators operate according to Faraday\u0027s law of electromagnetic induction."},{"subject":"physics","q":"In an A.C generator, the rotating coil is called the:","options":["Transformer","Armature","Rectifier","Solenoid"],"answer":1,"explanation":"The armature consists of insulated wire wound on a soft iron core."},{"subject":"physics","q":"Which component is used in an A.C. generator to transfer current to the external circuit?","options":["Commutator","Slip rings","Resistor","Capacitor"],"answer":1,"explanation":"Slip rings are used in A.C. generators to maintain continuous alternating current output."},{"subject":"physics","q":"A D.C. generator differs from an A.C. generator because it uses:","options":["Slip rings only","A transformer","A commutator","An electromagnet only"],"answer":2,"explanation":"A D.C. generator uses a commutator instead of slip rings."},{"subject":"physics","q":"The function of a commutator is to:","options":["Increase voltage","Reverse connections every half turn","Reduce current","Produce heat"],"answer":1,"explanation":"A commutator reverses the connections so current in the external circuit flows in one direction."},{"subject":"physics","q":"The output of an A.C. generator is:","options":["Constant direct current","Alternating current","Zero current","Pulsating voltage only"],"answer":1,"explanation":"The current periodically reverses direction, producing alternating current."},{"subject":"physics","q":"Carbon brushes in a generator are used to:","options":["Create magnetic fields","Transfer current between rotating and stationary parts","Increase resistance","Reduce voltage"],"answer":1,"explanation":"Carbon brushes provide electrical contact with slip rings or commutators."},{"subject":"physics","q":"A transformer works using:","options":["Self-induction","Reflection","Mutual induction","Conduction"],"answer":2,"explanation":"Transformers operate through mutual induction between two coils."},{"subject":"physics","q":"A transformer can only operate with:","options":["Direct current (DC)","Alternating current (AC)","Static electricity","Sound waves"],"answer":1,"explanation":"Transformers require changing magnetic fields produced by alternating current."},{"subject":"physics","q":"The coil connected to the power source is called the:","options":["Secondary coil","Output coil","Primary coil","Armature"],"answer":2,"explanation":"The primary coil receives electrical energy from the source."},{"subject":"physics","q":"The coil in which voltage is induced is called the:","options":["Primary coil","Secondary coil","Solenoid","Rotor"],"answer":1,"explanation":"The secondary coil receives the induced voltage."},{"subject":"physics","q":"A step-up transformer:","options":["Decreases voltage","Increases voltage","Produces direct current","Decreases frequency"],"answer":1,"explanation":"A step-up transformer increases the output voltage."},{"subject":"physics","q":"For a step-up transformer:","options":["Primary turns \u003e Secondary turns","Primary turns = Secondary turns","Secondary turns \u003e Primary turns","No turns are required"],"answer":2,"explanation":"A larger number of turns in the secondary coil increases voltage."},{"subject":"physics","q":"A step-down transformer:","options":["Increases voltage","Decreases voltage","Produces radio waves","Produces sound energy"],"answer":1,"explanation":"A step-down transformer reduces the output voltage."},{"subject":"physics","q":"For a step-down transformer:","options":["Primary turns \u003e Secondary turns","Secondary turns \u003e Primary turns","Both coils have equal turns only","No secondary coil is needed"],"answer":0,"explanation":"The secondary coil has fewer turns than the primary coil."},{"subject":"physics","q":"The iron core in a transformer serves to:","options":["Increase resistance","Transfer magnetic flux efficiently","Produce direct current","Reduce current flow"],"answer":1,"explanation":"The iron core links magnetic flux between the coils."},{"subject":"physics","q":"Which device is commonly used to increase transmission voltage in power stations?","options":["Step-down transformer","Generator","Step-up transformer","Motor"],"answer":2,"explanation":"Step-up transformers increase voltage for efficient power transmission."},{"subject":"physics","q":"Which statement about transformers is correct?","options":["They work with both AC and DC equally","They require mutual induction between two coils","They generate electricity from heat","They work without magnetic fields"],"answer":1,"explanation":"Transformers depend on mutual induction and changing magnetic fields between primary and secondary coils"},{"subject":"physics","q":"An atom is mainly composed of:","options":["Protons, neutrons and electrons","Molecules only","Neutrons only","Electrons only"],"answer":0,"explanation":"Atoms consist of protons, neutrons and electrons."},{"subject":"physics","q":"Which particles are found in the nucleus of an atom?","options":["Electrons only","Protons and neutrons","Electrons and protons","Electrons and neutrons"],"answer":1,"explanation":"The nucleus contains protons and neutrons, while electrons orbit around it."},{"subject":"physics","q":"Which particle has a positive charge?","options":["Electron","Neutron","Proton","Photon"],"answer":2,"explanation":"Protons carry a positive charge."},{"subject":"physics","q":"Which particle has no electric charge?","options":["Proton","Electron","Neutron","Positron"],"answer":2,"explanation":"Neutrons are electrically neutral."},{"subject":"physics","q":"Electrons carry:","options":["Positive charge","Negative charge","Neutral charge","Variable charge"],"answer":1,"explanation":"Electrons are negatively charged particles found outside the nucleus."},{"subject":"physics","q":"The atomic number of an element is equal to the number of:","options":["Neutrons","Electrons and neutrons","Protons","Nucleons"],"answer":2,"explanation":"Atomic number (Z) is defined as the number of protons in the nucleus."},{"subject":"physics","q":"The symbol commonly used for atomic number is:","options":["A","Z","N","M"],"answer":1,"explanation":"Atomic number is represented by the symbol Z."},{"subject":"physics","q":"The mass number of an atom is the total number of:","options":["Protons and neutrons","Electrons and protons","Electrons and neutrons","Electrons only"],"answer":0,"explanation":"Mass number (A) equals the sum of protons and neutrons."},{"subject":"physics","q":"The relationship between mass number (A), atomic number (Z), and neutron number (N) is:","options":["A = Z Ã¢Ë†â€™ N","A = Z + N","A = Z Ãƒâ€” N","A = Z/N"],"answer":1,"explanation":"Mass number equals protons plus neutrons."},{"subject":"physics","q":"In a neutral atom, the number of electrons equals the number of:","options":["Neutrons","Protons","Nucleons","Isotopes"],"answer":1,"explanation":"Neutral atoms have equal numbers of protons and electrons."},{"subject":"physics","q":"Isotopes are atoms that have:","options":["Different atomic numbers but same mass number","Same atomic number but different neutron numbers","Different proton numbers and same neutron numbers","Same mass number only"],"answer":1,"explanation":"Isotopes have the same number of protons but different numbers of neutrons."},{"subject":"physics","q":"Isotopes of an element have:","options":["Different chemical properties","Same chemical properties","Different atomic numbers","Different proton numbers"],"answer":1,"explanation":"Chemical properties depend mainly on electron arrangement, which remains the same for isotopes."},{"subject":"physics","q":"Some isotopes are radioactive because:","options":["Their nuclei are unstable","They have too many electrons","They have no neutrons","They contain no protons"],"answer":0,"explanation":"Radioactive isotopes have unstable nuclei and emit radiation to become stable."},{"subject":"physics","q":"The force that holds the nucleus together is called the:","options":["Gravitational force","Magnetic force","Strong nuclear force","Frictional force"],"answer":2,"explanation":"The strong nuclear force overcomes repulsion between protons and keeps the nucleus intact."},{"subject":"physics","q":"Binding energy is:","options":["The energy holding the nucleus together","Heat produced by an atom","Energy of electrons only","Magnetic energy"],"answer":0,"explanation":"Binding energy is the net energy that keeps the nucleus stable."},{"subject":"physics","q":"A stable atom is one whose nucleus:","options":["Contains no neutrons","Has enough binding energy to hold together","Has more electrons than protons","Continuously emits radiation"],"answer":1,"explanation":"Stable nuclei remain intact because binding energy is sufficient."},{"subject":"physics","q":"An unstable atom is also called a:","options":["Neutral atom","Radioactive atom","Compound atom","Molecular atom"],"answer":1,"explanation":"Unstable nuclei undergo radioactive decay and are called radioactive atoms."},{"subject":"physics","q":"Radioactivity is:","options":["The reflection of waves","The process by which unstable nuclei emit radiation","The formation of isotopes","The movement of electrons"],"answer":1,"explanation":"Radioactivity occurs when unstable nuclei lose energy by emitting radiation."},{"subject":"physics","q":"The atom of Oxygen-16 contains 8 protons. How many neutrons does it contain?","options":["6","8","10","16"],"answer":1,"explanation":"Neutrons = Mass Number Ã¢Ë†â€™ Atomic Number = 16 Ã¢Ë†â€™ 8 = 8."},{"subject":"physics","q":"Which statement about isotopes is correct?","options":["They have different atomic numbers","They always have the same mass number","They have the same number of protons but different numbers of neutrons","They have no neutrons"],"answer":2,"explanation":"This is the correct definition of isotopes"},{"subject":"physics","q":"Radioactive decay is the process by which:","options":["Stable nuclei gain energy","Unstable nuclei lose energy by emitting radiation","Electrons are removed from atoms","Molecules break apart"],"answer":1,"explanation":"Radioactive decay occurs when unstable nuclei emit radiation to become more stable."},{"subject":"physics","q":"Which type of radiation consists of positively charged particles?","options":["Beta rays","Gamma rays","Alpha rays","X-rays"],"answer":2,"explanation":"Alpha particles are positively charged."},{"subject":"physics","q":"Which radioactive radiation has the greatest ionising power?","options":["Alpha rays","Beta rays","Gamma rays","X-rays"],"answer":0,"explanation":"Alpha particles ionise many atoms over a short distance."},{"subject":"physics","q":"Which radiation has the lowest penetrating power?","options":["Gamma rays","Beta rays","Alpha rays","X-rays"],"answer":2,"explanation":"Alpha particles can be stopped by paper or skin."},{"subject":"physics","q":"Beta particles are:","options":["Helium nuclei","Electrons emitted from the nucleus","Protons","Neutrons"],"answer":1,"explanation":"Beta particles are high-energy electrons emitted from radioactive nuclei."},{"subject":"physics","q":"Beta particles carry:","options":["Positive charge","No charge","Negative charge","Variable charge"],"answer":2,"explanation":"Beta particles are negatively charged electrons."},{"subject":"physics","q":"Gamma rays are:","options":["Charged particles","Electrons","Electromagnetic radiation","Helium nuclei"],"answer":2,"explanation":"Gamma rays are highly energetic electromagnetic waves."},{"subject":"physics","q":"Which radiation has the greatest penetrating power?","options":["Alpha rays","Beta rays","Gamma rays","Sound waves"],"answer":2,"explanation":"Gamma rays can penetrate even thick materials."},{"subject":"physics","q":"Which radiation is the least ionising?","options":["Alpha rays","Beta rays","Gamma rays","Neutrons"],"answer":2,"explanation":"Gamma rays have the weakest ionising effect but the highest penetration."},{"subject":"physics","q":"Alpha particles are dangerous mainly when:","options":["They enter the body","They strike paper","They are reflected","They travel in air"],"answer":0,"explanation":"Inside the body, alpha particles can cause serious tissue damage due to strong ionisation."},{"subject":"physics","q":"A Geiger-Muller tube is used to:","options":["Generate radiation","Detect radiation","Increase radiation","Store radiation"],"answer":1,"explanation":"A GM tube detects ionising radiation and converts it into electrical pulses."},{"subject":"physics","q":"The instrument commonly used with a Geiger-Muller tube is called a:","options":["Spectrometer","Geiger Counter","Ammeter","Barometer"],"answer":1,"explanation":"A Geiger Counter measures radioactive emissions using a GM tube."},{"subject":"physics","q":"A cloud chamber is used to:","options":["Measure rainfall","Detect ionising radiation","Produce X-rays","Generate electricity"],"answer":1,"explanation":"A cloud chamber reveals visible tracks of charged radioactive particles."},{"subject":"physics","q":"Which of the following can also detect radiation?","options":["Photographic film","Bubble chamber","Gold-leaf electroscope","All of the above"],"answer":3,"explanation":"All these devices can be used to detect radioactive emissions."},{"subject":"physics","q":"Half-life is the time taken for:","options":["All nuclei to decay","Half the radioactive nuclei to decay","A nucleus to become stable","Radiation to stop completely"],"answer":1,"explanation":"Half-life is the time required for half of the radioactive atoms to decay."},{"subject":"physics","q":"During radioactive decay, the activity of a radioactive sample:","options":["Increases continuously","Remains constant","Decreases with time","Becomes negative"],"answer":2,"explanation":"As radioactive atoms decay, fewer remain to emit radiation."},{"subject":"physics","q":"Radioactive decay is:","options":["Predictable for individual atoms","A random process","Controlled by temperature","Controlled by pressure"],"answer":1,"explanation":"Individual radioactive decays occur randomly."},{"subject":"physics","q":"The count rate of a radioactive source is measured using:","options":["Thermometer","Geiger-Muller tube","Voltmeter","Magnetometer"],"answer":1,"explanation":"The GM tube records the number of radioactive emissions detected."},{"subject":"physics","q":"If a radioactive sample has a half-life of 10 years, after 20 years the remaining amount will be:","options":["1/2","1/4","1/8","3/4"],"answer":1,"explanation":"Two half-lives pass in 20 years, leaving (1/2)Ã‚Â² = 1/4 of the original sample."},{"subject":"physics","q":"Which order correctly shows increasing penetrating power?","options":["Gamma Ã¢â€ â€™ Beta Ã¢â€ â€™ Alpha","Beta Ã¢â€ â€™ Alpha Ã¢â€ â€™ Gamma","Alpha Ã¢â€ â€™ Beta Ã¢â€ â€™ Gamma","Gamma Ã¢â€ â€™ Alpha Ã¢â€ â€™ Beta"],"answer":2,"explanation":"Alpha rays have the least penetrating power, beta rays are intermediate, and gamma rays are the most penetrating."},{"subject":"physics","q":"One medical use of radioactive materials is:","options":["Water purification","Treating cancer","Making plastics","Making magnets"],"answer":1,"explanation":"Radioactive materials such as iodine-131 are used in the treatment of cancer and other diseases."},{"subject":"physics","q":"X-rays are commonly used to:","options":["Detect earthquakes","Examine internal body structures","Measure sound intensity","Generate electricity"],"answer":1,"explanation":"X-rays help doctors detect fractures and other medical conditions."},{"subject":"physics","q":"Carbon-14 dating is used by:","options":["Engineers","Pilots","Archaeologists","Astronomers"],"answer":2,"explanation":"Carbon dating is used to determine the age of fossils and archaeological objects."},{"subject":"physics","q":"Radioactive materials are used in agriculture to:","options":["Produce sound waves","Create new plant varieties","Reduce gravity","Increase rainfall"],"answer":1,"explanation":"Radiation is used to induce mutations and develop disease-resistant crops."},{"subject":"physics","q":"Gamma rays are used in agriculture for:","options":["Sterilising pests","Producing electricity","Measuring mass","Cooling crops"],"answer":0,"explanation":"Gamma radiation can sterilise male pests to control their populations."},{"subject":"physics","q":"Radiation is used in industry mainly for:","options":["Sterilisation and quality control","Producing rainfall","Creating earthquakes","Generating sound"],"answer":0,"explanation":"Radiation helps sterilise equipment and inspect industrial products."},{"subject":"physics","q":"Nuclear power plants generate electricity through:","options":["Reflection of waves","Nuclear fission","Nuclear fusion","Magnetisation"],"answer":1,"explanation":"Electricity in nuclear power plants is generated using nuclear fission."},{"subject":"physics","q":"Which body organ is particularly vulnerable to radioactive iodine?","options":["Liver","Heart","Thyroid gland","Kidney"],"answer":2,"explanation":"The thyroid gland readily absorbs radioactive iodine."},{"subject":"physics","q":"Radiation exposure of about 200 rems may cause:","options":["Improved hearing","Hair loss","Better vision","Stronger bones"],"answer":1,"explanation":"Significant radiation exposure may cause hair loss and other health effects."},{"subject":"physics","q":"Radiation damage to the intestinal tract may result in:","options":["Improved digestion","Nausea and diarrhoea","Increased appetite","Better immunity"],"answer":1,"explanation":"Radiation damage can cause vomiting, nausea and diarrhoea."},{"subject":"physics","q":"Radiation sickness may result from:","options":["Exposure to large doses of ionising radiation","Lack of sunlight","Lack of oxygen","Excessive exercise"],"answer":0,"explanation":"Radiation sickness occurs after exposure to high levels of ionising radiation."},{"subject":"physics","q":"One method of protection against radiation is:","options":["Increasing exposure time","Decreasing distance from the source","Shielding with lead","Removing magnetic fields"],"answer":2,"explanation":"Lead aprons and shields reduce radiation exposure."},{"subject":"physics","q":"Increasing distance from a radiation source:","options":["Increases exposure","Decreases exposure","Has no effect","Produces radiation"],"answer":1,"explanation":"Radiation intensity decreases as distance from the source increases."},{"subject":"physics","q":"Nuclear fission is:","options":["Joining small nuclei together","Splitting a heavy nucleus into smaller nuclei","Reflection of radiation","Emission of electrons only"],"answer":1,"explanation":"Fission occurs when a large nucleus splits into smaller nuclei and releases energy."},{"subject":"physics","q":"Nuclear fusion is:","options":["Splitting nuclei","Combining light nuclei to form a heavier nucleus","Converting neutrons into protons","Producing gamma rays only"],"answer":1,"explanation":"Fusion involves the joining of light nuclei and releases enormous energy."},{"subject":"physics","q":"Which process powers the Sun?","options":["Nuclear fission","Nuclear fusion","Radioactive decay","Ionisation"],"answer":1,"explanation":"The Sun produces energy through nuclear fusion reactions."},{"subject":"physics","q":"Nuclear fission is used in:","options":["Nuclear power stations","Sound production","Light reflection","Water purification only"],"answer":0,"explanation":"Nuclear reactors generate electricity using controlled fission reactions."},{"subject":"physics","q":"Nuclear fusion can be used:","options":["To produce electricity in fusion power plants","To reduce gravity","To produce sound waves","To purify water only"],"answer":0,"explanation":"Fusion has potential applications in power generation."},{"subject":"physics","q":"Which process produces hydrogen bombs?","options":["Reflection","Nuclear fusion","Conduction","Refraction"],"answer":1,"explanation":"Hydrogen bombs derive their tremendous energy from fusion reactions."},{"subject":"physics","q":"Which statement correctly compares nuclear fission and fusion?","options":["Both involve splitting nuclei","Fission splits nuclei while fusion joins nuclei","Fusion splits nuclei while fission joins nuclei","They are exactly the same process"],"answer":1,"explanation":"Fission breaks apart heavy nuclei, whereas fusion combines lighter nuclei into heavier ones"},{"subject":"physics","q":"Thermionic emission is the:","options":["Emission of protons from a cold metal","Emission of electrons from a heated material","Reflection of electrons","Emission of neutrons from a metal"],"answer":1,"explanation":"Thermionic emission is the release of electrons from a heated material."},{"subject":"physics","q":"Thermionic emission was first observed by:","options":["Isaac Newton","Albert Einstein","Thomas Edison","Faraday"],"answer":2,"explanation":"Thomas Edison first observed thermionic emission in 1883."},{"subject":"physics","q":"The Edison Effect refers to:","options":["Reflection of light","Thermionic emission","Nuclear fission","Electromagnetic induction"],"answer":1,"explanation":"Thermionic emission is also known as the Edison Effect."},{"subject":"physics","q":"Cathode rays are streams of:","options":["Protons","Neutrons","Electrons","Alpha particles"],"answer":2,"explanation":"Cathode rays are beams of fast-moving electrons."},{"subject":"physics","q":"Cathode rays are emitted from the:","options":["Anode","Cathode","Grid","Collector"],"answer":1,"explanation":"Cathode rays originate from the negative electrode called the cathode."},{"subject":"physics","q":"Electrons in a cathode ray tube move from:","options":["Anode to cathode","Cathode to anode","Grid to cathode","Earth to cathode"],"answer":1,"explanation":"Electrons are repelled by the cathode and attracted to the anode."},{"subject":"physics","q":"Cathode rays travel:","options":["In curved lines naturally","In straight lines","Around circles","Randomly"],"answer":1,"explanation":"Cathode rays travel in straight lines and cast shadows."},{"subject":"physics","q":"J. J. Thomson discovered that cathode rays are composed of:","options":["Protons","Neutrons","Electrons","Gamma rays"],"answer":2,"explanation":"Thomson identified cathode rays as negatively charged particles called electrons."},{"subject":"physics","q":"Cathode rays are:","options":["Positively charged","Negatively charged","Neutral","Sometimes charged"],"answer":1,"explanation":"Cathode rays consist of negatively charged electrons."},{"subject":"physics","q":"Evidence that cathode rays carry energy is that they:","options":["Produce sound","Move a paddle wheel","Produce magnets","Create gravity"],"answer":1,"explanation":"Cathode rays can turn a paddle wheel, showing they possess momentum and energy."},{"subject":"physics","q":"Cathode rays are deflected by:","options":["Magnetic fields","Electric fields","Both A and B","Neither A nor B"],"answer":2,"explanation":"Because electrons are charged, electric and magnetic fields can deflect them."},{"subject":"physics","q":"When cathode rays strike glass, they produce:","options":["Radiation sickness","Fluorescence","Radioactivity","Sound"],"answer":1,"explanation":"The glass glows due to fluorescence caused by cathode rays."},{"subject":"physics","q":"Cathode rays can:","options":["Penetrate thin metallic sheets","Travel through thick walls easily","Remove gravity","Produce earthquakes"],"answer":0,"explanation":"Cathode rays can pass through thin metal foils."},{"subject":"physics","q":"Cathode rays ionise:","options":["Solids only","Liquids only","Gases","Vacuum"],"answer":2,"explanation":"Cathode rays ionise gases through which they travel."},{"subject":"physics","q":"X-rays can be produced when cathode rays strike:","options":["Certain metals","Water","Plastic","Air only"],"answer":0,"explanation":"Cathode rays striking certain metals generate X-rays."},{"subject":"physics","q":"Cathode rays travel at speeds:","options":["Much slower than sound","Equal to sound","Nearly equal to the speed of light","Zero"],"answer":2,"explanation":"Cathode rays move at extremely high speeds, approaching the speed of light."},{"subject":"physics","q":"A Cathode Ray Tube (CRT) was commonly used in:","options":["Old television sets","Refrigerators","Microwaves","Electric kettles"],"answer":0,"explanation":"CRTs were the display technology used in older televisions and monitors."},{"subject":"physics","q":"A Colour CRT television uses:","options":["One electron gun","Two electron guns","Three electron guns","Four electron guns"],"answer":2,"explanation":"Colour CRT televisions use red, green and blue electron guns."},{"subject":"physics","q":"A Cathode Ray Oscilloscope (CRO) is used to:","options":["Measure voltage changes visually","Produce X-rays","Generate radio waves","Measure mass"],"answer":0,"explanation":"A CRO allows voltage signals to be displayed and analysed."},{"subject":"physics","q":"Which statement about cathode rays is correct?","options":["They are positively charged particles","They are neutral waves","They consist of electrons emitted from the cathode","They cannot be affected by magnetic fields"],"answer":2,"explanation":"Cathode rays are streams of electrons emitted from the cathode in a vacuum tube"},{"subject":"physics","q":"X-rays are a form of:","options":["Sound waves","Electromagnetic radiation","Mechanical waves","Matter waves"],"answer":1,"explanation":"X-rays are electromagnetic radiation with very short wavelengths."},{"subject":"physics","q":"X-rays were discovered by:","options":["J.J. Thomson","Isaac Newton","Wilhelm RÃƒÂ¶ntgen","Faraday"],"answer":2,"explanation":"X-rays are often called RÃƒÂ¶ntgen rays after their discoverer, Wilhelm RÃƒÂ¶ntgen."},{"subject":"physics","q":"An X-ray tube contains:","options":["A cathode and an anode","Two cathodes","Two anodes","A resistor and a coil"],"answer":0,"explanation":"An X-ray tube consists of a cathode that emits electrons and an anode that serves as the target."},{"subject":"physics","q":"The cathode in an X-ray tube is usually:","options":["Heated to emit electrons","Cooled continuously","Made of plastic","Neutral"],"answer":0,"explanation":"The cathode filament is heated, causing thermionic emission of electrons."},{"subject":"physics","q":"Electrons are accelerated towards the:","options":["Cathode","Anode","Vacuum","Filament"],"answer":1,"explanation":"A high potential difference accelerates electrons from the cathode to the anode."},{"subject":"physics","q":"X-rays are produced when:","options":["Electrons strike the anode target","Sound waves hit metal","Radiations collide with air","Water is heated"],"answer":0,"explanation":"X-rays are generated when fast-moving electrons suddenly decelerate on striking the anode."},{"subject":"physics","q":"Most of the energy of electrons striking the anode is converted into:","options":["Light","Sound","Heat","Magnetism"],"answer":2,"explanation":"Only a small fraction becomes X-rays; most energy is converted into heat."},{"subject":"physics","q":"Hard X-rays have:","options":["Longer wavelengths","Lower frequencies","Shorter wavelengths","Lower energy"],"answer":2,"explanation":"Hard X-rays have shorter wavelengths and higher frequencies."},{"subject":"physics","q":"Soft X-rays have:","options":["Longer wavelengths","Higher energies","Greater penetration","Higher frequencies"],"answer":0,"explanation":"Soft X-rays have longer wavelengths and lower energies."},{"subject":"physics","q":"Which type of X-rays have greater penetrating power?","options":["Soft X-rays","Hard X-rays","Both equal","Neither"],"answer":1,"explanation":"Hard X-rays are more penetrating because they have higher energy."},{"subject":"physics","q":"Hard X-rays are produced by:","options":["Lower accelerating potential","Higher accelerating potential","Lower temperatures only","Weak electric fields"],"answer":1,"explanation":"Higher accelerating voltages produce higher-energy X-rays."},{"subject":"physics","q":"X-rays travel:","options":["In curved paths naturally","In straight lines","Like sound waves","In circular paths"],"answer":1,"explanation":"X-rays travel in straight lines."},{"subject":"physics","q":"X-rays are affected by:","options":["Electric fields","Magnetic fields","Both A and B","Neither A nor B"],"answer":3,"explanation":"X-rays have no charge and are not deflected by electric or magnetic fields."},{"subject":"physics","q":"X-rays can cause:","options":["Fluorescence","Reflection only","Magnetisation only","Sound production"],"answer":0,"explanation":"Certain substances glow when exposed to X-rays."},{"subject":"physics","q":"X-rays can be detected using:","options":["Photographic film","Human ear","Compass","Barometer"],"answer":0,"explanation":"X-rays affect photographic film and can produce images."},{"subject":"physics","q":"X-rays ionise:","options":["Water only","Metals only","Gases","Wood only"],"answer":2,"explanation":"X-rays ionise gases, making them conduct electricity."},{"subject":"physics","q":"One major medical application of X-rays is:","options":["Measuring rainfall","Examining bones","Producing sound waves","Generating electricity"],"answer":1,"explanation":"X-rays are widely used to detect fractures and internal injuries."},{"subject":"physics","q":"X-rays are used in security installations to:","options":["Detect hidden objects","Increase temperature","Produce radio waves","Generate power"],"answer":0,"explanation":"Security scanners use X-rays to inspect luggage and packages."},{"subject":"physics","q":"X-ray crystallography is used to:","options":["Measure sound intensity","Study crystal structures","Detect radio waves","Measure rainfall"],"answer":1,"explanation":"X-ray crystallography helps determine the arrangement of atoms in crystals."},{"subject":"physics","q":"Which statement about X-rays is correct?","options":["They are charged particles","They are mechanical waves","They are electromagnetic waves with high penetrating power","They cannot pass through matter"],"answer":2,"explanation":"X-rays are electromagnetic radiation capable of penetrating many materials"},{"subject":"physics","q":"A conductor is a material that:","options":["Prevents current flow","Allows electric current to flow easily","Produces electricity","Stores electricity"],"answer":1,"explanation":"Conductors allow electric current to flow because they contain free charge carriers."},{"subject":"physics","q":"Which of the following is a good conductor?","options":["Glass","Rubber","Copper","Plastic"],"answer":2,"explanation":"Copper is widely used in electrical wiring because it conducts electricity very well."},{"subject":"physics","q":"An insulator is a material that:","options":["Conducts electricity easily","Prevents significant current flow","Produces electrons","Stores magnetic energy"],"answer":1,"explanation":"Insulators have very high resistance and do not allow current to flow easily."},{"subject":"physics","q":"Which of the following is an insulator?","options":["Aluminium","Copper","Glass","Silver"],"answer":2,"explanation":"Glass is a good electrical insulator."},{"subject":"physics","q":"A semiconductor has conductivity:","options":["Greater than a conductor","Equal to a conductor","Between a conductor and an insulator","Equal to an insulator"],"answer":2,"explanation":"Semiconductors have conductivity values between conductors and insulators."},{"subject":"physics","q":"Which material is commonly used as a semiconductor?","options":["Copper","Silver","Silicon","Plastic"],"answer":2,"explanation":"Silicon is the most widely used semiconductor material."},{"subject":"physics","q":"Another common semiconductor material is:","options":["Germanium","Aluminium","Gold","Iron"],"answer":0,"explanation":"Germanium is also widely used in semiconductor manufacturing."},{"subject":"physics","q":"The conductivity of a metal generally:","options":["Increases with temperature","Decreases with temperature","Remains constant","Becomes zero"],"answer":1,"explanation":"Increased temperature increases atomic vibrations, making it harder for electrons to move."},{"subject":"physics","q":"The conductivity of a semiconductor generally:","options":["Decreases with temperature","Remains constant","Increases with temperature","Becomes zero"],"answer":2,"explanation":"Higher temperatures provide energy for more electrons to enter the conduction band."},{"subject":"physics","q":"An intrinsic semiconductor is:","options":["Pure semiconductor material","Metal mixed with plastic","Fully insulated material","Semiconductor containing many impurities"],"answer":0,"explanation":"An intrinsic semiconductor is chemically pure silicon or germanium."},{"subject":"physics","q":"There are two main types of semiconductors:","options":["Conductors and insulators","Intrinsic and extrinsic","Positive and negative","Solid and liquid"],"answer":1,"explanation":"Semiconductors are classified as intrinsic or extrinsic."},{"subject":"physics","q":"Extrinsic semiconductors are produced by:","options":["Heating metals","Cooling insulators","Doping pure semiconductors","Adding water"],"answer":2,"explanation":"Doping introduces impurities to improve conductivity."},{"subject":"physics","q":"Doping is:","options":["Removing impurities","Adding impurities to a semiconductor","Heating a conductor","Cooling a semiconductor"],"answer":1,"explanation":"Doping modifies electrical properties by adding controlled impurities."},{"subject":"physics","q":"Pentavalent impurities create:","options":["P-type semiconductors","N-type semiconductors","Insulators","Conductors"],"answer":1,"explanation":"Pentavalent atoms contribute extra electrons, producing n-type material."},{"subject":"physics","q":"Which of the following is a pentavalent impurity?","options":["Boron","Gallium","Phosphorus","Aluminium"],"answer":2,"explanation":"Phosphorus has five valence electrons and forms n-type semiconductors."},{"subject":"physics","q":"Trivalent impurities create:","options":["N-type semiconductors","Insulators","P-type semiconductors","Metals"],"answer":2,"explanation":"Trivalent impurities create holes and produce p-type semiconductors."},{"subject":"physics","q":"Which of the following is a trivalent impurity?","options":["Phosphorus","Antimony","Arsenic","Boron"],"answer":3,"explanation":"Boron has three valence electrons and produces p-type semiconductors."},{"subject":"physics","q":"In an n-type semiconductor, the majority charge carriers are:","options":["Holes","Protons","Electrons","Neutrons"],"answer":2,"explanation":"N-type semiconductors contain excess free electrons."},{"subject":"physics","q":"In a p-type semiconductor, the majority charge carriers are:","options":["Electrons","Holes","Neutrons","Protons"],"answer":1,"explanation":"Holes act as positive charge carriers in p-type material."},{"subject":"physics","q":"A P-N junction is formed by joining:","options":["Two conductors","Two insulators","P-type and N-type semiconductors","Two metals"],"answer":2,"explanation":"A P-N junction is the foundation of semiconductor devices such as diodes and transistors."},{"subject":"physics","q":"A P-N junction is formed by joining:","options":["Two conductors","Two insulators","P-type and N-type semiconductors","Two metals"],"answer":2,"explanation":"A P-N junction is formed when P-type and N-type semiconductor materials are joined together."},{"subject":"physics","q":"In a P-type semiconductor, the majority carriers are:","options":["Electrons","Holes","Protons","Neutrons"],"answer":1,"explanation":"Holes are the majority charge carriers in P-type material."},{"subject":"physics","q":"In an N-type semiconductor, the majority carriers are:","options":["Holes","Protons","Electrons","Neutrons"],"answer":2,"explanation":"N-type semiconductors have excess free electrons."},{"subject":"physics","q":"When a P-N junction is formed, electrons initially move:","options":["From P-type to N-type","From N-type to P-type","Toward the battery","Toward the cathode"],"answer":1,"explanation":"Electrons diffuse from the N-type side to the P-type side."},{"subject":"physics","q":"Holes initially move:","options":["From N-type to P-type","From P-type to N-type","Through a vacuum","Toward electrons only"],"answer":1,"explanation":"Holes diffuse from the P-type side to the N-type side."},{"subject":"physics","q":"The region around the junction that lacks free charge carriers is called:","options":["Conduction region","Depletion region","Active region","Saturation region"],"answer":1,"explanation":"The depletion region forms near the junction due to diffusion of electrons and holes."},{"subject":"physics","q":"A semiconductor diode contains:","options":["Two P-N junctions","One P-N junction","Three junctions","No junction"],"answer":1,"explanation":"A diode is made from a single P-N junction."},{"subject":"physics","q":"A diode allows current to flow easily when:","options":["Reverse biased","Forward biased","Switched off","Not connected"],"answer":1,"explanation":"In forward bias, current passes through the diode easily."},{"subject":"physics","q":"A diode blocks significant current when:","options":["Forward biased","Reverse biased","Heated","Cooled"],"answer":1,"explanation":"Reverse bias widens the depletion region and blocks current flow."},{"subject":"physics","q":"A diode behaves like a:","options":["Capacitor","Resistor","One-way switch","Transformer"],"answer":2,"explanation":"A diode allows current to pass in one direction only."},{"subject":"physics","q":"The main function of a rectifier is to:","options":["Increase current","Convert AC to DC","Convert DC to AC","Store energy"],"answer":1,"explanation":"Rectifiers are devices that convert alternating current into direct current."},{"subject":"physics","q":"The process of converting AC to DC is called:","options":["Amplification","Rectification","Oscillation","Resonance"],"answer":1,"explanation":"Rectification is the conversion of AC into DC."},{"subject":"physics","q":"A half-wave rectifier uses:","options":["One diode","Two diodes","Four diodes","No diode"],"answer":0,"explanation":"A half-wave rectifier uses a single diode to conduct during one half-cycle."},{"subject":"physics","q":"A half-wave rectifier converts:","options":["Both halves of AC","One half of AC into DC","DC into AC","Heat into electricity"],"answer":1,"explanation":"Only one half of the AC cycle is used."},{"subject":"physics","q":"A full-wave rectifier uses:","options":["One diode only","More than one diode to utilise both halves of AC","No junctions","Only resistors"],"answer":1,"explanation":"A full-wave rectifier converts both positive and negative halves into DC output."},{"subject":"physics","q":"Which type of diode emits light when forward biased?","options":["Photodiode","Zener diode","LED","Tunnel diode"],"answer":2,"explanation":"LED stands for Light Emitting Diode."},{"subject":"physics","q":"Which diode is used to detect light?","options":["LED","Photodiode","Zener diode","Varactor diode"],"answer":1,"explanation":"Photodiodes convert light into electrical signals."},{"subject":"physics","q":"A Zener diode is mainly used for:","options":["Producing light","Detecting sound","Voltage regulation","Producing X-rays"],"answer":2,"explanation":"Zener diodes provide a stable reference voltage."},{"subject":"physics","q":"A laser diode produces:","options":["Sound waves","Coherent light","Radio waves","Gamma rays"],"answer":1,"explanation":"Laser diodes emit coherent and highly focused light."},{"subject":"physics","q":"Which statement about diodes is correct?","options":["Current flows equally in both directions","They contain no semiconductor material","They conduct mainly in one direction","They only work with DC"],"answer":2,"explanation":"The key property of a diode is one-way current conduction."},{"subject":"physics","q":"A transistor is a:","options":["Mechanical device","Semiconductor device","Magnetic device","Optical device"],"answer":1,"explanation":"A transistor is a semiconductor device used for amplification and switching."},{"subject":"physics","q":"A transistor normally has how many terminals?","options":["2","3","4","5"],"answer":1,"explanation":"A transistor has three terminals for connection to a circuit."},{"subject":"physics","q":"The two main types of transistors are:","options":["AC and DC","P and N","Bipolar and Field-Effect Transistors","Conductors and insulators"],"answer":2,"explanation":"Transistors are mainly classified as Bipolar Junction Transistors (BJTs) and Field Effect Transistors (FETs)."},{"subject":"physics","q":"The terminals of a bipolar transistor are:","options":["Gate, Source and Drain","Base, Collector and Emitter","Anode, Cathode and Grid","Positive, Negative and Neutral"],"answer":1,"explanation":"A bipolar transistor has Base, Collector and Emitter terminals."},{"subject":"physics","q":"The terminals of a field-effect transistor are:","options":["Base, Collector and Emitter","Anode, Cathode and Grid","Gate, Source and Drain","Positive, Negative and Neutral"],"answer":2,"explanation":"FETs use Gate, Source and Drain terminals."},{"subject":"physics","q":"A small current at the base controls:","options":["Voltage only","Temperature only","A larger collector current","Resistance only"],"answer":2,"explanation":"The base current controls a much larger collector-emitter current."},{"subject":"physics","q":"The main function of a transistor is:","options":["Reflection of light","Amplification and switching","Heating circuits","Storing charge only"],"answer":1,"explanation":"Transistors are mainly used as amplifiers and switches."},{"subject":"physics","q":"In an NPN transistor, the emitter arrow points:","options":["Inward","Outward","Upward","Downward"],"answer":1,"explanation":"The emitter arrow of an NPN transistor points outward."},{"subject":"physics","q":"In a PNP transistor, the emitter arrow points:","options":["Inward","Outward","Downward","Upward"],"answer":0,"explanation":"The emitter arrow of a PNP transistor points inward."},{"subject":"physics","q":"In an NPN transistor, the collector is usually:","options":["More positive than the emitter","More negative than the emitter","Equal to the emitter","Unconnected"],"answer":0,"explanation":"For normal operation, the collector is more positive than the emitter."},{"subject":"physics","q":"The current gain of a transistor is commonly represented by:","options":["ÃŽÂ»","ÃŽÂ±","ÃŽÂ²","ÃŽÂ¼"],"answer":2,"explanation":"Beta (ÃŽÂ²) is the ratio of collector current to base current."},{"subject":"physics","q":"The ratio Ic/Ib is called:","options":["Alpha","Beta","Gamma","Delta"],"answer":1,"explanation":"Beta represents transistor current gain."},{"subject":"physics","q":"The ratio Ic/Ie is called:","options":["Alpha","Beta","Delta","Omega"],"answer":0,"explanation":"Alpha (ÃŽÂ±) is the ratio of collector current to emitter current."},{"subject":"physics","q":"In a PNP transistor, the emitter is:","options":["More negative than the base","More positive than the base","Equal to the base","Uncharged"],"answer":1,"explanation":"In PNP transistors, the emitter is more positive than the base."},{"subject":"physics","q":"Which transistor uses holes as the major charge carriers?","options":["NPN transistor","PNP transistor","FET only","SCR"],"answer":1,"explanation":"Holes are the major charge carriers in PNP transistors."},{"subject":"physics","q":"Which transistor uses electrons as the major charge carriers?","options":["PNP transistor","NPN transistor","Phototransistor","All equally"],"answer":1,"explanation":"Electrons are the primary charge carriers in NPN transistors."},{"subject":"physics","q":"A transistor can be used as:","options":["A switch","An amplifier","Both A and B","Neither A nor B"],"answer":2,"explanation":"Transistors are widely used for both switching and amplification."},{"subject":"physics","q":"Which device forms the foundation of modern electronic circuits?","options":["Transformer","Resistor","Transistor","Capacitor"],"answer":2,"explanation":"Transistors are the basic building blocks of modern electronics."},{"subject":"physics","q":"Transistors are commonly found in:","options":["Radios","Computers","Televisions","All of the above"],"answer":3,"explanation":"Nearly all electronic devices use transistors."},{"subject":"physics","q":"Which statement about transistors is correct?","options":["They can amplify signals","They are made from semiconductors","They can act as switches","All of the above"],"answer":3,"explanation":"Transistors are semiconductor devices used for amplification and switching in electronic circuits."},{"subject":"physics","q":"An analogue signal is a signal that:","options":["Has only two values","Varies continuously with time","Has no amplitude","Is always constant"],"answer":1,"explanation":"Analogue signals change continuously and can take any value within a range."},{"subject":"physics","q":"A digital signal:","options":["Varies continuously","Has an infinite number of values","Has discrete levels, usually 0 and 1","Cannot transmit information"],"answer":2,"explanation":"Digital signals use discrete values, commonly represented by binary digits 0 and 1."},{"subject":"physics","q":"Which of the following is an example of an analogue signal?","options":["Clock pulse","Binary data","Human voice signal in a microphone","Computer code"],"answer":2,"explanation":"Sound waves picked up by a microphone are continuous and therefore analogue."},{"subject":"physics","q":"Which of the following is an example of a digital signal?","options":["Speech waveform","Temperature variation","Computer data","Sound from a guitar"],"answer":2,"explanation":"Computers process information using digital binary data."},{"subject":"physics","q":"The two binary digits used in digital systems are:","options":["1 and 2","0 and 2","0 and 1","1 and 10"],"answer":2,"explanation":"Digital electronics is based on the binary number system consisting of 0 and 1."},{"subject":"physics","q":"An advantage of digital signals is that they:","options":["Are easily affected by noise","Cannot be stored","Are less affected by noise","Cannot be transmitted"],"answer":2,"explanation":"Digital signals can be regenerated and are more resistant to interference."},{"subject":"physics","q":"Analogue signals are:","options":["More resistant to noise","More easily affected by noise","Always stronger than digital signals","Binary signals"],"answer":1,"explanation":"Analogue signals can be distorted by interference and noise."},{"subject":"physics","q":"The process of converting an analogue signal into a digital signal is called:","options":["Amplification","Rectification","Digitisation","Oscillation"],"answer":2,"explanation":"Digitisation converts continuous analogue signals into digital form."},{"subject":"physics","q":"A transistor amplifier is used to:","options":["Reduce signal strength","Increase signal strength","Produce radiation","Convert AC to DC only"],"answer":1,"explanation":"Amplifiers increase the amplitude of weak electrical signals."},{"subject":"physics","q":"Amplification means:","options":["Decreasing voltage","Increasing signal strength","Stopping current flow","Producing digital signals"],"answer":1,"explanation":"Amplification increases voltage, current or power of a signal."},{"subject":"physics","q":"A single-stage amplifier contains:","options":["One transistor","Two transistors","Three transistors","No transistor"],"answer":0,"explanation":"A single-stage amplifier uses one transistor as the active component."},{"subject":"physics","q":"In a transistor amplifier, the input signal is usually applied to the:","options":["Collector circuit","Base circuit","Power supply","Output terminal"],"answer":1,"explanation":"The signal is applied to the base where it controls a larger collector current."},{"subject":"physics","q":"The amplified output signal is commonly obtained from the:","options":["Base circuit","Battery terminal","Collector circuit","Earth connection"],"answer":2,"explanation":"The collector circuit usually provides the amplified output."},{"subject":"physics","q":"The purpose of biasing a transistor is to:","options":["Switch it off permanently","Establish a suitable operating condition","Reduce amplification to zero","Produce radio waves"],"answer":1,"explanation":"Biasing ensures the transistor operates correctly as an amplifier."},{"subject":"physics","q":"The gain of an amplifier is:","options":["Output signal ÃƒÂ· Input signal","Input signal ÃƒÂ· Output signal","Voltage Ãƒâ€” Current","Current Ã¢Ë†â€™ Voltage"],"answer":0,"explanation":"Gain measures how much the amplifier increases the signal."},{"subject":"physics","q":"A microphone converts:","options":["Electrical energy to sound energy","Sound energy to electrical signals","Heat energy to sound energy","Light energy to sound energy"],"answer":1,"explanation":"Microphones convert sound waves into electrical signals."},{"subject":"physics","q":"A loudspeaker converts:","options":["Electrical signals into sound","Sound into electricity","Heat into electricity","Light into sound"],"answer":0,"explanation":"Loudspeakers convert amplified electrical signals back into sound."},{"subject":"physics","q":"Which device commonly uses amplifier circuits?","options":["Radio receiver","Mobile phone","Television","All of the above"],"answer":3,"explanation":"Amplifiers are essential in most communication and electronic devices."},{"subject":"physics","q":"Digital signals are preferred in modern communication because they:","options":["Cannot carry information","Are highly affected by noise","Can be stored and processed easily","Travel slower than analogue signals"],"answer":2,"explanation":"Digital information can be stored, processed and transmitted efficiently."},{"subject":"physics","q":"Which statement is correct?","options":["Analogue signals have only two levels","Digital signals vary continuously","Single-stage amplifiers use one transistor to increase signal strength","Amplifiers decrease the amplitude of signals"],"answer":2,"explanation":"A single-stage amplifier uses one transistor to amplify weak signals."},{"subject":"physics","q":"Logic gates are electronic circuits used to:","options":["Amplify signals only","Perform logical operations","Produce sound","Generate X-rays"],"answer":1,"explanation":"Logic gates perform decision-making operations using binary inputs and outputs."},{"subject":"physics","q":"Logic gates operate using:","options":["Decimal numbers","Fractions","Binary numbers","Roman numerals"],"answer":2,"explanation":"Logic gates use binary digits 0 and 1 to represent LOW and HIGH states."},{"subject":"physics","q":"A NOT gate has:","options":["Two inputs and one output","One input and one output","Two inputs and two outputs","One input and two outputs"],"answer":1,"explanation":"A NOT gate inverts the input signal."},{"subject":"physics","q":"The output of a NOT gate is:","options":["The same as the input","Opposite to the input","Always 1","Always 0"],"answer":1,"explanation":"A NOT gate changes 1 to 0 and 0 to 1."},{"subject":"physics","q":"If the input of a NOT gate is 1, the output is:","options":["1","2","0","Undefined"],"answer":2,"explanation":"A NOT gate produces the complement of the input."},{"subject":"physics","q":"An AND gate produces an output of 1 only when:","options":["Both inputs are 0","One input is 1","Both inputs are 1","At least one input is 0"],"answer":2,"explanation":"AND gates require all inputs to be HIGH."},{"subject":"physics","q":"The truth table result for an AND gate with inputs 1 and 0 is:","options":["1","0","2","Undefined"],"answer":1,"explanation":"Both inputs must be 1 for the output to be 1."},{"subject":"physics","q":"An OR gate produces an output of 1 when:","options":["All inputs are 0","At least one input is 1","Both inputs are 0","Inputs are equal"],"answer":1,"explanation":"OR gates give a HIGH output if any input is HIGH."},{"subject":"physics","q":"The output of an OR gate with inputs 0 and 0 is:","options":["1","0","2","Undefined"],"answer":1,"explanation":"The OR gate outputs 0 only when all inputs are 0."},{"subject":"physics","q":"NAND means:","options":["NOT-AND","NOT-OR","Negative-Digital","New-AND"],"answer":0,"explanation":"A NAND gate is an AND gate followed by a NOT gate."},{"subject":"physics","q":"A NAND gate gives a LOW output only when:","options":["Both inputs are 0","One input is 1","Both inputs are 1","Inputs are different"],"answer":2,"explanation":"NAND is the inverse of AND."},{"subject":"physics","q":"NOR means:","options":["New-OR","Negative-OR","NOT-OR","Normal-OR"],"answer":2,"explanation":"A NOR gate is an OR gate followed by a NOT gate."},{"subject":"physics","q":"A NOR gate outputs 1 only when:","options":["Both inputs are 1","Both inputs are 0","One input is 1","Inputs differ"],"answer":1,"explanation":"NOR is the inverse of OR."},{"subject":"physics","q":"XOR stands for:","options":["Extra OR","Exclusive OR","External OR","Expanded OR"],"answer":1,"explanation":"XOR means Exclusive OR."},{"subject":"physics","q":"An XOR gate outputs 1 when:","options":["Both inputs are 0","Both inputs are 1","Inputs are different","Inputs are equal"],"answer":2,"explanation":"XOR produces HIGH output when inputs differ."},{"subject":"physics","q":"The output of an XOR gate for inputs 1 and 1 is:","options":["1","0","2","Undefined"],"answer":1,"explanation":"XOR outputs 0 when both inputs are the same."},{"subject":"physics","q":"Which gate is called an inverter?","options":["OR gate","NAND gate","NOT gate","XOR gate"],"answer":2,"explanation":"The NOT gate inverts the logical state."},{"subject":"physics","q":"Which gate can be made by combining an AND gate and a NOT gate?","options":["NOR gate","XOR gate","NAND gate","OR gate"],"answer":2,"explanation":"NAND = AND + NOT."},{"subject":"physics","q":"Which gate can be made by combining an OR gate and a NOT gate?","options":["XOR gate","NAND gate","AND gate","NOR gate"],"answer":3,"explanation":"NOR = OR + NOT."},{"subject":"physics","q":"Which statement is true?","options":["Logic gates use binary inputs and outputs","Logic gates work with decimal numbers only","Logic gates cannot be combined","Logic gates are mechanical devices"],"answer":0,"explanation":"Logic circuits process binary information using logic gates."}];
